def normalize(number_str):
    # Cards are often written in groups separated by spaces or dashes; drop both.
    return number_str.replace(" ", "").replace("-", "")


def luhn_checksum_ok(digits):
    total = 0
    # Walk the digits from right to left so the doubling positions are unambiguous.
    for index, digit in enumerate(reversed(digits)):
        if index % 2 == 1:
            doubled = digit * 2
            # A doubled value above 9 is folded by subtracting 9 (same as summing its digits).
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit
    return total % 10 == 0


def identify_issuer(cleaned):
    # Issuer prefixes are checked on the cleaned string, longest prefix rules first.
    if cleaned.startswith("4"):
        return "Visa"
    if cleaned[:2] in {"51", "52", "53", "54", "55"}:
        return "MasterCard"
    if cleaned[:2] in {"34", "37"}:
        return "Amex"
    return "Unknown"


def validate_credit_card(number_str):
    cleaned = normalize(number_str)
    # Anything that is not a pure digit string of plausible length fails outright.
    if not cleaned.isdigit() or not 13 <= len(cleaned) <= 16:
        return (False, "Unknown")
    issuer = identify_issuer(cleaned)
    digits = [int(character) for character in cleaned]
    return (luhn_checksum_ok(digits), issuer)


def format_report(number_str, result):
    is_valid, issuer = result
    status = "VALID" if is_valid else "INVALID"
    # Keep the original formatting in the report so the user recognises their input.
    return "{:<22} {:<7} {}".format(number_str, status, issuer)


def main():
    samples = [
        "4539 1488 0343 6467",
        "4539-1488-0343-6468",
        "5500 0055 5555 5559",
        "3782 822463 10005",
        "6011 1111 1111 1117",
        "1234",
        "4111 11X1 1111 1111",
    ]
    print("{:<22} {:<7} {}".format("NUMBER", "STATUS", "ISSUER"))
    valid_count = 0
    for sample in samples:
        result = validate_credit_card(sample)
        print(format_report(sample, result))
        # Tally only the cards that passed both the format and the Luhn check.
        if result[0]:
            valid_count += 1
    print("\n{} of {} numbers are valid.".format(valid_count, len(samples)))


if __name__ == "__main__":
    main()

