def validate_throws(throws):
    # every roll is a pin count, so it has to be a small non-negative integer
    if not isinstance(throws, (list, tuple)):
        raise TypeError("throws must be a list of integers")
    for value in throws:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("throws must contain plain integers")
        if value < 0 or value > 10:
            raise ValueError("each throw must knock down between 0 and 10 pins")
    return list(throws)


def frame_scores(throws):
    # ten per-frame scores let a report show the breakdown as well as the total
    rolls = validate_throws(throws)
    scores = []
    index = 0
    for frame in range(10):
        # a frame needs at least one roll of its own before any bonus rolls
        if index >= len(rolls):
            raise ValueError("not enough throws to complete frame %d" % (frame + 1))
        first = rolls[index]
        if first == 10:
            # a strike closes the frame with one roll and scores the next two
            bonus = rolls[index + 1:index + 3]
            if len(bonus) < 2:
                raise ValueError("missing bonus throws after strike in frame %d" % (frame + 1))
            scores.append(10 + sum(bonus))
            index += 1
            continue
        if index + 1 >= len(rolls):
            raise ValueError("frame %d is missing its second throw" % (frame + 1))
        second = rolls[index + 1]
        # two rolls of an open frame cannot exceed the ten standing pins
        if first + second > 10:
            raise ValueError("frame %d knocks down more than 10 pins" % (frame + 1))
        if first + second == 10:
            # a spare adds a single extra roll on top of the ten pins
            if index + 2 >= len(rolls):
                raise ValueError("missing bonus throw after spare in frame %d" % (frame + 1))
            scores.append(10 + rolls[index + 2])
        else:
            scores.append(first + second)
        index += 2
    return scores


def score_bowling(throws):
    return sum(frame_scores(throws))


def format_scorecard(throws):
    scores = frame_scores(throws)
    lines = []
    running = 0
    for number, value in enumerate(scores, start=1):
        # the running total is what a real scorecard prints in each box
        running += value
        lines.append("Frame %2d: %3d  (total %3d)" % (number, value, running))
    return "\n".join(lines)


def main():
    games = {
        "perfect game": [10] * 12,
        "all spares": [5] * 21,
        "gutter game": [0] * 20,
        "mixed game": [1, 4, 4, 5, 6, 4, 5, 5, 10, 0, 1, 7, 3, 6, 4, 10, 2, 8, 6],
    }
    for name, throws in games.items():
        print(name)
        print(format_scorecard(throws))
        print("Final score: %d\n" % score_bowling(throws))


if __name__ == "__main__":
    main()

