OPERATORS = {'+', '-', '*', '/'}
STACK_COMMANDS = {'DUP', 'SWAP', 'DROP'}


def parse_number(token):
    # Convert a token to a float, or return None if it is not numeric
    try:
        return float(token)
    except ValueError:
        # Not a literal: the caller will treat it as an operator or command
        return None


def apply_operator(operator, left, right):
    # Apply a binary arithmetic operator to two operands
    if operator == '+':
        return left + right
    if operator == '-':
        return left - right
    if operator == '*':
        return left * right
    # Division is the only case that can fail on valid numeric input
    if right == 0.0:
        raise ZeroDivisionError('division by zero in RPN expression')
    return left / right


def apply_command(command, stack):
    # Run one of the stack-manipulation commands in place
    if command == 'DUP':
        if not stack:
            raise ValueError('DUP requires at least one item on the stack')
        stack.append(stack[-1])
    elif command == 'SWAP':
        if len(stack) < 2:
            raise ValueError('SWAP requires at least two items on the stack')
        stack[-1], stack[-2] = stack[-2], stack[-1]
    else:
        # DROP: discard the topmost value
        if not stack:
            raise ValueError('DROP requires at least one item on the stack')
        stack.pop()


def evaluate_rpn(expression):
    # Evaluate a space-separated RPN expression and return the single result
    stack = []
    for token in expression.split():
        number = parse_number(token)
        if number is not None:
            stack.append(number)
        elif token in OPERATORS:
            # Operands were pushed in order, so the right one comes off first
            if len(stack) < 2:
                raise ValueError('not enough operands for ' + token)
            right = stack.pop()
            left = stack.pop()
            stack.append(apply_operator(token, left, right))
        elif token in STACK_COMMANDS:
            apply_command(token, stack)
        else:
            raise ValueError('unknown token: ' + token)
    # A well-formed expression leaves exactly one value behind
    if len(stack) != 1:
        raise ValueError('malformed expression: %d values left' % len(stack))
    return stack[0]


def main():
    samples = [
        '3 4 +',
        '5 1 2 + 4 * + 3 -',
        '2 DUP *',
        '10 3 SWAP -',
        '7 8 DROP',
        '1 0 /',
        '2 FOO +',
    ]
    for sample in samples:
        try:
            print('%-24s => %s' % (sample, evaluate_rpn(sample)))
        except (ZeroDivisionError, ValueError) as error:
            # Report bad input instead of aborting the whole run
            print('%-24s => error: %s' % (sample, error))


if __name__ == '__main__':
    main()

