def parse_ipv4(ip_str):
    # Split on dots first; anything other than four parts is not an IPv4 literal
    parts = ip_str.strip().split(".")
    if len(parts) != 4:
        raise ValueError("IPv4 address must have exactly four octets: %r" % ip_str)
    octets = []
    for part in parts:
        # Reject empty fields and things like "1e2" or "+7" that int() would tolerate
        if not part.isdigit():
            raise ValueError("Octet %r is not a decimal number" % part)
        value = int(part)
        if value > 255:
            raise ValueError("Octet %d is out of the 0-255 range" % value)
        octets.append(value)
    return octets


def ip_to_int(ip_str):
    result = 0
    for octet in parse_ipv4(ip_str):
        # Shift the accumulator one byte to the left, then drop the octet in
        result = (result << 8) | octet
    return result


def int_to_ip(value):
    # Peel off one byte at a time, most significant byte first
    return ".".join(str((value >> shift) & 0xFF) for shift in (24, 16, 8, 0))


def cidr_to_mask(cidr):
    if not 0 <= cidr <= 32:
        raise ValueError("CIDR prefix must be between 0 and 32, got %d" % cidr)
    if cidr == 0:
        # A /0 mask is all zeros; the shift below would push bits out of the 32-bit window
        return 0
    return (0xFFFFFFFF << (32 - cidr)) & 0xFFFFFFFF


def usable_hosts(cidr):
    # /31 (point-to-point) and /32 (single host) have no usable host range by the classic rule
    if cidr >= 31:
        return 0
    return (1 << (32 - cidr)) - 2


def subnet_info(ip_str, cidr):
    ip_int = ip_to_int(ip_str)
    mask = cidr_to_mask(cidr)
    # AND with the mask clears every host bit, leaving the network address
    network = ip_int & mask
    # OR with the inverted mask sets every host bit, leaving the broadcast address
    broadcast = ip_int | (~mask & 0xFFFFFFFF)
    return {
        "network": int_to_ip(network),
        "broadcast": int_to_ip(broadcast),
        "hosts": usable_hosts(cidr),
    }


def format_report(ip_str, cidr, info):
    header = "%s/%d" % (ip_str, cidr)
    lines = [header]
    for label in ("network", "broadcast", "hosts"):
        # Pad the labels so the three values line up under the header
        lines.append("  %-10s %s" % (label + ":", info[label]))
    return "\n".join(lines)


def main():
    queries = [
        ("192.168.1.130", 24),
        ("10.0.5.77", 20),
        ("172.16.0.1", 31),
        ("8.8.8.8", 32),
        ("203.0.113.9", 0),
    ]
    for ip_str, cidr in queries:
        info = subnet_info(ip_str, cidr)
        print(format_report(ip_str, cidr, info))
        print()


if __name__ == "__main__":
    main()

