TAX_RATES = {'CA': 0.08, 'NY': 0.07}
FLAT_SHIPPING = 15.00
FREE_SHIPPING_THRESHOLD = 75.00
ELECTRONICS_DISCOUNT = 0.10


def chargeable_quantity(category, quantity):
    # Apparel runs a 'buy 2 get 1 free' promotion: every third unit is free
    if category == 'apparel':
        return quantity - quantity // 3
    return quantity


def unit_price(category, price):
    # Electronics are discounted by 10% before the line total is computed
    if category == 'electronics':
        return price * (1 - ELECTRONICS_DISCOUNT)
    return price


def line_total(item):
    # Category rules touch the quantity and the unit price independently
    quantity = chargeable_quantity(item['category'], item['quantity'])
    return unit_price(item['category'], item['price']) * quantity


def shipping_cost(subtotal):
    # Orders above the threshold ship for free, everything else pays the flat rate
    if subtotal > FREE_SHIPPING_THRESHOLD:
        return 0.00
    return FLAT_SHIPPING


def tax_rate_for(state_code):
    # Unknown or non-taxed states fall back to a zero rate
    return TAX_RATES.get(state_code.upper(), 0.0)


def validate_item(item):
    for key in ('name', 'price', 'category', 'quantity'):
        # A missing key would otherwise surface as an opaque KeyError deep in the maths
        if key not in item:
            raise ValueError("cart item is missing the '%s' key" % key)
    if item['price'] < 0 or item['quantity'] < 0:
        raise ValueError("negative price or quantity for '%s'" % item['name'])


def process_checkout(cart_items, state_code):
    subtotal = 0.0
    for item in cart_items:
        validate_item(item)
        subtotal += line_total(item)
    taxable = subtotal + shipping_cost(subtotal)
    # Tax applies to the goods and the shipping charge together
    return round(taxable * (1 + tax_rate_for(state_code)), 2)


def format_receipt(cart_items, state_code):
    lines = []
    subtotal = 0.0
    for item in cart_items:
        total = line_total(item)
        subtotal += total
        lines.append("  %-12s x%-3d %8.2f" % (item['name'], item['quantity'], total))
    lines.append("  subtotal     %13.2f" % subtotal)
    lines.append("  shipping     %13.2f" % shipping_cost(subtotal))
    # Recomputing via process_checkout keeps the receipt and the charge in sync
    lines.append("  total (%s)   %12.2f" % (state_code, process_checkout(cart_items, state_code)))
    return "\n".join(lines)


def main():
    small_cart = [
        {'name': 'T-Shirt', 'price': 12.50, 'category': 'apparel', 'quantity': 3},
        {'name': 'Mug', 'price': 8.00, 'category': 'kitchen', 'quantity': 2},
    ]
    big_cart = [
        {'name': 'Headphones', 'price': 99.99, 'category': 'electronics', 'quantity': 1},
        {'name': 'Socks', 'price': 5.00, 'category': 'apparel', 'quantity': 7},
    ]
