def validate_inputs(utc_hours, participant_offsets):
    # A meeting needs at least one proposed time and at least one participant
    if not utc_hours:
        raise ValueError("utc_hours must contain at least one proposed hour")
    if not participant_offsets:
        raise ValueError("participant_offsets must contain at least one offset")
    for hour in utc_hours:
        # Proposed times are clock hours, so anything outside 0-23 is meaningless
        if not isinstance(hour, int) or not 0 <= hour <= 23:
            raise ValueError("proposed UTC hours must be integers in 0..23")
    for offset in participant_offsets:
        # Real world offsets run from UTC-12 to UTC+14
        if not isinstance(offset, int) or not -12 <= offset <= 14:
            raise ValueError("offsets must be integers in -12..14")


def local_hour(utc_hour, offset):
    # Modulo keeps the result in 0..23 even for negative sums such as 2 + (-8)
    return (utc_hour + offset) % 24


def is_working_hour(hour):
    # Standard working window, both endpoints inclusive
    return 9 <= hour <= 17


def find_meeting_slot(utc_hours, participant_offsets):
    validate_inputs(utc_hours, participant_offsets)
    for utc_hour in utc_hours:
        # Assume the slot works until a single participant contradicts it
        suitable = True
        for offset in participant_offsets:
            if not is_working_hour(local_hour(utc_hour, offset)):
                suitable = False
                break
        if suitable:
            # Proposals are checked in the given order, so this is the earliest match
            return utc_hour
    return None


def describe_slot(utc_hour, participant_offsets):
    # Build a readable "UTC+9 -> 18:00" fragment for every participant
    parts = []
    for offset in participant_offsets:
        sign = "+" if offset >= 0 else "-"
        label = "UTC{}{}".format(sign, abs(offset))
        parts.append("{} -> {:02d}:00".format(label, local_hour(utc_hour, offset)))
    return ", ".join(parts)


def report(utc_hours, participant_offsets):
    slot = find_meeting_slot(utc_hours, participant_offsets)
    if slot is None:
        # None means every proposal left somebody outside working hours
        return "No proposed time suits all participants."
    return "Meeting at {:02d}:00 UTC ({})".format(
        slot, describe_slot(slot, participant_offsets)
    )


def main():
    teams = [
        ([8, 12, 15, 20], [0, 1, 2]),
        ([2, 6, 10], [-8, 0, 9]),
        ([13, 14], [-5, 3]),
    ]
    for utc_hours, offsets in teams:
        print("Proposals {} for offsets {}".format(utc_hours, offsets))
        # Validation errors are user input problems, not crashes worth a traceback
        try:
            print("  " + report(utc_hours, offsets))
        except ValueError as exc:
            print("  invalid request: {}".format(exc))


if __name__ == "__main__":
    main()

