from collections import deque

# The eight L-shaped offsets a knight can apply to its current square.
KNIGHT_OFFSETS = (
    (1, 2), (2, 1), (2, -1), (1, -2),
    (-1, -2), (-2, -1), (-2, 1), (-1, 2),
)

FILES = "abcdefgh"
RANKS = "12345678"


def parse_square(square):
    # Accept surrounding whitespace and upper-case files such as 'A1'.
    text = square.strip().lower()
    # A legal square is exactly one file letter followed by one rank digit.
    if len(text) != 2:
        raise ValueError("square must be two characters, got %r" % (square,))
    file_char, rank_char = text[0], text[1]
    if file_char not in FILES:
        raise ValueError("file must be a-h, got %r" % (file_char,))
    if rank_char not in RANKS:
        raise ValueError("rank must be 1-8, got %r" % (rank_char,))
    # Files map to x (a -> 0) and ranks map to y (rank 1 -> 0).
    return FILES.index(file_char), int(rank_char) - 1


def format_square(x, y):
    # Inverse of parse_square, used to echo normalised squares when reporting.
    return "%s%d" % (FILES[x], y + 1)


def neighbours(x, y):
    for dx, dy in KNIGHT_OFFSETS:
        nx, ny = x + dx, y + dy
        # Discard moves that leave the 0-7 range on either axis.
        if 0 <= nx <= 7 and 0 <= ny <= 7:
            yield nx, ny


def knight_moves(start_pos, end_pos):
    start = parse_square(start_pos)
    end = parse_square(end_pos)
    # BFS explores squares in order of distance, so the first hit is optimal.
    queue = deque([(start, 0)])
    visited = {start}
    # The knight graph on a full board is connected, so the target is always found.
    while True:
        (x, y), distance = queue.popleft()
        if (x, y) == end:
            return distance
        for step in neighbours(x, y):
            # The visited set keeps the queue finite despite the cyclic move graph.
            if step not in visited:
                visited.add(step)
                queue.append((step, distance + 1))


def main():
    pairs = [("a1", "h8"), ("a1", "b3"), ("d4", "d4"), ("g1", "f3"), ("B1", "a8")]
    for start_pos, end_pos in pairs:
        count = knight_moves(start_pos, end_pos)
        origin = format_square(*parse_square(start_pos))
        target = format_square(*parse_square(end_pos))
        plural = "" if count == 1 else "s"
        print("%s -> %s: %d move%s" % (origin, target, count, plural))


if __name__ == "__main__":
    main()

