def parse_line(line):
    # A usable record needs exactly the four documented fields
    parts = [field.strip() for field in line.split(',')]
    if len(parts) != 4:
        return None
    raw_ts, level, user_id, action = parts
    try:
        timestamp = int(raw_ts)
    except ValueError:
        # Non-integer timestamps make the 60-second comparison meaningless
        return None
    return timestamp, level.upper(), user_id, action.upper()


def brute_force_alert(user_id, timestamp):
    return "Brute Force: user {} reached 3 consecutive FAILED actions at t={}".format(user_id, timestamp)


def compromised_alert(user_id, delta):
    return "Compromised: user {} succeeded {}s after a FAILED action".format(user_id, delta)


def detect_anomalies(log_lines):
    alerts = []
    # Per-user state: how many FAILED in a row and when the last one happened
    failed_streak = {}
    last_failed_ts = {}

    for line in log_lines:
        record = parse_line(line)
        if record is None:
            continue
        timestamp, level, user_id, action = record
        # Informational entries carry no security signal
        if level == 'INFO':
            continue

        if action == 'FAILED':
            failed_streak[user_id] = failed_streak.get(user_id, 0) + 1
            last_failed_ts[user_id] = timestamp
            if failed_streak[user_id] == 3:
                alerts.append(brute_force_alert(user_id, timestamp))
                # Restart the streak so the next three failures alert again
                failed_streak[user_id] = 0
        elif action == 'SUCCESS':
            previous = last_failed_ts.pop(user_id, None)
            # Only a success that directly follows a failure is suspicious
            if previous is not None:
                delta = timestamp - previous
                if delta <= 60:
                    alerts.append(compromised_alert(user_id, delta))
            failed_streak[user_id] = 0

    return alerts


def main():
    log_lines = [
        "100, INFO, alice, LOGIN",
        "110, WARN, bob, FAILED",
        "120, WARN, bob, FAILED",
        "125, INFO, bob, FAILED",
        "130, WARN, bob, FAILED",
        "140, WARN, carol, FAILED",
        "160, WARN, carol, SUCCESS",
        "200, WARN, dave, FAILED",
        "400, WARN, dave, SUCCESS",
        "bad line without fields",
        "xyz, WARN, erin, FAILED",
    ]
    alerts = detect_anomalies(log_lines)
    # bob triggers brute force, carol is compromised, dave's 200s gap is benign
    print("{} alert(s) generated:".format(len(alerts)))
    for alert in alerts:
        print(" -", alert)


if __name__ == '__main__':
    main()

