# Count the living cells among the eight neighbours of (row, col).
def count_live_neighbors(grid, row, col):
    rows = len(grid)
    cols = len(grid[0])
    total = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            # The cell itself is not one of its own neighbours
            if dr == 0 and dc == 0:
                continue
            r = row + dr
            c = col + dc
            # Out-of-bounds positions are treated as permanently dead
            if 0 <= r < rows and 0 <= c < cols:
                total += grid[r][c]
    return total


# Build the next generation of the grid from the survival rules.
def step(grid):
    rows = len(grid)
    cols = len(grid[0])
    nxt = []
    for row in range(rows):
        new_row = []
        for col in range(cols):
            neighbors = count_live_neighbors(grid, row, col)
            if grid[row][col] == 1:
                # A live cell needs exactly two or three live neighbours to survive
                new_row.append(1 if neighbors in (2, 3) else 0)
            else:
                # A dead cell is born only with exactly three live neighbours
                new_row.append(1 if neighbors == 3 else 0)
        nxt.append(new_row)
    return nxt


# Reject anything that is not a rectangular grid of zeros and ones.
def validate(grid):
    if not grid or not grid[0]:
        raise ValueError("grid must contain at least one row and one column")
    width = len(grid[0])
    for row in grid:
        # Ragged input would make neighbour indexing unsafe
        if len(row) != width:
            raise ValueError("all rows must have the same length")
        for cell in row:
            if cell not in (0, 1):
                raise ValueError("cells must be 0 or 1")


# Advance the automaton by ten generations and return the final state.
def simulate(grid):
    validate(grid)
    # Copy the rows so the caller's grid is never mutated
    current = [list(row) for row in grid]
    for _ in range(10):
        current = step(current)
    return current


# Render a grid as text using '#' for live cells and '.' for dead ones.
def format_grid(grid):
    return "\n".join("".join("#" if cell else "." for cell in row) for row in grid)


def main():
    # A glider placed near the top-left corner of a 10x10 field
    field = [[0] * 10 for _ in range(10)]
    for r, c in [(0, 1), (1, 2), (2, 0), (2, 1), (2, 2)]:
        field[r][c] = 1
    print("Initial state:")
    print(format_grid(field))
    result = simulate(field)
    # After ten steps the glider has travelled two cells diagonally
    print("\nAfter 10 steps:")
    print(format_grid(result))
    live = sum(sum(row) for row in result)
    print("\nLiving cells remaining:", live)


if __name__ == "__main__":
    main()

