import sys

# Standard base64 alphabet: uppercase, lowercase, digits, then '+' and '/'.
ALPHABET = (
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "abcdefghijklmnopqrstuvwxyz"
    "0123456789+/"
)

PAD = "="


def _encode_triple(group):
    # Pack a group of 1..3 bytes into a 24-bit integer, most significant byte first.
    packed = 0
    for index in range(3):
        byte = group[index] if index < len(group) else 0
        packed = (packed << 8) | byte

    # Split the 24-bit value into four 6-bit segments, again most significant first.
    segments = [(packed >> shift) & 0x3F for shift in (18, 12, 6, 0)]
    chars = [ALPHABET[segment] for segment in segments]

    # Each missing input byte turns one trailing character into a pad character.
    missing = 3 - len(group)
    for offset in range(missing):
        chars[3 - offset] = PAD
    return "".join(chars)


def encode(data):
    # Accept anything buffer-like (bytes, bytearray, memoryview) but reject text.
    if isinstance(data, str):
        raise TypeError("encode() expects bytes, not str; encode the text first")
    view = bytes(data)

    # Walk the input in three-byte strides; a short final slice pads itself.
    pieces = []
    for start in range(0, len(view), 3):
        pieces.append(_encode_triple(view[start:start + 3]))
    return "".join(pieces)


def encode_lines(data, width=76):
    # MIME transfer encoding wraps the character stream at a fixed line width.
    if width <= 0:
        raise ValueError("width must be a positive number of characters")
    text = encode(data)
    return [text[i:i + width] for i in range(0, len(text), width)]


def main(argv):
    # With no arguments, behave like a filter and encode whatever arrives on stdin.
    if len(argv) <= 1:
        payload = sys.stdin.buffer.read()
    else:
        # Arguments are joined with spaces so that quoting stays optional.
        payload = " ".join(argv[1:]).encode("utf-8")

    for line in encode_lines(payload):
        print(line)
    # An empty input produces no lines at all, which is the correct base64 of b"".
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

