import re

# Matches a run of text enclosed in double asterisks, non-greedy so that
# several bold spans on one line are treated separately.
BOLD_PATTERN = re.compile(r"\*\*(.+?)\*\*")


def emphasize(line):
    """Replace **...** spans with <b>...</b> tags."""
    return BOLD_PATTERN.sub(r"<b>\1</b>", line)


def classify(line):
    """Return the kind of block a single raw line represents."""
    stripped = line.strip()
    # Blank lines only act as separators, they produce no output at all.
    if not stripped:
        return "blank", ""
    if stripped.startswith("# "):
        return "heading", stripped[2:].strip()
    if stripped.startswith("- "):
        return "item", stripped[2:].strip()
    return "paragraph", stripped


def parse(text):
    """Convert the simple markup in *text* into HTML and return it as a string."""
    if not isinstance(text, str):
        raise TypeError("parse() expects a string")

    out = []
    in_list = False
    for raw_line in text.splitlines():
        kind, content = classify(raw_line)
        # Any line that is not a list item terminates an open list.
        if in_list and kind != "item":
            out.append("</ul>")
            in_list = False
        if kind == "heading":
            out.append("<h1>{}</h1>".format(emphasize(content)))
        elif kind == "item":
            # Open the list lazily, on the first item of a consecutive run.
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append("<li>{}</li>".format(emphasize(content)))
        elif kind == "paragraph":
            out.append("<p>{}</p>".format(emphasize(content)))
    # A list running to the very end of the input still needs closing.
    if in_list:
        out.append("</ul>")
    return "".join(out)


def pretty(html):
    """Break the flat HTML string into one tag block per line for display."""
    # Insert a newline before every opening tag except the one starting the string.
    return re.sub(r"(?<!^)<(h1|ul|/ul|li|p)>", r"\n<\1>", html)


def main():
    document = (
        "# Shopping **list**\n"
        "Things I need to buy today:\n"
        "\n"
        "- **Milk**\n"
        "- Bread\n"
        "- Six eggs\n"
        "That is all for now.\n"
    )
    html = parse(document)
    print(pretty(html))
    print("items:", html.count("<li>"))


if __name__ == "__main__":
    main()

