# Consonants that sound alike share a digit; the table drives the whole encoding.
CODES = {
    "B": "1", "F": "1", "P": "1", "V": "1",
    "C": "2", "G": "2", "J": "2", "K": "2", "Q": "2", "S": "2", "X": "2", "Z": "2",
    "D": "3", "T": "3",
    "L": "4",
    "M": "5", "N": "5",
    "R": "6",
}


def normalize(word):
    # Soundex is defined on letters only, so apostrophes, hyphens and spaces are dropped
    letters = "".join(ch for ch in word.upper() if ch.isalpha())
    if not letters:
        raise ValueError("word must contain at least one letter: %r" % (word,))
    return letters


def letter_code(letter):
    # Vowels, Y, H and W have no digit; they are reported as an empty string
    return CODES.get(letter, "")


def soundex(word):
    letters = normalize(word)
    code = [letters[0]]
    # The first letter still contributes its digit as the "previous" value,
    # so a following letter of the same group is swallowed
    previous = letter_code(letters[0])
    for letter in letters[1:]:
        if letter in "HW":
            # H and W are transparent: they neither code nor separate two equal digits
            continue
        digit = letter_code(letter)
        if digit and digit != previous:
            code.append(digit)
            if len(code) == 4:
                break
        # A vowel or Y clears the memory, so the same digit may be emitted again
        previous = digit
    return "".join(code).ljust(4, "0")


def group_by_code(words):
    # Words that sound alike collapse onto the same key
    groups = {}
    for word in words:
        groups.setdefault(soundex(word), []).append(word)
    return groups


def format_report(words):
    width = max(len(w) for w in words)
    lines = ["%-*s -> %s" % (width, word, soundex(word)) for word in words]
    lines.append("")
    for code, family in sorted(group_by_code(words).items()):
        # Only families with more than one member say something about homophones
        if len(family) > 1:
            lines.append("%s: %s" % (code, ", ".join(family)))
    return "\n".join(lines)


def main():
    samples = [
        "Robert", "Rupert", "Rubin", "Ashcraft", "Ashcroft",
        "Tymczak", "Pfister", "Honeyman", "O'Hara", "Lee",
    ]
    print(format_report(samples))


