# Compress a string into a list of integer codes using LZW
def lzw(text):
    # Seed the dictionary with every single-byte character code (0..255)
    table = {chr(code): code for code in range(256)}
    next_code = 256
    sequence = ""
    codes = []
    for char in text:
        candidate = sequence + char
        if candidate in table:
            # The extended sequence is known, so keep growing it
            sequence = candidate
        else:
            # Emit the code for the longest known prefix
            codes.append(table[sequence])
            table[candidate] = next_code
            next_code += 1
            # Restart the sequence with the character that broke the match
            sequence = char
    if sequence:
        # Flush whatever sequence is still pending at end of input
        codes.append(table[sequence])
    return codes


# Rebuild the original text from a list of LZW codes
def lzw_decompress(codes):
    if not codes:
        return ""
    table = {code: chr(code) for code in range(256)}
    next_code = 256
    previous = table[codes[0]]
    pieces = [previous]
    for code in codes[1:]:
        if code in table:
            entry = table[code]
        elif code == next_code:
            # The encoder used the code it defined on this very step
            entry = previous + previous[0]
        else:
            raise ValueError("invalid LZW code stream: %d" % code)
        pieces.append(entry)
        table[next_code] = previous + entry[0]
        next_code += 1
        previous = entry
    return "".join(pieces)


# Ratio of compressed size to original size, assuming 16-bit codes
def compression_ratio(text, codes):
    if not text:
        return 1.0
    # One input character costs 8 bits, one output code costs 16 bits
    return (len(codes) * 16) / (len(text) * 8)


# Compress, verify the stream by round-trip, and print a one-line summary
