# Comprime una cadena en una lista de códigos enteros usando LZW
def lzw(text):
    # Inicializa el diccionario con cada código de carácter de un solo byte (0..255)
    table = {chr(code): code for code in range(256)}
    next_code = 256
    sequence = ""
    codes = []
    for char in text:
        candidate = sequence + char
        if candidate in table:
            # La secuencia extendida es conocida, así que sigue haciéndola crecer
            sequence = candidate
        else:
            # Emite el código para el prefijo conocido más largo
            codes.append(table[sequence])
            table[candidate] = next_code
            next_code += 1
            # Reinicia la secuencia con el carácter que rompió la coincidencia
            sequence = char
    if sequence:
        # Vacía cualquier secuencia que aún esté pendiente al final de la entrada
        codes.append(table[sequence])
    return codes


# Reconstruye el texto original a partir de una lista de códigos LZW
def lzw_decompress(codes):
    if not codes:
        return ""
    table = {code: chr(code) for code in range(256)}
    next_code = 256
    previous = table[codes[0]]
    pieces = [previous]
    for code in codes[1:]:
        if code in table:
            entry = table[code]
        elif code == next_code:
            # El codificador usó el código que definió en este mismo paso
            entry = previous + previous[0]
        else:
            raise ValueError("invalid LZW code stream: %d" % code)
        pieces.append(entry)
        table[next_code] = previous + entry[0]
        next_code += 1
        previous = entry
    return "".join(pieces)


# Proporción del tamaño comprimido al tamaño original, asumiendo códigos de 16 bits
def compression_ratio(text, codes):
    if not text:
        return 1.0
    # Un carácter de entrada cuesta 8 bits, un código de salida cuesta 16 bits
    return (len(codes) * 16) / (len(text) * 8)


# Comprime, verifica el flujo mediante ida y vuelta, e imprime un resumen de una línea
def report(text):
    codes = lzw(text)
    if lzw_decompress(codes) != text:
        raise AssertionError("round-trip failed for %r" % text[:20])
    print("chars=%d codes=%d ratio=%.2f" % (len(text), len(codes), compression_ratio(text, codes)))
    return codes


def main():
    samples = [
        "TOBEORNOTTOBEORTOBEORNOT",
        "banana bandana bandanna",
        "aaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    ]
    for sample in samples:
        codes = report(sample)
        # Muestra solo la cabeza de los flujos largos para mantener la salida legible
        shown = codes if len(codes) <= 12 else codes[:12] + ["..."]
        print("  ", shown)


