VOWELS = "aeiou"
SIBILANT_SUFFIXES = ("s", "x", "z", "ch", "sh")


def _ends_with_sibilant(word):
    # Words hissing at the end need a full "es" syllable to stay pronounceable.
    return word.endswith(SIBILANT_SUFFIXES)


def _pluralize_y_ending(word):
    # The letter before the final y decides between "ies" and a plain "s".
    preceding = word[-2]
    if preceding in VOWELS:
        return word + "s"
    return word[:-1] + "ies"


def _pluralize_f_ending(word):
    # "fe" loses two characters, a bare "f" only one, before "ves" is attached.
    if word.endswith("fe"):
        return word[:-2] + "ves"
    return word[:-1] + "ves"


def pluralize(words):
    plurals = []
    for word in words:
        if not isinstance(word, str):
            raise TypeError("pluralize expects a list of strings")
        # An empty string has no ending to inspect, so no rule can apply.
        if not word:
            raise ValueError("cannot pluralize an empty string")
        if _ends_with_sibilant(word):
            plurals.append(word + "es")
        elif word.endswith("y") and len(word) > 1:
            plurals.append(_pluralize_y_ending(word))
        elif word.endswith("f") or word.endswith("fe"):
            plurals.append(_pluralize_f_ending(word))
        else:
            # Default rule: a single trailing s covers the regular nouns.
            plurals.append(word + "s")
    return plurals


def format_report(words):
    plurals = pluralize(words)
    # Align the arrows by padding every singular to the longest one.
    width = max(len(word) for word in words)
    lines = []
    for singular, plural in zip(words, plurals):
        lines.append("{0:<{1}} -> {2}".format(singular, width, plural))
    return "\n".join(lines)


