        "bus", "box", "buzz", "church", "dish",
        "city", "day", "leaf", "knife", "dog",
    ]
    print(format_report(nouns))
    # A lone "y" keeps the generic rule because there is no preceding letter.
    print(", ".join(pluralize(["y", "sky", "toy"])))
    try:
        pluralize(["cat", ""])
    except ValueError as exc:
        # Report the rejected input instead of letting the driver crash.
        print("error:", exc)


if __name__ == "__main__":
    main()

