import re

# Semitone position of each natural note inside an octave, counting from C.
_NATURAL_SEMITONES = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}

# Octave numbers may be spelled out in words, so keep a small lookup table.
_NUMBER_WORDS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
    "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9,
}

_ACCIDENTALS = {"sharp": 1, "flat": -1, "natural": 0}

A4_FREQUENCY = 440.0
SEMITONE_RATIO = 2.0 ** (1.0 / 12.0)


def parse_note(name):
    # Split a spoken note name into its letter, accidental shift and octave.
    tokens = re.findall(r"[A-Za-z#b0-9]+", name)
    if not tokens:
        raise ValueError("empty note name: %r" % (name,))
    letter = None
    shift = 0
    octave = None
    for token in tokens:
        word = token.lower()
        # "middle" is a synonym for octave four and carries no pitch letter itself.
        if word == "middle":
            octave = 4
        elif word in _ACCIDENTALS:
            shift += _ACCIDENTALS[word]
        elif word in _NUMBER_WORDS:
            octave = _NUMBER_WORDS[word]
        elif word.isdigit():
            octave = int(word)
        elif token.upper() in _NATURAL_SEMITONES:
            letter = token.upper()
        else:
            # Compact spellings such as "F#5" or "Bb3" arrive as a single token.
            head = token[0].upper()
            if head in _NATURAL_SEMITONES and len(token) > 1:
                letter = head
                for char in token[1:]:
                    if char == "#":
                        shift += 1
                    elif char == "b":
                        shift -= 1
                    elif char.isdigit():
                        octave = int(char)
                    else:
                        raise ValueError("unrecognised part %r in %r" % (char, name))
            else:
                raise ValueError("unrecognised word %r in %r" % (token, name))
    if letter is None:
        raise ValueError("no note letter found in %r" % (name,))
    # Without an explicit octave the conventional default is the middle one.
    if octave is None:
        octave = 4
    return letter, shift, octave


def semitones_from_a4(name):
    # Signed number of semitones between the given note and A4.
    letter, shift, octave = parse_note(name)
    absolute = _NATURAL_SEMITONES[letter] + shift + 12 * octave
    # A4 sits nine semitones above C4, which is the reference point here.
    return absolute - (_NATURAL_SEMITONES["A"] + 12 * 4)


def tune(notes):
    # Frequency of each note: 440 Hz scaled by the twelfth root of two.
    return [A4_FREQUENCY * SEMITONE_RATIO ** semitones_from_a4(note) for note in notes]


def main():
    names = ["middle C four", "A four", "F sharp five", "B flat three", "A five"]
    # Pair each name with its pitch so the report lines up in two columns.
    for name, hertz in zip(names, tune(names)):
        print("%-16s %9.3f Hz" % (name, hertz))


if __name__ == "__main__":
    main()

