# Conversion of nested lists / strings / ints / bools into a text representation.
# No json, pickle or other serialization module is used anywhere below.

# Characters that must be prefixed with a backslash inside a quoted string.
_ESCAPES = {'"': '\\"', '\\': '\\\\'}


def escape_text(text):
    # Build the body of a quoted string, replacing quotes and backslashes.
    pieces = []
    for char in text:
        pieces.append(_ESCAPES.get(char, char))
    return "".join(pieces)


def stringify(data):
    # bool must be tested before int, because bool is a subclass of int.
    if isinstance(data, bool):
        return "true" if data else "false"
    if isinstance(data, int):
        return str(data)
    if isinstance(data, str):
        return '"' + escape_text(data) + '"'
    if isinstance(data, list):
        # Each element is converted on its own, then the results are joined.
        return "[" + ",".join(stringify(item) for item in data) + "]"
    raise TypeError("unsupported type: " + type(data).__name__)


def pretty(data, indent=0, step=2):
    # Same conversion, but nested lists are spread over indented lines.
    pad = " " * indent
    if not isinstance(data, list):
        # Scalars never span several lines, so reuse the compact form.
        return pad + stringify(data)
    if not data:
        return pad + "[]"
    inner = [pretty(item, indent + step, step) for item in data]
    # A trailing comma is placed on every line except the last one.
    body = ",\n".join(inner)
    return pad + "[\n" + body + "\n" + pad + "]"


def describe(data):
    # Count the leaves and the maximum nesting depth of a structure.
    if not isinstance(data, list):
        return 1, 0
    leaves = 0
    depth = 0
    for item in data:
        item_leaves, item_depth = describe(item)
        leaves += item_leaves
        # Track the deepest branch seen so far among the children.
        if item_depth > depth:
            depth = item_depth
    return leaves, depth + 1


def main():
    record = [
        "path: C:\\Users\\dev",
        ['say "hello"', True, False],
        [1, [2, [3, -4]]],
        [],
    ]
    print(stringify(record))
    print(pretty(record))
    leaves, depth = describe(record)
    # The report gives a quick sanity check on what was serialized.
    print("leaves={0} depth={1} chars={2}".format(leaves, depth, len(stringify(record))))


if __name__ == "__main__":
    main()

