# Standard letter values, grouped by point worth (Scrabble-style scoring).
LETTER_GROUPS = (
    (1, "AEIOULNRST"),
    (2, "DG"),
    (3, "BCMP"),
    (4, "FHVWY"),
    (5, "K"),
    (8, "JX"),
    (10, "QZ"),
)
LETTER_VALUES = {
    letter: value for value, letters in LETTER_GROUPS for letter in letters
}

# A full rack is seven tiles, and emptying it earns the "bingo" bonus.
RACK_SIZE = 7
BINGO_BONUS = 50


def letter_value(char):
    # Case is irrelevant on a board, so normalise before the lookup.
    key = str(char).upper()
    # Symbols and digits have no defined worth, so scoring them is an error.
    if key not in LETTER_VALUES:
        raise ValueError("no letter value for {!r}".format(char))
    return LETTER_VALUES[key]


def validate(placement):
    if not placement:
        # An empty placement is not a word, so refuse to score it.
        raise ValueError("placement must contain at least one letter")
    for tile in placement:
        # Every tile carries a character plus its two premium factors.
        if len(tile) != 3:
            raise ValueError("each tile needs a char and two multipliers")
        char, letter_mult, word_mult = tile
        if len(str(char)) != 1:
            raise ValueError("each tile holds exactly one character")
        # Multipliers are premium factors; zero or negative makes no sense.
        if letter_mult < 1 or word_mult < 1:
            raise ValueError("multipliers must be at least 1")


def score(placement):
    validate(placement)
    base = 0
    word_factor = 1
    for char, letter_mult, word_mult in placement:
        # Premium squares boost the individual tile before it joins the sum.
        base += letter_value(char) * letter_mult
        # Word multipliers accumulate and apply to the whole word afterwards.
        word_factor *= word_mult
    total = base * word_factor
    if len(placement) == RACK_SIZE:
        # Using all seven tiles adds a flat bonus after every multiplier.
        total += BINGO_BONUS
    return int(total)


def describe(placement):
    # Report the played word, its score and how many premium squares it used.
    word = "".join(str(tile[0]).upper() for tile in placement)
    premiums = sum(1 for _, lm, wm in placement if lm > 1 or wm > 1)
    return "{:<10} {:>4} points ({} premium squares)".format(
        word, score(placement), premiums
    )


def main():
    plain = [(c, 1, 1) for c in "quirky"]
    bingo = [(c, 1, 1) for c in "quartzy"]
    # "z" lands on a double-letter square and the first tile on a triple word.
    premium = [("j", 1, 3), ("a", 1, 1), ("z", 2, 1), ("z", 1, 1)]
    for placement in (plain, bingo, premium):
        print(describe(placement))


if __name__ == "__main__":
    main()

