BASE32 = "0123456789bcdefghjkmnpqrstuvwxyz"
PRECISION = 8
BITS_PER_CHAR = 5


def _validate(coordinate):
    # A plain tuple/list of exactly two items is the only accepted shape
    if not isinstance(coordinate, (tuple, list)) or len(coordinate) != 2:
        raise TypeError("coordinate must be a (latitude, longitude) pair")
    lat, lon = coordinate
    # Booleans are ints in Python, but they are never meaningful coordinates
    if isinstance(lat, bool) or isinstance(lon, bool):
        raise TypeError("latitude and longitude must be real numbers")
    if not isinstance(lat, (int, float)) or not isinstance(lon, (int, float)):
        raise TypeError("latitude and longitude must be real numbers")
    lat, lon = float(lat), float(lon)
    if not -90.0 <= lat <= 90.0:
        raise ValueError("latitude out of range: %r" % lat)
    # Longitude spans twice the latitude interval
    if not -180.0 <= lon <= 180.0:
        raise ValueError("longitude out of range: %r" % lon)
    return lat, lon


def _refine(value, low, high):
    # Emit one bit for value and return the narrowed half-interval
    mid = (low + high) / 2.0
    if value >= mid:
        # Upper half: bit 1, and the lower bound moves up to the midpoint
        return 1, mid, high
    return 0, low, mid


def _interleaved_bits(lat, lon, count):
    lat_low, lat_high = -90.0, 90.0
    lon_low, lon_high = -180.0, 180.0
    for index in range(count):
        # Even positions belong to longitude, odd positions to latitude
        if index % 2 == 0:
            bit, lon_low, lon_high = _refine(lon, lon_low, lon_high)
        else:
            bit, lat_low, lat_high = _refine(lat, lat_low, lat_high)
        yield bit


def encode(coordinate):
    lat, lon = _validate(coordinate)
    # Eight characters of five bits each fix how deep the refinement goes
    bits = _interleaved_bits(lat, lon, PRECISION * BITS_PER_CHAR)
    chars = []
    chunk = 0
    for position, bit in enumerate(bits):
        # Shift the accumulated chunk left and append the new bit
        chunk = (chunk << 1) | bit
        if position % BITS_PER_CHAR == BITS_PER_CHAR - 1:
            chars.append(BASE32[chunk])
            chunk = 0
    return "".join(chars)


def report(places):
    # Column width follows the longest name so the codes line up
    width = max(len(name) for name, _ in places)
    lines = []
    for name, coordinate in places:
        lines.append("%-*s  %s" % (width, name, encode(coordinate)))
    return "\n".join(lines)


if __name__ == "__main__":
    samples = [
        ("Null Island", (0.0, 0.0)),
        ("Nashville", (36.1627, -86.7816)),
        ("Sydney Opera House", (-33.8568, 151.2153)),
        ("South Pole", (-90.0, 0.0)),
    ]
