import math
import re
from typing import List, Tuple


def tokenize(text: str) -> List[str]:
    # Words are lowercase alphanumeric runs, so punctuation never sticks to a token
    return re.findall(r"[a-z0-9']+", text.lower())


def document_frequency(term: str, documents: List[List[str]]) -> int:
    # Count the documents in which the term appears at least once
    return sum(1 for tokens in documents if term in tokens)


def inverse_document_frequency(term: str, documents: List[List[str]]) -> float:
    df = document_frequency(term, documents)
    # A term absent from the whole corpus carries no information at all
    if df == 0:
        return 0.0
    return math.log(len(documents) / df)


def term_frequency(term: str, tokens: List[str]) -> float:
    # An empty document has no length to normalise by
    if not tokens:
        return 0.0
    return tokens.count(term) / len(tokens)


def score(corpus: Tuple[str, List[str]]) -> List[float]:
    target, raw_documents = corpus
    # The target is normalised like the documents, otherwise it could never match
    term_tokens = tokenize(target)
    if len(term_tokens) != 1:
        raise ValueError("the target must be a single word")
    term = term_tokens[0]
    # Without documents there is no total count to build the idf from
    if not raw_documents:
        return []
    documents = [tokenize(doc) for doc in raw_documents]
    idf = inverse_document_frequency(term, documents)
    return [term_frequency(term, tokens) * idf for tokens in documents]


def report(corpus: Tuple[str, List[str]]) -> str:
    target, raw_documents = corpus
    scores = score(corpus)
    # Sort by descending score, keeping the original order as tie-breaker
    ranking = sorted(enumerate(scores), key=lambda pair: (-pair[1], pair[0]))
    lines = ["relevance of %r across %d document(s):" % (target, len(raw_documents))]
    for position, (index, value) in enumerate(ranking, start=1):
        preview = raw_documents[index]
        # Keep the preview short so wide documents do not break the table layout
        if len(preview) > 30:
            preview = preview[:27] + "..."
        lines.append("%2d. [%.4f] %s" % (position, value, preview))
    return "\n".join(lines)


def main() -> None:
    print(score(("apple", ["apple pie", "banana"])))
    news = [
        "Apple released a new phone today.",
        "The banana harvest was poor this year.",
        "Apple stock rose after the apple event.",
    ]
    print(report(("apple", news)))
    # A word shared by every document gets an idf of zero and thus no relevance
    print(score(("the", ["the road", "the sea"])))


if __name__ == "__main__":
    main()

