import math


def dot(u, v):
    # Standard Euclidean dot product of two 3-component vectors
    return u[0] * v[0] + u[1] * v[1] + u[2] * v[2]


def subtract(u, v):
    # Component-wise difference, used to move the ray into sphere-local space
    return (u[0] - v[0], u[1] - v[1], u[2] - v[2])


def intersect(scene):
    origin, direction, center, radius = scene
    # The offset vector puts the sphere at the coordinate origin
    offset = subtract(origin, center)
    a = dot(direction, direction)
    if a == 0.0:
        # A zero-length direction is not a ray, so nothing can ever be hit
        return -1.0
    b = 2.0 * dot(offset, direction)
    c = dot(offset, offset) - radius * radius
    discriminant = b * b - 4.0 * a * c
    if discriminant < 0.0:
        # No real roots: the ray's line passes the sphere completely
        return -1.0
    root = math.sqrt(discriminant)
    near = (-b - root) / (2.0 * a)
    far = (-b + root) / (2.0 * a)
    # The near root is always the smaller one, so test it first
    if near > 0.0:
        return near
    if far > 0.0:
        # The origin lies inside the sphere and we exit at the far root
        return far
    # Both roots are behind the origin, meaning the sphere is in the past
    return -1.0


def point_at(origin, direction, distance):
    # Evaluate the parametric ray equation origin + distance * direction
    return tuple(o + distance * d for o, d in zip(origin, direction))


def describe(scene):
    origin, direction, center, radius = scene
    distance = intersect(scene)
    if distance < 0.0:
        return "ray from %s misses the sphere at %s (r=%g)" % (origin, center, radius)
    hit = point_at(origin, direction, distance)
    # Round the coordinates so accumulated floating point noise stays readable
    pretty = tuple(round(coordinate, 6) for coordinate in hit)
    return "ray from %s hits at distance %g, point %s" % (origin, distance, pretty)


def main():
    scenes = [
        ((0, 0, 0), (0, 0, 1), (0, 0, 5), 1.0),
        # Tangent case: the ray grazes the sphere's surface at a single point
        ((0, 1, 0), (0, 0, 1), (0, 0, 5), 1.0),
        ((0, 3, 0), (0, 0, 1), (0, 0, 5), 1.0),
        # Origin inside the sphere, so only the exit point is in front of us
        ((0, 0, 5), (0, 0, 1), (0, 0, 5), 1.0),
        # Sphere sits behind the origin along the negative direction
        ((0, 0, 0), (0, 0, -1), (0, 0, 5), 1.0),
    ]
    for scene in scenes:
        print(describe(scene))


if __name__ == "__main__":
    main()

