import math
from fractions import Fraction

# Terms smaller than this remainder are treated as exact to avoid blow-up in the reciprocal.
EPSILON = 1e-9

# The task fixes the expansion length at ten extracted terms.
MAX_TERMS = 10


def fraction(number):
    """Return up to ten continued fraction terms of a float."""
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise TypeError("fraction() expects a real number")
    if math.isnan(number) or math.isinf(number):
        # Neither infinities nor NaN have a meaningful integer part to truncate.
        raise ValueError("fraction() needs a finite number")
    terms = []
    value = float(number)
    for _ in range(MAX_TERMS):
        # math.trunc rounds toward zero, which is the required "integer part".
        whole = math.trunc(value)
        terms.append(whole)
        remainder = value - whole
        if abs(remainder) < EPSILON:
            break
        value = 1.0 / remainder
    return terms


def to_fraction(terms):
    """Fold continued fraction terms back into an exact rational number."""
    if not terms:
        raise ValueError("cannot rebuild a number from an empty term list")
    # Start from the innermost term and work outwards, inverting at each step.
    result = Fraction(terms[-1])
    for term in reversed(terms[:-1]):
        result = term + Fraction(1, 1) / result
    return result


def format_expansion(terms):
    """Render terms in the usual [a0; a1, a2, ...] notation."""
    head = str(terms[0])
    tail = ", ".join(str(t) for t in terms[1:])
    if not tail:
        # A single term means the input was already an integer.
        return "[{0}]".format(head)
