import math
from fractions import Fraction

# Los términos menores que este resto se consideran exactos para evitar una explosión en el recíproco.
EPSILON = 1e-9

# La tarea fija la longitud de la expansión en diez términos extraídos.
MAX_TERMS = 10


def fraction(number):
    """Return up to ten continued fraction terms of a float."""
    if isinstance(number, bool) or not isinstance(number, (int, float)):
        raise TypeError("fraction() expects a real number")
    if math.isnan(number) or math.isinf(number):
        # Ni los infinitos ni NaN tienen una parte entera significativa para truncar.
        raise ValueError("fraction() needs a finite number")
    terms = []
    value = float(number)
    for _ in range(MAX_TERMS):
        # math.trunc redondea hacia cero, lo cual es la "parte entera" requerida.
        whole = math.trunc(value)
        terms.append(whole)
        remainder = value - whole
        if abs(remainder) < EPSILON:
            break
        value = 1.0 / remainder
    return terms


def to_fraction(terms):
    """Fold continued fraction terms back into an exact rational number."""
    if not terms:
        raise ValueError("cannot rebuild a number from an empty term list")
    # Empieza desde el término más interno y trabaja hacia afuera, invirtiendo en cada paso.
    result = Fraction(terms[-1])
    for term in reversed(terms[:-1]):
        result = term + Fraction(1, 1) / result
    return result


