    head = str(terms[0])
    tail = ", ".join(str(t) for t in terms[1:])
    if not tail:
        # Un solo término significa que la entrada ya era un entero.
        return "[{0}]".format(head)
    return "[{0}; {1}]".format(head, tail)


def report(number):
    """Build a one-line description of the expansion and its accuracy."""
    terms = fraction(number)
    rebuilt = to_fraction(terms)
    error = abs(float(rebuilt) - number)
    return "{0:>12} -> {1} = {2} (err {3:.2e})".format(
        number, format_expansion(terms), rebuilt, error
    )


def main():
    samples = [3.245, 3.141592653589793, 2.718281828459045, 0.5, -7.0, 1.6180339887]
