def xtime(value):
    # Multiplication by two in GF(2^8): left shift, then reduce if the high bit was set
    shifted = (value << 1) & 0xFF
    if value > 127:
        # The shift pushed out bit 7, so fold in the AES reduction polynomial 0x1B
        shifted ^= 0x1B
    return shifted


def mul3(value):
    # Multiplication by three is (2 * value) XOR value, since 3 == 2 + 1 over GF(2)
    return xtime(value) ^ value


def _check_column(column):
    # The mixing matrix is 4x4, so the input must hold exactly four bytes
    if len(column) != 4:
        raise ValueError("column must contain exactly four integers")
    for index, value in enumerate(column):
        # Booleans are ints in Python but are not meaningful byte values here
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("column[%d] is not an integer" % index)
        if value < 0 or value > 255:
            raise ValueError("column[%d]=%d is outside the byte range" % (index, value))


def mix(column):
    a, b, c, d = column
    _check_column(column)
    # Row 1 of the matrix is [2, 3, 1, 1]
    r0 = xtime(a) ^ mul3(b) ^ c ^ d
    # Row 2 is the same pattern rotated one position to the right
    r1 = a ^ xtime(b) ^ mul3(c) ^ d
    # Row 3 places the doubling coefficient on the third byte
    r2 = a ^ b ^ xtime(c) ^ mul3(d)
    # Row 4 wraps the tripling coefficient back onto the first byte
    r3 = mul3(a) ^ b ^ c ^ xtime(d)
    return [r0, r1, r2, r3]


