import math

KNOTS_TO_KMH = 1.852


def compute_checksum(payload):
    # XOR of every character between '$' and '*' is the NMEA checksum
    checksum = 0
    for char in payload:
        checksum ^= ord(char)
    return checksum


def split_sentence(sentence):
    # A navigation sentence always opens with a dollar sign
    if not sentence.startswith("$"):
        raise ValueError("sentence must start with '$'")
    body = sentence[1:].strip()
    star = body.rfind("*")
    # Without the asterisk there is no checksum to compare against
    if star < 0:
        raise ValueError("sentence has no '*' checksum delimiter")
    payload = body[:star]
    given = body[star + 1:]
    try:
        expected = int(given, 16)
    except ValueError:
        raise ValueError("checksum %r is not hexadecimal" % given)
    if compute_checksum(payload) != expected:
        raise ValueError("checksum mismatch in %r" % sentence)
    # Only now that the data is intact is it worth splitting into fields
    return payload.split(",")


def truncate4(value):
    # Truncate instead of round so 11.516666... is reported as 11.5166
    return math.trunc(value * 10000) / 10000


def dm_to_decimal(raw, hemisphere):
    dot = raw.index(".")
    # The two digits left of the decimal point are whole minutes
    degrees = int(raw[:dot - 2])
    minutes = float(raw[dot - 2:])
    value = degrees + minutes / 60.0
    if hemisphere in ("S", "W"):
        value = -value
    return truncate4(value)


def parse(sentence):
    fields = split_sentence(sentence)
    # Latitude, longitude and speed live in the RMC layout used below
    if not fields[0].endswith("RMC"):
        raise ValueError("expected an RMC sentence, got %r" % fields[0])
    if len(fields) < 8:
        raise ValueError("RMC sentence is truncated")
    # Status 'V' means the receiver reports the fix as void
    if fields[2] != "A":
        raise ValueError("navigation data is flagged as invalid")
    latitude = dm_to_decimal(fields[3], fields[4])
    longitude = dm_to_decimal(fields[5], fields[6])
    # Knots are converted to km/h and kept at two decimals
    speed = round(float(fields[7]) * KNOTS_TO_KMH, 2)
    return latitude, longitude, speed


def format_report(latitude, longitude, speed):
    # Hemisphere letters read better than signed numbers in a report
    ns = "N" if latitude >= 0 else "S"
    ew = "E" if longitude >= 0 else "W"
    return "%.4f%s %.4f%s at %.2f km/h" % (abs(latitude), ns, abs(longitude), ew, speed)


def main():
    sentences = [
        "$GPRMC,123519,A,4807.038,N,01131.000,E,022.4,084.4,230394,003.1,W*6A",
        "$GPRMC,092750,A,5321.6802,S,00630.3372,W,000.0,000.0,120598,,*13",
    ]
    for sentence in sentences:
        try:
            latitude, longitude, speed = parse(sentence)
        except ValueError as error:
            # Bad sentences are common on noisy serial lines, so report and go on
            print("skipped: %s" % error)
            continue
        print(format_report(latitude, longitude, speed))


if __name__ == "__main__":
    main()

