def _validate_token(token, position, buffer_length):
    # Reject anything that is not a tuple before looking at its shape.
    if not isinstance(token, tuple):
        raise TypeError(f"token {position} is not a tuple: {token!r}")
    if len(token) == 1:
        # A one-element token is a literal; only its string form matters.
        return (str(token[0]),)
    if len(token) != 2:
        raise ValueError(f"token {position} must have 1 or 2 elements: {token!r}")
    distance, length = token
    if not (isinstance(distance, int) and isinstance(length, int)):
        raise TypeError(f"back reference {position} needs integers: {token!r}")
    if distance <= 0:
        # Distance is measured backwards from the end, so it must be positive.
        raise ValueError(f"back reference {position} has distance {distance}")
    if length < 0:
        raise ValueError(f"back reference {position} has length {length}")
    if distance > buffer_length:
        # Referring further back than the produced output would read garbage.
        raise ValueError(f"back reference {position} points before the stream start")
    return (distance, length)


def decompress(stream):
    # Characters are collected one by one so back references can read them again.
    buffer = []
    for position, raw in enumerate(stream):
        token = _validate_token(raw, position, len(buffer))
        if len(token) == 1:
            buffer.append(token[0])
            continue
        distance, length = token
        start = len(buffer) - distance
        for offset in range(length):
            # Reading inside the loop lets the copy overlap freshly written data.
            buffer.append(buffer[start + offset])
    return "".join(buffer)


def parse_stream(text):
    # Accepts a compact encoding such as 'A,1:3' and builds the token list.
    tokens = []
    for field in text.split(","):
        field = field.strip()
        if not field:
            raise ValueError("empty field in stream description")
        if ":" in field:
            distance, _, length = field.partition(":")
            tokens.append((int(distance), int(length)))
        else:
            # Anything without a colon is a literal character token.
            tokens.append((field,))
    return tokens


def report(stream):
    text = decompress(stream)
    # Guard against division by zero for an empty stream.
    ratio = len(text) / len(stream) if stream else 0.0
    return f"{len(stream):>3} tokens -> {text!r} (x{ratio:.2f})"


