import re

# A tag is a brace group that contains no braces itself; matching only such
# groups lets us peel nested tags from the inside out.
INNERMOST_TAG = re.compile(r"\{[^{}]*\}")


def strip_tags(text):
    # Repeat until a pass removes nothing, so nested tags vanish inside out.
    while True:
        stripped = INNERMOST_TAG.sub("", text)
        if stripped == text:
            return stripped
        text = stripped


def quote_body(line):
    # Peel every '>' marker, since quotes may be nested several levels deep.
    body = line.lstrip()
    while body.startswith(">"):
        body = body[1:].lstrip()
    return body


def list_body(line):
    # Drop the leading asterisk and the spacing around the item text.
    return line.lstrip()[1:].strip()


def is_quote(line):
    return line.lstrip().startswith(">")


def is_item(line):
    return line.lstrip().startswith("*")


def restructure(lines):
    out = []
    index = 0
    while index < len(lines):
        line = lines[index]
        if is_quote(line):
            parts = []
            # Consume the whole run of quoted lines; empty quotes add nothing.
            while index < len(lines) and is_quote(lines[index]):
                body = quote_body(lines[index])
                if body:
                    parts.append(body)
                index += 1
            out.append(" ".join(parts))
        elif is_item(line):
            # Numbering restarts at one for every separate list block.
            number = 1
            while index < len(lines) and is_item(lines[index]):
                out.append("%d. %s" % (number, list_body(lines[index])))
                number += 1
                index += 1
        else:
            out.append(line.rstrip())
            index += 1
    return out


def squeeze_blanks(lines):
    result = []
    for line in lines:
        # Only skip a blank line when the previous kept line was blank too.
        if not line.strip() and result and not result[-1].strip():
            continue
        result.append(line)
    return result


def clean(text):
    if not isinstance(text, str):
        raise TypeError("clean() expects a string")
    # Tags must go before line analysis, since a tag could otherwise hide
    # the '>' or '*' marker at the start of a line.
    plain = strip_tags(text)
    lines = squeeze_blanks(restructure(plain.splitlines()))
    # Trailing blank lines carry no information in the output document.
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines)


def main():
    document = (
        "{bold}Release notes{/bold}\n"
        "\n"
        "\n"
        "> {italic}Everything{/italic} that changed\n"
        "> in this version.\n"
        "\n"
        "* {code}clean(){/code} added\n"
        "* nested {b}{i}tags{/i}{/b} supported\n"
    )
    print(clean(document))


if __name__ == "__main__":
    main()

