            return stripped
        text = stripped


def quote_body(line):
    # Pelar cada marcador '>', ya que las citas pueden estar anidadas a varios niveles de profundidad.
    body = line.lstrip()
    while body.startswith(">"):
        body = body[1:].lstrip()
    return body


def list_body(line):
    # Eliminar el asterisco inicial y el espaciado alrededor del texto del elemento.
    return line.lstrip()[1:].strip()


def is_quote(line):
    return line.lstrip().startswith(">")


def is_item(line):
    return line.lstrip().startswith("*")


def restructure(lines):
    out = []
    index = 0
    while index < len(lines):
        line = lines[index]
        if is_quote(line):
            parts = []
            # Consumir toda la racha de líneas citadas; las citas vacías no añaden nada.
            while index < len(lines) and is_quote(lines[index]):
                body = quote_body(lines[index])
                if body:
                    parts.append(body)
                index += 1
            out.append(" ".join(parts))
        elif is_item(line):
            # La numeración se reinicia en uno para cada bloque de lista separado.
            number = 1
            while index < len(lines) and is_item(lines[index]):
                out.append("%d. %s" % (number, list_body(lines[index])))
                number += 1
                index += 1
        else:
            out.append(line.rstrip())
            index += 1
    return out


def squeeze_blanks(lines):
    result = []
    for line in lines:
        # Solo omitir una línea en blanco cuando la línea anterior conservada también estaba en blanco.
        if not line.strip() and result and not result[-1].strip():
            continue
        result.append(line)
    return result


def clean(text):
    if not isinstance(text, str):
        raise TypeError("clean() expects a string")
    # Las etiquetas deben ir antes del análisis de líneas, ya que de lo contrario una etiqueta podría ocultar
    # el marcador '>' o '*' al principio de una línea.
    plain = strip_tags(text)
    lines = squeeze_blanks(restructure(plain.splitlines()))
    # Las líneas en blanco finales no aportan información en el documento de salida.
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines)


def main():
    document = (
        "{bold}Release notes{/bold}\n"
        "\n"
        "\n"
        "> {italic}Everything{/italic} that changed\n"
        "> in this version.\n"
        "\n"
        "* {code}clean(){/code} added\n"
        "* nested {b}{i}tags{/i}{/b} supported\n"
    )
    print(clean(document))


if __name__ == "__main__":
    main()

