import random
import math

K = 3


def euclidean(a, b):
    # Straight-line distance between two 2D points
    return math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)


def initial_centers(points):
    # Sampling without replacement keeps the three starting centers distinct
    return [tuple(p) for p in random.sample(points, K)]


def assign(points, centers):
    groups = [[] for _ in range(K)]
    for point in points:
        # Pick the index of the center with the smallest distance to this point
        best = min(range(K), key=lambda i: euclidean(point, centers[i]))
        groups[best].append(list(point))
    return groups


def mean_point(group):
    # The centroid is the average of the x's and the average of the y's
    n = len(group)
    return (sum(p[0] for p in group) / n, sum(p[1] for p in group) / n)


def update_centers(groups, old_centers):
    centers = []
    for index, group in enumerate(groups):
        if group:
            centers.append(mean_point(group))
        else:
            # An empty cluster has no centroid, so its previous center is reused
            centers.append(old_centers[index])
    return centers


def cluster(points):
    if len(points) < K:
        raise ValueError("need at least three points to build three clusters")
    centers = initial_centers(points)
    while True:
        groups = assign(points, centers)
        new_centers = update_centers(groups, centers)
        # Convergence: no center shifted during this pass
        if new_centers == centers:
            return groups
        centers = new_centers


def format_report(groups):
    lines = []
    for index, group in enumerate(groups, start=1):
        # Report the centroid only when the cluster actually holds points
        if group:
            cx, cy = mean_point(group)
            header = "Cluster %d (%d points, center %.2f/%.2f):" % (index, len(group), cx, cy)
        else:
            header = "Cluster %d (empty):" % index
        coords = " ".join("(%.1f,%.1f)" % (p[0], p[1]) for p in group)
        lines.append(header + " " + coords)
    return "\n".join(lines)


def make_blobs(seed):
    rng = random.Random(seed)
    data = []
    # Three well separated blobs so the clustering result is easy to eyeball
    for base_x, base_y in ((0, 0), (10, 10), (0, 12)):
        for _ in range(8):
            data.append([base_x + rng.uniform(-1.5, 1.5), base_y + rng.uniform(-1.5, 1.5)])
    return data


def main():
    random.seed(7)
    points = make_blobs(42)
    print(format_report(cluster(points)))


if __name__ == "__main__":
    main()

