import sys

ROOT = "/"


def split_path(path):
    # Leading and trailing slashes carry no component information, so strip them off.
    parts = [part for part in path.strip("/").split("/") if part]
    if not parts:
        raise ValueError("path %r does not contain a file name" % path)
    # The last component is always the file itself; everything before it is a directory.
    return parts[:-1], parts[-1]


def ancestors(dirs):
    # Every file lives inside the root, so the root always receives the size.
    yield ROOT
    current = ""
    for name in dirs:
        # Each step down the chain builds one more enclosing directory path.
        current = current + "/" + name
        yield current


def rollup(files):
    totals = {}
    for entry in files:
        path, size = entry
        if not isinstance(size, int):
            # Sizes must be summable integers; anything else is a malformed record.
            raise TypeError("size for %r must be an integer" % path)
        if size < 0:
            raise ValueError("size for %r must not be negative" % path)
        dirs, _name = split_path(path)
        for directory in ancestors(dirs):
            # A file's size propagates to its parent and to all higher ancestors.
            totals[directory] = totals.get(directory, 0) + size
    # Sorting keeps the report stable and places parents next to their children.
    return sorted(totals.items())


def format_report(totals):
    lines = []
    for directory, size in totals:
        if directory == ROOT:
            depth = 0
        else:
            # Depth equals the number of separators, which drives the indentation.
            depth = directory.count("/")
        lines.append("%s%s  %d" % ("  " * depth, directory, size))
    return "\n".join(lines)


def main():
    files = [
        ("/usr/bin/python", 5000),
        ("/usr/bin/gcc", 3000),
        ("/usr/lib/libc.so", 12000),
        ("/var/log/syslog", 800),
        ("readme.txt", 120),
    ]
    totals = rollup(files)
    print(format_report(totals))
    # The root entry already holds the sum of every file, so it is the grand total.
    print("total bytes: %d" % dict(totals)[ROOT])
    return 0


if __name__ == "__main__":
    sys.exit(main())

