def parse_row(cells):
    # Lengths of consecutive '#' runs, in the order they appear.
    lengths = []
    run = 0
    for cell in cells:
        if cell == '#':
            # Still inside a filled segment, so extend the current run.
            run += 1
        else:
            if run:
                # A dot closes the segment that was being measured.
                lengths.append(run)
            run = 0
    if run:
        # The row ended while a segment was still open.
        lengths.append(run)
    return lengths


def check_row_syntax(cells):
    # Only '#' and '.' describe a cell; anything else is a malformed row.
    for cell in cells:
        if cell not in '#.':
            raise ValueError("illegal cell %r: rows use only '#' and '.'" % cell)


def check_clues_syntax(clues):
    # Clues count filled cells, so they must be strictly positive integers.
    for clue in clues:
        if not isinstance(clue, int) or isinstance(clue, bool):
            raise TypeError("clue %r is not an integer" % (clue,))
        if clue <= 0:
            raise ValueError("clue %d must be strictly positive" % clue)


def validate(puzzle):
    clues, cells = puzzle
    check_clues_syntax(clues)
    check_row_syntax(cells)
    # Comparing as lists makes both the count and the ordering significant.
    return parse_row(cells) == list(clues)


def describe(puzzle):
    clues, cells = puzzle
    found = parse_row(cells)
    # An empty clue list or an empty row prints as a dash instead of nothing.
    clue_text = ','.join(str(c) for c in clues) or '-'
    found_text = ','.join(str(f) for f in found) or '-'
    verdict = 'OK' if validate(puzzle) else 'BAD'
    return '%-14s clues=%-10s found=%-10s %s' % (cells, clue_text, found_text, verdict)


def main():
    rows = [
        ([3, 1], '###..#...'),
        ([3, 1], '###...#..'),
        ([3, 1], '..###..#.'),
        ([3, 1], '###.#....'),
        ([3, 1], '####.#...'),
        ([3, 1], '###......'),
        ([], '.........'),
        ([1, 1, 1], '#.#.#....'),
    ]
    for row in rows:
        print(describe(row))
    # A malformed row should surface as an error rather than a silent False.
    try:
        validate(([2], '##x.'))
    except ValueError as exc:
        print('rejected:', exc)
    # Same for clues that could never describe a real segment.
    try:
        validate(([0, 2], '..##'))
    except ValueError as exc:
        print('rejected:', exc)


if __name__ == '__main__':
    main()

