import math
import sys
from datetime import date

# Mean length of a synodic month, the standard lunar cycle in days.
LUNAR_CYCLE = 29.5
# Quarter points expressed as a fraction of the cycle.
QUARTER_POINTS = (
    ("new moon", 0.0),
    ("first quarter", 0.25),
    ("full moon", 0.5),
    ("last quarter", 0.75),
)
# Half-width of the window (in days) that still counts as a primary phase.
TOLERANCE_DAYS = 2.0
# A new moon that actually occurred, used as the epoch for date-based runs.
KNOWN_NEW_MOON = date(2000, 1, 6)


def cycle_age(days):
    # Reject booleans explicitly, since they would silently act as 0 and 1.
    if not isinstance(days, (int, float)) or isinstance(days, bool):
        raise TypeError("days must be a number")
    if days < 0:
        # Counting backwards past the reference new moon is not supported.
        raise ValueError("days must not be negative")
    # Only the position inside the current cycle matters, so wrap around.
    return float(days) % LUNAR_CYCLE


def cyclic_gap(age, target):
    gap = abs(age - target)
    # Going the other way round the cycle may be shorter, e.g. day 29 vs day 0.
    return min(gap, LUNAR_CYCLE - gap)


def estimate(days):
    age = cycle_age(days)
    for name, fraction in QUARTER_POINTS:
        # Each quarter point sits at a fixed fraction of the whole cycle.
        if cyclic_gap(age, fraction * LUNAR_CYCLE) <= TOLERANCE_DAYS:
            return name
    # Between the windows, fall back to whichever quarter point is closest.
    best_name = QUARTER_POINTS[0][0]
    best_gap = LUNAR_CYCLE
    for name, fraction in QUARTER_POINTS:
        gap = cyclic_gap(age, fraction * LUNAR_CYCLE)
        if gap < best_gap:
            best_name, best_gap = name, gap
    return best_name


def illuminated_fraction(days):
    # A cosine of the cycle progress approximates the lit share of the disc.
    progress = cycle_age(days) / LUNAR_CYCLE
    return 0.5 * (1.0 - math.cos(2.0 * math.pi * progress))


def format_report(days):
    age = cycle_age(days)
    percent = illuminated_fraction(days) * 100.0
    return "day {:g}: age {:.1f}d, {} ({:.0f}% lit)".format(days, age, estimate(days), percent)


def main(argv):
    if len(argv) > 1:
        # Day counts may be supplied directly on the command line.
        values = [float(arg) for arg in argv[1:]]
    else:
        # With no arguments, report on today relative to the known new moon.
        values = [(date.today() - KNOWN_NEW_MOON).days]
    for days in values:
        print(format_report(days))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

