def tokenize(formula):
    tokens = []
    index = 0
    while index < len(formula):
        char = formula[index]
        # A new element always begins with an uppercase letter
        if not char.isupper():
            raise ValueError("unexpected character %r at position %d" % (char, index))
        symbol = char
        index += 1
        # A single lowercase letter may extend the symbol, as in "Na" or "Cl"
        if index < len(formula) and formula[index].islower():
            symbol += formula[index]
            index += 1
        digits = ""
        # Consume every consecutive digit so multi-digit counts like "12" survive intact
        while index < len(formula) and formula[index].isdigit():
            digits += formula[index]
            index += 1
        # An omitted number means exactly one atom of this element
        count = int(digits) if digits else 1
        tokens.append((symbol, count))
    return tokens


def calculate(formula):
    if not formula:
