    "S": 32.06,
    "Cl": 35.45,
    "K": 39.098,
    "Ca": 40.078,
    "Fe": 55.845,
}


def tokenize(formula):
    tokens = []
    index = 0
    while index < len(formula):
        char = formula[index]
        # Un nuevo elemento siempre comienza con una letra mayúscula
        if not char.isupper():
            raise ValueError("unexpected character %r at position %d" % (char, index))
        symbol = char
        index += 1
        # Una única letra minúscula puede extender el símbolo, como en "Na" o "Cl"
        if index < len(formula) and formula[index].islower():
            symbol += formula[index]
            index += 1
        digits = ""
        # Consumir todos los dígitos consecutivos para que los recuentos de varios dígitos como "12" se mantengan intactos
        while index < len(formula) and formula[index].isdigit():
            digits += formula[index]
            index += 1
        # Un número omitido significa exactamente un átomo de este elemento
        count = int(digits) if digits else 1
        tokens.append((symbol, count))
    return tokens


def calculate(formula):
    if not formula:
        raise ValueError("formula must not be empty")
    total = 0.0
    for symbol, count in tokenize(formula):
        # Los símbolos desconocidos no pueden aportar una masa, así que se rechaza toda la fórmula
        if symbol not in ATOMIC_MASSES:
