CUPS_TO_TABLESPOONS = 16
TABLESPOONS_TO_TEASPOONS = 3


def _validate(recipe):
    original, target, ingredients = recipe
    # Servings of zero or below cannot produce a meaningful scaling factor
    if original <= 0 or target <= 0:
        raise ValueError("servings must be positive numbers")
    for name, amount, unit in ingredients:
        # A negative quantity is not something that can be measured out
        if amount < 0:
            raise ValueError(f"negative amount for ingredient {name!r}")
        if not unit:
            raise ValueError(f"missing unit for ingredient {name!r}")
    return original, target, ingredients


def scaling_factor(original, target):
    # The factor is a plain ratio, kept unrounded to avoid compounding error
    return target / original


def normalise(amount, unit):
    unit = unit.lower()
    # Cups below a quarter read better as tablespoons
    if unit in ("cup", "cups") and amount < 0.25:
        amount *= CUPS_TO_TABLESPOONS
        unit = "tablespoons"
    # The converted value may itself be under one tablespoon, so check again
    if unit in ("tablespoon", "tablespoons") and amount < 1:
        amount *= TABLESPOONS_TO_TEASPOONS
        unit = "teaspoons"
    return amount, unit


def scale(recipe):
    original, target, ingredients = _validate(recipe)
    factor = scaling_factor(original, target)
    scaled = []
    for name, amount, unit in ingredients:
        new_amount, new_unit = normalise(amount * factor, unit)
        # Rounding happens last so the unit conversions use full precision
        scaled.append((name, round(new_amount, 2), new_unit))
    return scaled


