    lines = [f"Scaled from {original} to {target} servings:"]
    for name, amount, unit in scaled:
        # Drop the trailing ".0" so whole numbers look natural in the output
        shown = int(amount) if amount == int(amount) else amount
        lines.append(f"  {name}: {shown} {unit}")
