import re
import sys

# Sentences end at a period, exclamation mark or question mark.
SENTENCE_DELIMITERS = re.compile(r"[.!?]")

# A syllable nucleus is one contiguous run of vowel letters.
VOWEL_GROUPS = re.compile(r"[aeiouy]+")


def split_sentences(text):
    pieces = SENTENCE_DELIMITERS.split(text)
    # Trailing punctuation leaves an empty fragment that is not a sentence.
    return [piece.strip() for piece in pieces if piece.strip()]


def split_words(text):
    # Line and tab breaks act as spaces before the split on single spaces.
    raw = text.replace("\n", " ").replace("\t", " ").split(" ")
    # Repeated spaces produce empty strings which must be discarded.
    return [word for word in raw if word]


def count_syllables_in_word(word):
    # Punctuation attached to a word must not break the vowel runs.
    cleaned = "".join(ch for ch in word.lower() if ch.isalpha() or ch == "'")
    total = len(VOWEL_GROUPS.findall(cleaned))
    # A final e is usually silent, but every word keeps at least one syllable.
    if cleaned.endswith("e") and total > 1:
        total -= 1
    return total


def count_syllables(words):
    return sum(count_syllables_in_word(word) for word in words)


def evaluate(text):
    sentences = split_sentences(text)
    words = split_words(text)
    # Without words or sentences the averages below are undefined.
    if not words or not sentences:
        raise ValueError("text must contain at least one word and one sentence")
    syllables = count_syllables(words)
    words_per_sentence = len(words) / len(sentences)
    syllables_per_word = syllables / len(words)
    # Flesch-Kincaid grade level from the two averages.
    grade = 0.39 * words_per_sentence + 11.8 * syllables_per_word - 15.59
    return round(grade)


def describe(grade):
    # Negative or tiny grades mean the prose is below first-grade difficulty.
    if grade < 1:
        return "kindergarten level"
    if grade > 16:
        return "post-graduate level"
    return "grade {} level".format(grade)


def main(argv):
    # Read the prose from the command line, or from stdin when none is given.
    if len(argv) > 1:
        text = " ".join(argv[1:])
    else:
        text = sys.stdin.read()
    grade = evaluate(text)
    print("Words:     {}".format(len(split_words(text))))
    print("Sentences: {}".format(len(split_sentences(text))))
    print("Grade:     {} ({})".format(grade, describe(grade)))


if __name__ == "__main__":
    main(sys.argv)

