def _validate(moves):
    """Return the moves as a list of ints, rejecting anything unusable."""
    # A string would iterate character by character, so reject non-sequences early.
    if not isinstance(moves, (list, tuple)):
        raise TypeError("moves must be a list or tuple of integers")
    checked = []
    for index, move in enumerate(moves):
        # bool is a subclass of int, but True/False are not meaningful click counts.
        if isinstance(move, bool) or not isinstance(move, int):
            raise TypeError("move at position %d is not an integer" % index)
        checked.append(move)
    return checked


def _forward(rings, clicks):
    """Rotate ring 1 forward, carrying into ring 2 once per full revolution."""
    total = rings[0] + clicks
    # Integer division counts how many times the first ring passed nine.
    revolutions = total // 10
    rings[0] = total % 10
    rings[1] = (rings[1] + revolutions) % 10


def _backward(rings, clicks):
    """Rotate ring 3 backward, pulling ring 4 each time zero is passed."""
    total = rings[2] - clicks
    # Floor division of a negative value already yields the number of borrows.
    borrows = -(total // 10)
    rings[2] = total % 10
    rings[3] = (rings[3] - borrows) % 10


def unlock(moves):
    """Apply every click sequence in order and report the four ring positions."""
    rings = [0, 0, 0, 0]
    for move in _validate(moves):
        # Non-negative values drive the first pair; zero simply leaves it alone.
        if move >= 0:
            _forward(rings, move)
        else:
            _backward(rings, -move)
    return tuple(rings)


def describe(moves):
    """Format a single line showing the moves and the resulting combination."""
    positions = unlock(moves)
    # Join with a separator so the four digits stay readable as a combination.
    combination = "-".join(str(digit) for digit in positions)
    return "%-28s -> %s" % (moves, combination)


def main():
    sequences = [
        [5],
        [12],
        [-1],
        [-23],
        [9, 3, -4, -8, 25],
    ]
    for sequence in sequences:
        print(describe(sequence))


if __name__ == "__main__":
    main()

