CAR_CAPACITY = 100_000


def validate_freight(freight):
    # The manifest may arrive as a list or tuple; anything else is unusable
    if not isinstance(freight, (list, tuple)):
        raise TypeError("freight must be a list of integer weights")
    checked = []
    for index, weight in enumerate(freight):
        # bool is a subclass of int, but True/False are not meaningful weights
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError(f"weight at position {index} is not an integer: {weight!r}")
        if weight < 0:
            raise ValueError(f"weight at position {index} is negative: {weight}")
        checked.append(weight)
    return checked


def load(freight):
    manifest = validate_freight(freight)
    cars = []
    current = []
    current_load = 0
    for weight in manifest:
        # An oversized container can never fit anywhere, so it never boards
        if weight > CAR_CAPACITY:
            continue
        if current_load + weight > CAR_CAPACITY:
            # The current car is full: close it and roll up an empty one
            cars.append(current)
            current = []
            current_load = 0
        current.append(weight)
        current_load += weight
    # The last car is only part of the train if something was actually loaded
    if current:
        cars.append(current)
    return cars


def rejected_containers(freight):
    # Containers heavier than a whole car are skipped by load()
    return [weight for weight in validate_freight(freight) if weight > CAR_CAPACITY]


def format_report(freight):
    cars = load(freight)
    lines = [f"Train of {len(cars)} car(s), capacity {CAR_CAPACITY:,} lb each:"]
    for number, car in enumerate(cars, start=1):
        total = sum(car)
        # Show how much room is left so a dispatcher can squeeze in late arrivals
        slack = CAR_CAPACITY - total
        weights = ", ".join(f"{weight:,}" for weight in car)
        lines.append(f"  Car {number}: {weights} (total {total:,}, free {slack:,})")
    skipped = rejected_containers(freight)
    if skipped:
        lines.append("  Rejected: " + ", ".join(f"{weight:,}" for weight in skipped))
    return "\n".join(lines)


def main():
    shipments = [
        [40_000, 50_000, 30_000, 100_000, 20_000],
        [120_000, 10_000, 95_000, 6_000],
        [],
    ]
    for shipment in shipments:
        print(format_report(shipment))
        # Blank line keeps consecutive shipment reports readable
        print()


if __name__ == "__main__":
    main()

