ELEMENT_BEATS = {
    "water": "fire",
    "fire": "grass",
    "grass": "water",
    "light": "dark",
    "dark": "light",
}


def beats(attacker_element, defender_element):
    # A type only gains an advantage against the single element it counters.
    return ELEMENT_BEATS.get(attacker_element) == defender_element


def compute_damage(attacker, defender):
    _, attack, _, attacker_element = attacker
    _, _, defense, defender_element = defender
    # Defense reduces the blow, but every hit lands for at least one point.
    damage = max(1, attack - defense)
    if beats(attacker_element, defender_element):
        damage *= 2
    return damage


def validate_fighter(fighter):
    if len(fighter) != 4:
        raise ValueError("a combatant needs health, attack, defense and element")
    health, attack, defense, element = fighter
    # Numeric stats must be real numbers; a negative starting health is nonsense.
    for value in (health, attack, defense):
        if not isinstance(value, (int, float)):
            raise TypeError("health, attack and defense must be numeric")
    if health <= 0:
        raise ValueError("a combatant must start with positive health")
    if not isinstance(element, str):
        raise TypeError("the elemental type must be a string")
    # Elements are compared case-insensitively, so normalise them here.
    return (health, attack, defense, element.strip().lower())


def clash(fighters):
    if len(fighters) != 2:
        raise ValueError("exactly two combatants are required")
