import math

EARTH_RADIUS_M = 6_371_000.0

CLIMB_FACTOR = 1.2
DESCENT_FACTOR = 0.8


def _validate(waypoints):
    """Check that the input really is a sequence of (lat, lon, alt) triples."""
    if not isinstance(waypoints, (list, tuple)):
        raise TypeError("waypoints must be a list of (lat, lon, alt) tuples")
    cleaned = []
    for index, point in enumerate(waypoints):
        # Each waypoint must expose exactly three numeric components.
        if len(point) != 3:
            raise ValueError("waypoint %d does not have three components" % index)
        lat, lon, alt = (float(value) for value in point)
        # Latitude outside the poles and longitude beyond the date line are meaningless.
        if not -90.0 <= lat <= 90.0:
            raise ValueError("waypoint %d has latitude out of range" % index)
        if not -180.0 <= lon <= 180.0:
            raise ValueError("waypoint %d has longitude out of range" % index)
        cleaned.append((lat, lon, alt))
    return cleaned


def _surface_distance(first, second):
    """Great-circle distance in metres between two points, ignoring altitude."""
    lat1, lon1 = math.radians(first[0]), math.radians(first[1])
    lat2, lon2 = math.radians(second[0]), math.radians(second[1])
    delta_lat = lat2 - lat1
    delta_lon = lon2 - lon1
    # Standard haversine expression, numerically stable for short legs.
    haversine = math.sin(delta_lat / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin(delta_lon / 2) ** 2
    return 2 * EARTH_RADIUS_M * math.asin(math.sqrt(haversine))


def _segment_distance(first, second):
    """Straight line length of one leg, combining ground track and height change."""
    ground = _surface_distance(first, second)
    climb = second[2] - first[2]
    # Pythagoras turns the ground track and the vertical offset into a slant range.
    return math.hypot(ground, climb)


def route(waypoints):
    """Total flight distance in metres, penalising climbs and rewarding descents."""
    points = _validate(waypoints)
    total = 0.0
    for first, second in zip(points, points[1:]):
        distance = _segment_distance(first, second)
        if second[2] > first[2]:
            # Gaining altitude burns extra fuel, so the leg counts for more.
            distance *= CLIMB_FACTOR
        elif second[2] < first[2]:
            # Descending glides part of the way, so the leg counts for less.
            distance *= DESCENT_FACTOR
        total += distance
    return round(total)


def describe(name, waypoints):
    """Build a one-line human readable summary of a named flight plan."""
    metres = route(waypoints)
    # Kilometres read better than raw metres in a report.
    return "%-12s %2d waypoints %10.1f km" % (name, len(waypoints), metres / 1000.0)


def main():
    plans = {
        "shorthop": [(52.3105, 4.7683, 0.0), (52.6500, 5.2000, 3000.0), (53.1200, 6.5800, 0.0)],
        "transalp": [(45.6306, 8.7281, 200.0), (46.5000, 9.5000, 8000.0),
                     (47.2600, 11.3400, 8000.0), (48.3538, 11.7861, 450.0)],
        "single": [(51.4700, -0.4543, 25.0)],
    }
    for name in sorted(plans):
        print(describe(name, plans[name]))


if __name__ == "__main__":
    main()

