# Clean up common OCR mistakes in text captured from a scanned document.

import re
import sys

# marks that should never be preceded by padding whitespace
PUNCTUATION_MARKS = ".,;:!?"


def fix_misread_glyphs(text):
    out = []
    last_index = len(text) - 1
    for i, ch in enumerate(text):
        # neighbours are read from the untouched original so repairs cannot cascade
        before = text[i - 1] if i > 0 else ""
        after = text[i + 1] if i < last_index else ""
        inside_word = before.isalpha() and after.isalpha()
        if ch == "0" and inside_word:
            # a zero hugged by letters was really the capital letter O
            out.append("O")
        elif ch == "!" and inside_word:
            # an exclamation mark wedged into a word was really a lowercase ell
            out.append("l")
        else:
            out.append(ch)
    return "".join(out)


def squeeze_space_before_punctuation(text):
    # the character class is built from the shared table so both stay in sync
    pattern = r"[ \t]+([" + re.escape(PUNCTUATION_MARKS) + r"])"
    return re.sub(pattern, r"\1", text)


def capitalize_after_sentence_end(text):
    def upper_second_group(match):
        return match.group(1) + match.group(2).upper()

    # a period plus at least one space marks the start of a new sentence
    return re.sub(r"(\. +)([a-z])", upper_second_group, text)


def correct(scan):
    if not isinstance(scan, str):
        raise TypeError("correct() expects the raw scan as a string")
    text = fix_misread_glyphs(scan)
    # spaces are squeezed before capitalising so '. ' patterns are already normal
    text = squeeze_space_before_punctuation(text)
    return capitalize_after_sentence_end(text)


def main():
    raw = sys.stdin.read()
    if not raw:
        # nothing was piped in, so there is nothing to correct
        return 0
    lines = raw.splitlines()
    repaired = 0
    for number, line in enumerate(lines, start=1):
        fixed = correct(line)
        if fixed != line:
            # count only the lines the corrector actually had to touch
            repaired += 1
        print(f"{number:4d}: {fixed}")
    # the summary goes to stderr so the corrected text itself stays pipeable
    print(f"{repaired} of {len(lines)} lines corrected", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())

