from collections import deque


# Normalise the (adults, temperatures) pair and reject malformed input.
def validate_colony(colony):
    # The colony must be a two-part record: starting adults and a temperature series.
    if not isinstance(colony, tuple) or len(colony) != 2:
        raise ValueError("colony must be a tuple of (adults, temperatures)")
    adults, temperatures = colony
    if not isinstance(adults, int) or isinstance(adults, bool):
        raise TypeError("initial adult population must be an integer")
    # A hive cannot start with a negative number of bees.
    if adults < 0:
        raise ValueError("initial adult population must be non-negative")
    temps = list(temperatures)
    for day, temp in enumerate(temps, start=1):
        # Reject non-numeric readings early so the simulation never mixes types.
        if not isinstance(temp, (int, float)) or isinstance(temp, bool):
            raise TypeError("temperature for day %d is not a number" % day)
    return adults, temps


# Build a per-day record of (day, temperature, adults, eggs still maturing).
def daily_log(colony):
    adults, temperatures = validate_colony(colony)
    # Eggs wait in a queue; index 0 holds the batch that matures today.
    pipeline = deque([0, 0, 0])
    log = []
    for day, temp in enumerate(temperatures, start=1):
        # Eggs laid three days ago have finished maturing and join the adults.
        adults += pipeline.popleft()
        if temp > 50:
            # Warm day: foragers bring food home, so the queen lays a full batch.
            pipeline.append(100)
        else:
            # Cold day: no food is gathered and part of the colony freezes.
            adults = max(0, adults - 10)
            pipeline.append(0)
        log.append((day, temp, adults, sum(pipeline)))
    return log


# Run the hive day by day and return the final adult population.
def simulate(colony):
    log = daily_log(colony)
    # With no temperature readings the hive never changes from its initial size.
    if not log:
        return validate_colony(colony)[0]
    return log[-1][2]


# Render the daily records as an aligned text table.
def format_log(log):
    header = "{:>4} {:>7} {:>8} {:>6}".format("day", "temp", "adults", "eggs")
    rows = [header, "-" * len(header)]
    for day, temp, adults, eggs in log:
        rows.append("{:>4} {:>7.1f} {:>8} {:>6}".format(day, float(temp), adults, eggs))
    return "\n".join(rows)


def main():
    colony = (100, [55, 60, 45, 70, 48, 52, 51, 40, 65, 66])
    print(format_log(daily_log(colony)))
    print("final adult population:", simulate(colony))


if __name__ == "__main__":
    main()

