def score(knight):
    # Horsemanship counts double, then the lance strength is added on top
    _, horsemanship, lance = knight
    return horsemanship * 2 + lance


def wear_lance(knight):
    name, horsemanship, lance = knight
    # Lance strength never drops below zero, no matter how many bouts are fought
    return (name, horsemanship, max(0, lance - 1))


def joust(left, right):
    left_score, right_score = score(left), score(right)
    if left_score > right_score:
        return wear_lance(left)
    if right_score > left_score:
        return wear_lance(right)
    # Equal scores are broken by the finer horsemanship, then by seniority in the list
    if right[1] > left[1]:
        return wear_lance(right)
    return wear_lance(left)


def run_round(knights):
    survivors = []
    # Knights are paired sequentially: first with second, third with fourth, and so on
    for index in range(0, len(knights) - 1, 2):
        survivors.append(joust(knights[index], knights[index + 1]))
    if len(knights) % 2:
        # An unpaired knight gets a bye and keeps his lance intact
        survivors.append(knights[-1])
    return survivors


def validate(knights):
    if not knights:
        raise ValueError("the tournament needs at least one knight")
    for knight in knights:
        if len(knight) != 3:
            raise ValueError("each knight must be (name, horsemanship, lance)")
        name, horsemanship, lance = knight
        # Skills are compared numerically, so anything else is a data error
        if not isinstance(horsemanship, (int, float)) or not isinstance(lance, (int, float)):
            raise ValueError("skills of %r must be numeric" % (name,))


def tournament(knights):
    validate(knights)
    field = list(knights)
    # Rounds continue until a single undefeated knight is left standing
    while len(field) > 1:
        field = run_round(field)
    return field[0][0]


def describe_rounds(knights):
    validate(knights)
    lines = []
    field = list(knights)
    round_number = 1
    while len(field) > 1:
        field = run_round(field)
        # Show the surviving line-up with its current, worn lance strengths
        lines.append("Round %d: %s" % (round_number, ", ".join(
            "%s(%g)" % (name, lance) for name, _, lance in field)))
        round_number += 1
    return "\n".join(lines)


if __name__ == "__main__":
    roster = [
        ("Lancelot", 8, 5),
        ("Gawain", 7, 9),
        ("Percival", 9, 2),
        ("Galahad", 8, 4),
        ("Tristan", 6, 8),
    ]
    print(describe_rounds(roster))
    print("Champion:", tournament(roster))

