WATERING_INTERVALS = {"low": 3, "medium": 7, "high": 14}


def interval_for(tolerance):
    # Tolerance labels are compared case-insensitively so input files stay flexible
    key = tolerance.strip().lower()
    if key not in WATERING_INTERVALS:
        raise ValueError("unknown drought tolerance: {!r}".format(tolerance))
    return WATERING_INTERVALS[key]


def days_left(days_since_watered, tolerance):
    # Days remaining before the plant must be watered again
    remaining = interval_for(tolerance) - days_since_watered
    # An overdue plant is clamped to 0, meaning "water it right now"
    return max(remaining, 0)


def validate(plants):
    cleaned = []
    for record in plants:
        # Each record must carry exactly the three documented fields
        if len(record) != 3:
            raise ValueError("each plant needs (name, days_since_watered, tolerance)")
        name, since, tolerance = record
        # Negative elapsed days would silently push a plant past its interval
        if since < 0:
            raise ValueError("days since last watered cannot be negative for " + name)
        cleaned.append((name.strip(), int(since), tolerance))
    return cleaned


def group_by_days_left(plants):
    groups = {}
    for name, since, tolerance in validate(plants):
        due_in = days_left(since, tolerance)
        # setdefault keeps the first plant of a new day bucket from being lost
        groups.setdefault(due_in, []).append(name)
    return groups


def schedule(plants):
    groups = group_by_days_left(plants)
    # A missing key means nothing is due today, so an empty list is the answer
    return groups.get(0, [])


def format_report(plants):
    # Build a day-ordered plan, earliest watering first
    groups = group_by_days_left(plants)
    lines = []
    for due_in in sorted(groups):
        names = ", ".join(sorted(groups[due_in]))
        if due_in == 0:
            lines.append("Water now: " + names)
        else:
            # Singular/plural wording keeps the printed plan readable
            unit = "day" if due_in == 1 else "days"
            lines.append("In {} {}: {}".format(due_in, unit, names))
    return "\n".join(lines)


def main():
    garden = [
        ("Basil", 4, "low"),
        ("Fern", 2, "low"),
        ("Aloe", 14, "high"),
        ("Rosemary", 3, "medium"),
        ("Cactus", 5, "high"),
        ("Mint", 7, "medium"),
    ]
    print(format_report(garden))
    urgent = schedule(garden)
    # Watering order is alphabetical so the gardener can walk the beds predictably
    print("Today's list:", ", ".join(sorted(urgent)) or "nothing to do")


if __name__ == "__main__":
    main()

