DAILY_RATE = {
    # Fee per day overdue, in dollars, keyed by patron type.
    "standard": 0.25,
    "student": 0.10,
}

# Daily fees stop accumulating once this much has been charged.
DAILY_FEE_CAP = 10.00

# Flat charge assumed to replace a book considered lost.
REPLACEMENT_CHARGE = 20.00

# Only standard patrons are billed for replacement, and only past this many days.
REPLACEMENT_THRESHOLD = 30


def normalize_patron(patron):
    # Reject anything that cannot name a patron type at all.
    if not isinstance(patron, str):
        raise TypeError("patron type must be a string, got %r" % (patron,))
    # Accept sloppy input such as "Student " or "STANDARD".
    key = patron.strip().lower()
    if key not in DAILY_RATE:
        raise ValueError("unknown patron type: %r" % (patron,))
    return key


def fine_for(patron, days_overdue):
    key = normalize_patron(patron)
    # Booleans are ints in Python, but they are not day counts.
    if not isinstance(days_overdue, int) or isinstance(days_overdue, bool):
        raise TypeError("days overdue must be an int, got %r" % (days_overdue,))
    if days_overdue < 0:
        raise ValueError("days overdue cannot be negative: %d" % days_overdue)
    # Books returned on time (or early) cost nothing at all.
    if days_overdue == 0:
        return 0.0
    daily = min(DAILY_RATE[key] * days_overdue, DAILY_FEE_CAP)
    if key == "standard" and days_overdue > REPLACEMENT_THRESHOLD:
        # The replacement charge sits on top of the already-capped daily fees.
        return daily + REPLACEMENT_CHARGE
    return daily


def penalize(returns):
    # Total the fines owed across a batch of (patron type, days overdue) pairs.
    total = 0.0
    for entry in returns:
        patron, days_overdue = entry
        total += fine_for(patron, days_overdue)
    # Money is only meaningful to the cent, so shed float accumulation noise.
    return round(total, 2)


def report(returns):
    # Build a per-book breakdown followed by the grand total.
    lines = []
    for patron, days_overdue in returns:
        fine = fine_for(patron, days_overdue)
        lines.append("%-9s %3d day(s) overdue -> $%6.2f" % (patron, days_overdue, fine))
    lines.append("%-9s %-18s    $%6.2f" % ("TOTAL", "", penalize(returns)))
    return "\n".join(lines)


def main():
    batch = [
        ("standard", 4),
        ("student", 12),
        ("standard", 45),
        ("student", 200),
        ("Standard", 0),
    ]
    print(report(batch))
    print("Largest single fine: $%.2f" % max(fine_for(p, d) for p, d in batch))


if __name__ == "__main__":
    main()

