DAILY_RATE = {
    # Tarifa por día de retraso, en dólares, indexada por tipo de usuario.
    "standard": 0.25,
    "student": 0.10,
}

# Las tarifas diarias dejan de acumularse una vez que se ha cobrado esta cantidad.
DAILY_FEE_CAP = 10.00

# Cargo fijo que se supone reemplaza un libro considerado perdido.
REPLACEMENT_CHARGE = 20.00

# Solo a los usuarios estándar se les cobra el reemplazo, y solo después de esta cantidad de días.
REPLACEMENT_THRESHOLD = 30


def normalize_patron(patron):
    # Rechazar cualquier cosa que no pueda nombrar un tipo de usuario en absoluto.
    if not isinstance(patron, str):
        raise TypeError("patron type must be a string, got %r" % (patron,))
    # Aceptar entradas descuidadas como "Student " o "STANDARD".
    key = patron.strip().lower()
    if key not in DAILY_RATE:
        raise ValueError("unknown patron type: %r" % (patron,))
    return key


def fine_for(patron, days_overdue):
    key = normalize_patron(patron)
    # Los booleanos son enteros en Python, pero no son conteos de días.
    if not isinstance(days_overdue, int) or isinstance(days_overdue, bool):
        raise TypeError("days overdue must be an int, got %r" % (days_overdue,))
    if days_overdue < 0:
        raise ValueError("days overdue cannot be negative: %d" % days_overdue)
    # Los libros devueltos a tiempo (o antes) no cuestan nada en absoluto.
    if days_overdue == 0:
        return 0.0
    daily = min(DAILY_RATE[key] * days_overdue, DAILY_FEE_CAP)
    if key == "standard" and days_overdue > REPLACEMENT_THRESHOLD:
        # El cargo de reemplazo se suma a las tarifas diarias ya limitadas.
        return daily + REPLACEMENT_CHARGE
    return daily


def penalize(returns):
    # Sumar las multas debidas en un lote de pares (tipo de usuario, días de retraso).
    total = 0.0
    for entry in returns:
        patron, days_overdue = entry
        total += fine_for(patron, days_overdue)
    # El dinero solo tiene sentido hasta el centavo, así que se elimina el ruido de acumulación de flotantes.
    return round(total, 2)


def report(returns):
    # Construir un desglose por libro seguido del total general.
    lines = []
    for patron, days_overdue in returns:
        fine = fine_for(patron, days_overdue)
        lines.append("%-9s %3d day(s) overdue -> $%6.2f" % (patron, days_overdue, fine))
    lines.append("%-9s %-18s    $%6.2f" % ("TOTAL", "", penalize(returns)))
    return "\n".join(lines)


def main():
    batch = [
        ("standard", 4),
        ("student", 12),
        ("standard", 45),
        ("student", 200),
        ("Standard", 0),
    ]
    print(report(batch))
    print("Largest single fine: $%.2f" % max(fine_for(p, d) for p, d in batch))


if __name__ == "__main__":
    main()

