BASE_PRICE_PER_SQFT = 3.00
STAIR_SURCHARGE = 50.00
WASTE_MARGIN = 0.10


def _validate_room(room, index):
    # A room must unpack into exactly three fields, otherwise the caller mixed up its data
    if len(room) != 3:
        raise ValueError("room %d must be (length, width, has_stairs)" % index)
    length, width, has_stairs = room
    # Booleans are a subclass of int in Python, so reject them as dimensions explicitly
    if isinstance(length, bool) or isinstance(width, bool):
        raise ValueError("room %d has a boolean dimension" % index)
    if not isinstance(length, (int, float)) or not isinstance(width, (int, float)):
        raise ValueError("room %d has non-numeric dimensions" % index)
    # Zero-sized or negative rooms cannot be carpeted and signal a data entry mistake
    if length <= 0 or width <= 0:
        raise ValueError("room %d must have positive dimensions" % index)
    return float(length), float(width), bool(has_stairs)


# Area of one rectangular room in square feet
def room_area(length, width):
    return length * width


# Total carpet quote: material, stair labour and waste margin, rounded to cents
def quote(rooms):
    total_area = 0.0
    surcharges = 0.0
    for index, room in enumerate(rooms):
        length, width, has_stairs = _validate_room(room, index)
        total_area += room_area(length, width)
        # The surcharge is per room with stairs, not per square foot
        if has_stairs:
            surcharges += STAIR_SURCHARGE
    subtotal = total_area * BASE_PRICE_PER_SQFT + surcharges
    # Offcuts and edge trimming are billed as a percentage of the whole job
    grand_total = subtotal * (1.0 + WASTE_MARGIN)
    return round(grand_total, 2)


# Per-room lines plus the grand total, used to print an itemised estimate
def breakdown(rooms):
    lines = []
    for index, room in enumerate(rooms):
        length, width, has_stairs = _validate_room(room, index)
        area = room_area(length, width)
        cost = area * BASE_PRICE_PER_SQFT
        # Mirror the stair rule from quote() so the itemised lines add up to the subtotal
        if has_stairs:
            cost += STAIR_SURCHARGE
        lines.append((index + 1, area, has_stairs, round(cost, 2)))
    return lines, quote(rooms)


# Render the breakdown as a human-readable multi-line estimate
def format_estimate(rooms):
    lines, total = breakdown(rooms)
    out = ["Room  Area (sqft)  Stairs  Cost"]
    for number, area, has_stairs, cost in lines:
        # Mark stair rooms so the customer can see where the labour fee came from
        flag = "yes" if has_stairs else "no"
        out.append("%4d  %11.2f  %6s  $%.2f" % (number, area, flag, cost))
    out.append("Grand total (incl. %d%% waste): $%.2f" % (WASTE_MARGIN * 100, total))
    return "\n".join(out)


def main():
    job = [(12, 10, False), (15, 11, True), (9.5, 8, False)]
    print(format_estimate(job))


if __name__ == "__main__":
    main()

