BASE_PRICE_PER_SQFT = 3.00
STAIR_SURCHARGE = 50.00
WASTE_MARGIN = 0.10


def _validate_room(room, index):
    # Una habitación debe desempaquetarse en exactamente tres campos; de lo contrario, quien llama confundió sus datos
    if len(room) != 3:
        raise ValueError("room %d must be (length, width, has_stairs)" % index)
    length, width, has_stairs = room
    # Los booleanos son una subclase de int en Python, así que recházalos explícitamente como dimensiones
    if isinstance(length, bool) or isinstance(width, bool):
        raise ValueError("room %d has a boolean dimension" % index)
    if not isinstance(length, (int, float)) or not isinstance(width, (int, float)):
        raise ValueError("room %d has non-numeric dimensions" % index)
    # Las habitaciones de tamaño cero o negativo no se pueden alfombrar e indican un error en la entrada de datos
    if length <= 0 or width <= 0:
        raise ValueError("room %d must have positive dimensions" % index)
    return float(length), float(width), bool(has_stairs)


# Área de una habitación rectangular en pies cuadrados
def room_area(length, width):
    return length * width


# Presupuesto total de la alfombra: material, mano de obra de escaleras y margen de desperdicio, redondeado a centavos
def quote(rooms):
    total_area = 0.0
    surcharges = 0.0
    for index, room in enumerate(rooms):
        length, width, has_stairs = _validate_room(room, index)
        total_area += room_area(length, width)
        # El recargo es por habitación con escaleras, no por pie cuadrado
        if has_stairs:
            surcharges += STAIR_SURCHARGE
    subtotal = total_area * BASE_PRICE_PER_SQFT + surcharges
    # Los recortes y el ribeteado de bordes se facturan como un porcentaje del trabajo completo
    grand_total = subtotal * (1.0 + WASTE_MARGIN)
    return round(grand_total, 2)


# Líneas por habitación más el total general, usado para imprimir un presupuesto detallado
def breakdown(rooms):
    lines = []
    for index, room in enumerate(rooms):
        length, width, has_stairs = _validate_room(room, index)
        area = room_area(length, width)
        cost = area * BASE_PRICE_PER_SQFT
        # Refleja la regla de escaleras de quote() para que las líneas detalladas sumen el subtotal
        if has_stairs:
            cost += STAIR_SURCHARGE
        lines.append((index + 1, area, has_stairs, round(cost, 2)))
    return lines, quote(rooms)


# Presenta el desglose como un presupuesto legible de varias líneas
def format_estimate(rooms):
