# Drain rates in percent of battery per second of the maneuver.
DRAIN_RATES = {"hover": 0.1, "climb": 0.3, "cruise": 0.2}

# A cruise that directly follows a climb rides the headwind and drains less.
HEADWIND_CRUISE_RATE = 0.15

START_BATTERY = 100.0


# Validate the plan and return it as a list of (action, duration) pairs.
def normalize(maneuvers):
    cleaned = []
    for index, maneuver in enumerate(maneuvers):
        action, duration = maneuver
        key = action.strip().lower()
        # Unknown actions have no defined drain rate, so the plan is unusable.
        if key not in DRAIN_RATES:
            raise ValueError("unknown action %r at position %d" % (action, index))
        # Negative durations would recharge the battery, which is not physical.
        if duration < 0:
            raise ValueError("negative duration at position %d" % index)
        cleaned.append((key, float(duration)))
    return cleaned


# Percent per second drained by one maneuver, given the preceding action.
def drain_rate(action, previous_action):
    # The headwind bonus applies only to a cruise right after a climb.
    if action == "cruise" and previous_action == "climb":
        return HEADWIND_CRUISE_RATE
    return DRAIN_RATES[action]


def estimate(maneuvers):
    battery = START_BATTERY
    previous_action = None
    for action, duration in normalize(maneuvers):
        battery -= drain_rate(action, previous_action) * duration
        # A depleted battery ends the flight, so no later maneuver matters.
        if battery <= 0:
            return 0
        previous_action = action
    return round(battery, 1)


# Build a human readable log of the battery level after each maneuver.
def report(maneuvers):
    lines = []
    battery = START_BATTERY
    previous_action = None
    for action, duration in normalize(maneuvers):
        rate = drain_rate(action, previous_action)
        battery = max(0.0, battery - rate * duration)
        lines.append("%-6s %5.0fs @ %.2f%%/s -> %5.1f%%" % (action, duration, rate, battery))
        # Stop logging once the drone is out of power; the rest never flies.
        if battery <= 0:
            lines.append("battery depleted, remaining maneuvers cancelled")
            break
        previous_action = action
    return "\n".join(lines)


def main():
    plans = {
        "survey": [("climb", 60), ("cruise", 120), ("hover", 90), ("cruise", 60)],
        "endurance": [("hover", 600), ("climb", 100), ("cruise", 300)],
        "overreach": [("climb", 200), ("cruise", 200), ("climb", 150)],
    }
    for name, plan in plans.items():
        print("=== %s ===" % name)
        print(report(plan))
        remaining = estimate(plan)
        # A zero result means the drone never finished the plan.
        if remaining == 0:
            print("result: mission aborted (0%)")
        else:
            print("result: %.1f%% remaining" % remaining)


if __name__ == "__main__":
    main()

