import math

# Base preparation time in minutes for each station, keyed by order category.
BASE_TIMES = {"espresso": 2.0, "blended": 4.0, "food": 3.0}

# Iced drinks need an extra chilling step; food is never served iced.
ICED_PENALTY = 1.0

# Each custom modifier (extra shot, syrup, alternative milk, ...) costs half a minute.
MODIFIER_COST = 0.5

STATIONS = ("espresso", "blended", "food")


def validate_order(order):
    # A malformed tuple would silently corrupt a station total, so reject it here.
    if len(order) != 3:
        raise ValueError("each order needs a category, an iced flag and a modifier count")
    category, iced, modifiers = order
    # Normalise the category so "Espresso" and "ESPRESSO" reach the same station.
    category = str(category).strip().lower()
    if category not in BASE_TIMES:
        raise ValueError("unknown order category: {!r}".format(category))
    # A bool would pass as an int but means nothing as a modifier count.
    if not isinstance(modifiers, int) or isinstance(modifiers, bool):
        raise ValueError("modifier count must be an integer")
    if modifiers < 0:
        raise ValueError("modifier count cannot be negative")
    return category, bool(iced), modifiers


def order_time(category, iced, modifiers):
    minutes = BASE_TIMES[category]
    # Only drinks can be iced, so a food order keeps its plain base time.
    if iced and category != "food":
        minutes += ICED_PENALTY
    return minutes + modifiers * MODIFIER_COST


def dispatch(orders):
    # Running totals are kept as floats so half-minute modifiers accumulate exactly.
    totals = {name: 0.0 for name in STATIONS}
    for order in orders:
        category, iced, modifiers = validate_order(order)
        totals[category] += order_time(category, iced, modifiers)
    # The shop quotes whole minutes, so each station total is rounded up once at the end.
    return tuple(math.ceil(totals[name]) for name in STATIONS)


def format_board(waits):
    lines = []
    for name, minutes in zip(STATIONS, waits):
        # A station with nothing queued should read as free rather than "0 min".
        if minutes == 0:
            lines.append("{:<9} ready".format(name.title()))
        else:
            lines.append("{:<9} {} min".format(name.title(), minutes))
    return lines


def main():
    morning_rush = [
        ("espresso", False, 0),
        ("espresso", True, 3),
        ("Blended", True, 1),
        ("food", False, 2),
        ("espresso", False, 1),
    ]
    waits = dispatch(morning_rush)
    for line in format_board(waits):
        print(line)
    # The longest queue tells the barista where an extra pair of hands is needed.
    busiest = max(zip(STATIONS, waits), key=lambda pair: pair[1])
    print("Busiest station: {} ({} min)".format(*busiest))


if __name__ == "__main__":
    main()

