CYCLE_DAYS = 30


def daily_rate(monthly_price):
    # A month is billed as thirty equal days, so one day costs a thirtieth.
    return monthly_price / CYCLE_DAYS


def validate_changes(changes):
    # A missing or non-sequence argument cannot be prorated at all.
    if not isinstance(changes, (list, tuple)):
        raise TypeError("changes must be a list of (day, price) tuples")
    cleaned = []
    for entry in changes:
        # Each entry has to unpack into exactly a day and a price.
        if len(entry) != 2:
            raise ValueError("each change needs exactly a day and a price: %r" % (entry,))
        day, price = entry
        # Changes outside the cycle would create negative or overlong segments.
        if not 1 <= day <= CYCLE_DAYS:
            raise ValueError("day %r is outside the 30 day billing cycle" % (day,))
        if price < 0:
            raise ValueError("price %r cannot be negative" % (price,))
        cleaned.append((int(day), float(price)))
    # Sorting makes the segment arithmetic valid even for unordered input.
    cleaned.sort(key=lambda change: change[0])
    return cleaned


def segments(changes):
    # Walk the timeline and emit (start_day, days_active, monthly_price).
    current_day = 1
    # The subscription begins on day one at no cost until the first change.
    current_price = 0.0
    for day, price in validate_changes(changes):
        days_active = day - current_day
        # Two changes on the same day produce an empty segment worth nothing.
        if days_active > 0:
            yield current_day, days_active, current_price
        current_day = day
        current_price = price
    # The last plan stays active through the end of the thirtieth day.
    yield current_day, CYCLE_DAYS - current_day + 1, current_price


def prorate(changes):
    total = 0.0
    for _, days_active, price in segments(changes):
        total += days_active * daily_rate(price)
    # Money is reported to the cent.
    return round(total, 2)


def bill_report(changes):
    # Render one line per billed segment plus the rounded monthly total.
    lines = []
    for start, days_active, price in segments(changes):
        end = start + days_active - 1
        amount = days_active * daily_rate(price)
        lines.append(
            "days %2d-%2d: %2d day(s) at $%.2f/mo = $%6.2f" % (start, end, days_active, price, amount)
        )
    lines.append("total: $%.2f" % prorate(changes))
    return "\n".join(lines)


def main():
    # An upgrade mid-month followed by a downgrade near the end of the cycle.
    print(bill_report([(11, 30.00), (21, 15.00)]))
    print()
    # A customer who signs up on day six and never changes plans again.
    print(bill_report([(6, 60.00)]))


if __name__ == "__main__":
    main()

