import math


# A single round's differential: (gross - rating) * 113 / slope, to one decimal.
def course_differential(gross, rating, slope):
    # A slope of zero or below would make the differential undefined.
    if slope <= 0:
        raise ValueError(f"course slope must be positive, got {slope!r}")
    raw = (gross - rating) * 113 / slope
    return round(raw, 1)


def validate_round(entry):
    # Accept any sequence of exactly three items; anything else is a data error.
    if len(entry) != 3:
        raise ValueError(f"each round needs 3 values, got {len(entry)}: {entry!r}")
    gross, rating, slope = entry
    for label, value in (("gross score", gross), ("course rating", rating), ("slope", slope)):
        # Booleans are ints in Python, but they are never valid golf numbers.
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{label} must be numeric, got {value!r}")
    return gross, rating, slope


def count_used(n):
    # Fewer than five rounds is not enough history for an index at all.
    if n < 5:
        return 0
    # Five to ten cards use the best two, more than ten use the best eight.
    if n <= 10:
        return 2
    return 8


def truncate_one_decimal(value):
    # math.trunc drops toward zero, which keeps negative indexes correct too.
    return math.trunc(value * 10) / 10


def handicap(rounds):
    differentials = []
    for entry in rounds:
        gross, rating, slope = validate_round(entry)
        differentials.append(course_differential(gross, rating, slope))
    # Sorting ascending puts the best (lowest) differentials first.
    differentials.sort()
    used = count_used(len(differentials))
    if used == 0:
        return 0
    average = sum(differentials[:used]) / used
    # The 0.96 bonus factor is part of the standard index formula.
    return truncate_one_decimal(average * 0.96)


def report(label, rounds):
    index = handicap(rounds)
    # An index of exactly zero means the player has no established handicap.
    status = "not established" if index == 0 else f"{index:.1f}"
    print(f"{label}: {len(rounds)} rounds -> {status}")


def main():
    novice = [(95, 70.0, 113), (101, 71.2, 120), (98, 69.8, 118)]
    regular = [(88, 71.4, 125), (92, 70.1, 118), (85, 69.5, 113),
               (94, 72.0, 130), (90, 70.8, 122), (87, 71.1, 124)]
    # Twelve cards, so only the eight lowest differentials count.
    veteran = regular + [(82, 70.2, 119), (79, 69.9, 115), (84, 71.5, 127),
                         (86, 70.4, 121), (81, 70.0, 116), (83, 71.8, 128)]
    report("Novice", novice)
    report("Regular", regular)
    report("Veteran", veteran)


if __name__ == "__main__":
    main()

