BULLSEYE_RADIUS_MM = 2.0
MISS_PENALTY = 1
CONSECUTIVE_MISS_LIMIT = 3
CONSECUTIVE_MISS_PENALTY = 5
BULLSEYE_BONUS = 2


def validate_shot(shot):
    # A shot must be a pair; anything else cannot be read as ring + distance
    if not isinstance(shot, (tuple, list)) or len(shot) != 2:
        raise ValueError("each arrow must be a (ring, distance) pair, got %r" % (shot,))
    ring, distance = shot
    # Booleans are ints in Python, but a boolean ring is certainly a mistake
    if isinstance(ring, bool) or not isinstance(ring, int):
        raise TypeError("ring must be an integer, got %r" % (ring,))
    # Ring zero means a miss, ten is the innermost scoring ring
    if not 0 <= ring <= 10:
        raise ValueError("ring must be between 0 and 10, got %d" % ring)
    if isinstance(distance, bool) or not isinstance(distance, (int, float)):
        raise TypeError("distance must be a number, got %r" % (distance,))
    # Distance is measured from the centre outwards, so it is never negative
    if distance < 0:
        raise ValueError("distance must not be negative, got %r" % (distance,))
    return ring, float(distance)


def shot_points(ring, distance):
    # A miss costs a point instead of awarding any
    if ring == 0:
        return -MISS_PENALTY
    # Rings one to nine (and ten) simply award their face value
    points = ring
    if ring == 10 and distance < BULLSEYE_RADIUS_MM:
        # A perfect bullseye inside the two millimetre circle earns a bonus
        points += BULLSEYE_BONUS
    return points


def score(arrows):
    total = 0
    consecutive_misses = 0
    for shot in arrows:
        ring, distance = validate_shot(shot)
        total += shot_points(ring, distance)
        if ring == 0:
            consecutive_misses += 1
        else:
            # Any hit breaks the miss streak
            consecutive_misses = 0
        if consecutive_misses == CONSECUTIVE_MISS_LIMIT:
            total -= CONSECUTIVE_MISS_PENALTY
            # Start counting afresh so a sixth miss in a row is penalised again
            consecutive_misses = 0
    return total


def describe_round(arrows):
    lines = []
    for index, shot in enumerate(arrows, start=1):
        ring, distance = validate_shot(shot)
        points = shot_points(ring, distance)
        if ring == 0:
            label = "miss"
        elif points > ring:
            # Only a bonused shot scores more than its ring value
            label = "bullseye"
        else:
            label = "ring %d" % ring
        lines.append("Arrow %2d: %-9s at %5.1f mm -> %+d" % (index, label, distance, points))
    # The totals line includes streak penalties, which no single arrow owns
    lines.append("Final score: %d" % score(arrows))
    return "\n".join(lines)


def main():
    round_shots = [
        (10, 0.4), (9, 21.0), (0, 180.5), (0, 240.0),
        (0, 310.2), (10, 1.9), (5, 92.7), (0, 205.0),
    ]
    print(describe_round(round_shots))


if __name__ == "__main__":
    main()

