def validate(drivetrain):
    """Unpack and sanity-check a drivetrain description."""
    fronts, rears, circumference = drivetrain
    # Both sprocket lists must be non-empty, otherwise there is no gear to analyze
    if not fronts or not rears:
        raise ValueError("drivetrain needs at least one chainring and one cog")
    # A tooth count of zero or less would make the ratio meaningless or divide by zero
    if any(t <= 0 for t in fronts) or any(t <= 0 for t in rears):
        raise ValueError("tooth counts must be positive")
    if circumference <= 0:
        raise ValueError("wheel circumference must be positive")
    return list(fronts), list(rears), float(circumference)


def is_cross_chained(front, rear, fronts, rears):
    """Detect the two extreme cross-chaining combinations."""
    # Smallest ring with smallest cog: chain runs far outboard at the back
    if front == min(fronts) and rear == min(rears):
        return True
    # Largest ring with largest cog: chain runs far inboard at the back
    return front == max(fronts) and rear == max(rears)


def analyze(drivetrain):
    """Return sorted development distances (mm) for all usable gear combinations."""
    fronts, rears, circumference = validate(drivetrain)
    developments = []
    for front in fronts:
        for rear in rears:
            # Skip the combinations that stress the chain too much to be ridden
            if is_cross_chained(front, rear, fronts, rears):
                continue
            ratio = front / rear
            developments.append(round(ratio * circumference))
    # Lowest gear first, which matches how a rider shifts up through the range
    developments.sort()
    return developments


def report(developments):
    """Build a short human-readable summary of analyzed development distances."""
    lines = ["%d usable gear(s)" % len(developments)]
    if developments:
        # Range and spacing only make sense when at least one gear survived filtering
        lines.append("lowest: %d mm" % developments[0])
        lines.append("highest: %d mm" % developments[-1])
        span = (developments[-1] - developments[0]) / 1000.0
        lines.append("span: %.2f m per crank revolution" % span)
        # Duplicate developments are gears that feel identical to the rider
        duplicates = len(developments) - len(set(developments))
        lines.append("redundant gears: %d" % duplicates)
    return "\n".join(lines)


def main():
    road_bike = ([34, 50], [11, 13, 15, 17, 19, 21, 24, 28], 2096)
    touring_bike = ([26, 36, 48], [14, 16, 18, 21, 24, 28, 32], 2133)
    for name, drivetrain in (("road", road_bike), ("touring", touring_bike)):
        developments = analyze(drivetrain)
        print("=== %s bike ===" % name)
        print(report(developments))
        print("developments:", developments)


if __name__ == "__main__":
    main()

