OPENING_HOUR = 9
PASSES_PER_HOUR = 10


def _validate(requests):
    cleaned = []
    for index, request in enumerate(requests):
        # A request must unpack into exactly three fields to be usable.
        if len(request) != 3:
            raise ValueError("request %d must have 3 fields" % index)
        ride, party_size, is_vip = request
        if not isinstance(ride, str) or not ride.strip():
            raise ValueError("request %d has an empty ride name" % index)
        # Party sizes come from a turnstile counter, so they are whole numbers.
        if not isinstance(party_size, int) or isinstance(party_size, bool):
            raise ValueError("request %d has a non-integer party size" % index)
        if party_size < 1:
            raise ValueError("request %d has a party size below one" % index)
        # Ride names arrive from a form, so trim them before grouping by ride.
        cleaned.append((ride.strip(), party_size, bool(is_vip)))
    return cleaned


def _military(hour):
    # Hours never pass 23 in a single operating day, so two digits suffice.
    return "%02d:00" % hour


def _assign(ride, party_size, availability):
    # Every ride starts the day at the opening hour with a full pass quota.
    hour, remaining = availability.get(ride, (OPENING_HOUR, PASSES_PER_HOUR))
    slots = []
    while party_size > 0:
        # A full hour for this ride pushes everyone behind it to the next hour.
        if remaining == 0:
            hour += 1
            remaining = PASSES_PER_HOUR
        seated = min(party_size, remaining)
        slots.append((ride, _military(hour)))
        party_size -= seated
        remaining -= seated
    availability[ride] = (hour, remaining)
    return slots


def distribute(requests):
    cleaned = _validate(requests)
    availability = {}
    assignments = []
    # VIPs keep their original relative order, then the regular queue follows.
    ordered = [r for r in cleaned if r[2]] + [r for r in cleaned if not r[2]]
    for ride, party_size, _is_vip in ordered:
        assignments.extend(_assign(ride, party_size, availability))
    return assignments


def summarize(assignments):
    counts = {}
    for ride, slot in assignments:
        counts[(ride, slot)] = counts.get((ride, slot), 0) + 1
    lines = []
    # Sorting by ride then slot keeps the printed report stable for operators.
    for ride, slot in sorted(counts):
        lines.append("%s %s: %d group(s)" % (ride, slot, counts[(ride, slot)]))
    return "\n".join(lines)


def main():
    requests = [
        ("Thunder Drop", 4, False),
        ("Thunder Drop", 8, True),
        ("River Rapids", 14, False),
        ("Thunder Drop", 3, False),
        ("River Rapids", 2, True),
    ]
    assignments = distribute(requests)
    for ride, slot in assignments:
        print("%-14s %s" % (ride, slot))
    print(summarize(assignments))


if __name__ == "__main__":
    main()

