MIN_AGE = 17
MIN_WEIGHT = 110
STANDARD_WAIT = 56
SENIOR_WAIT = 80
SENIOR_AGE = 65


def required_wait(age):
    # Donors past 65 need a longer recovery window between donations
    if age > SENIOR_AGE:
        return SENIOR_WAIT
    return STANDARD_WAIT


def is_eligible(age, weight, days_since):
    if age < MIN_AGE:
        return False
    # Weight is measured in pounds, matching the clinic's intake form
    if weight < MIN_WEIGHT:
        return False
    return days_since >= required_wait(age)


def parse_record(record):
    # Each record is expected as (name, age, weight, days since last donation)
    name, age, weight, days_since = record
    if not str(name).strip():
        raise ValueError("donor name must not be empty")
    age = int(age)
    weight = float(weight)
    days_since = int(days_since)
    # Negative values would silently pass the comparisons below, so reject them
    if age < 0 or weight < 0 or days_since < 0:
        raise ValueError("age, weight and days since donation must be non-negative")
    return str(name).strip(), age, weight, days_since


def screen(donors):
    eligible = []
    for record in donors:
        name, age, weight, days_since = parse_record(record)
        if is_eligible(age, weight, days_since):
            eligible.append(name)
    # The clinic prints the call list alphabetically
    return sorted(eligible)


def report(donors):
    approved = screen(donors)
    lines = ["Eligible donors: %d of %d" % (len(approved), len(donors))]
    for name in approved:
        lines.append("  - " + name)
    # Make the rejection case explicit rather than printing an empty block
    if not approved:
        lines.append("  (none)")
    return "\n".join(lines)


def main():
    roster = [
        ("Nadia Okonkwo", 34, 145, 60),
        ("Ben Ruiz", 16, 160, 120),
        ("Clara Vance", 71, 130, 70),
        ("Dmitri Volkov", 68, 190, 95),
        ("Elena Sharma", 29, 104, 200),
        ("Frank Mbeki", 45, 175, 40),
        ("amy Zhao", 22, 118, 56),
    ]
    # Clara waits only 70 days, which is short of the senior threshold
    print(report(roster))


if __name__ == "__main__":
    main()

