def required_wait(age):
    # Los donantes mayores de 65 años necesitan un periodo de recuperación más largo entre donaciones
    if age > SENIOR_AGE:
        return SENIOR_WAIT
    return STANDARD_WAIT


def is_eligible(age, weight, days_since):
    if age < MIN_AGE:
        return False
    # El peso se mide en libras, coincidiendo con el formulario de admisión de la clínica
    if weight < MIN_WEIGHT:
        return False
    return days_since >= required_wait(age)


def parse_record(record):
    # Se espera cada registro como (nombre, edad, peso, días desde la última donación)
    name, age, weight, days_since = record
    if not str(name).strip():
        raise ValueError("donor name must not be empty")
    age = int(age)
    weight = float(weight)
    days_since = int(days_since)
    # Los valores negativos pasarían silenciosamente las comparaciones de abajo, así que se rechazan
    if age < 0 or weight < 0 or days_since < 0:
        raise ValueError("age, weight and days since donation must be non-negative")
    return str(name).strip(), age, weight, days_since


def screen(donors):
    eligible = []
    for record in donors:
        name, age, weight, days_since = parse_record(record)
        if is_eligible(age, weight, days_since):
            eligible.append(name)
    # La clínica imprime la lista de llamadas en orden alfabético
    return sorted(eligible)


def report(donors):
    approved = screen(donors)
    lines = ["Eligible donors: %d of %d" % (len(approved), len(donors))]
    for name in approved:
        lines.append("  - " + name)
    # Hacer explícito el caso de rechazo en lugar de imprimir un bloque vacío
    if not approved:
        lines.append("  (none)")
    return "\n".join(lines)


def main():
    roster = [
        ("Nadia Okonkwo", 34, 145, 60),
        ("Ben Ruiz", 16, 160, 120),
        ("Clara Vance", 71, 130, 70),
        ("Dmitri Volkov", 68, 190, 95),
        ("Elena Sharma", 29, 104, 200),
        ("Frank Mbeki", 45, 175, 40),
        ("amy Zhao", 22, 118, 56),
    ]
    # Clara espera solo 70 días, lo que no alcanza el umbral para personas mayores
    print(report(roster))


if __name__ == "__main__":
    main()

