import math

# Bonus factors applied to the base miles according to the ticket class.
CLASS_FACTORS = {"economy": 1.0, "business": 1.5, "first": 2.0}

# Multipliers granted by the frequent flyer tier on top of base and class miles.
TIER_FACTORS = {"basic": 1.0, "gold": 1.25, "platinum": 1.5, "diamond": 2.0}

# Short flights are credited as if this many miles had been flown.
MINIMUM_BASE_MILES = 500


def base_miles(distance):
    # Base miles credited for a flown distance.
    if distance < 0:
        raise ValueError("distance cannot be negative")
    # The minimum guarantee applies before any class or tier bonus.
    if distance < MINIMUM_BASE_MILES:
        return float(MINIMUM_BASE_MILES)
    return float(distance)


def class_factor(ticket_class):
    # Ticket class names are matched case-insensitively.
    key = ticket_class.strip().lower()
    if key not in CLASS_FACTORS:
        raise ValueError("unknown ticket class: %r" % (ticket_class,))
    return CLASS_FACTORS[key]


def tier_factor(tier):
    # Tier names are matched the same way as ticket classes.
    key = tier.strip().lower()
    if key not in TIER_FACTORS:
        raise ValueError("unknown tier: %r" % (tier,))
    return TIER_FACTORS[key]


def round_half_up(value):
    # round() uses banker's rounding, which would credit 2.5 miles as 2.
    return int(math.floor(value + 0.5))


def miles(flights):
    # Earned miles for each (distance, ticket class, tier) record.
    earned = []
    for distance, ticket_class, tier in flights:
        credited = base_miles(distance) * class_factor(ticket_class)
        # The tier bonus compounds on the class-adjusted total, not on the raw distance.
        credited *= tier_factor(tier)
        earned.append(round_half_up(credited))
    return earned


def format_report(flights, earned):
    # One text line per flight, followed by a total line.
    lines = []
    for (distance, ticket_class, tier), award in zip(flights, earned):
        lines.append("%5d km  %-9s %-9s -> %6d miles" % (distance, ticket_class, tier, award))
    # The summary line lets a caller check the account balance at a glance.
    lines.append("%34s %6d miles" % ("total", sum(earned)))
    return "\n".join(lines)


def main():
    flights = [
        (400, "economy", "basic"),
        (1200, "business", "gold"),
        (3500, "first", "diamond"),
        (250, "business", "platinum"),
        (800, "economy", "platinum"),
    ]
    earned = miles(flights)
    print(format_report(flights, earned))


if __name__ == "__main__":
    main()

