SINGLE_PURCHASE_LIMIT = 8
CUMULATIVE_LIMIT = 15
TRANSACTION_LIMIT = 3


def parse_purchase(event):
    if len(event) != 3:
        raise ValueError("each purchase needs a name, an address and a ticket count")
    name, address, tickets = event
    # Names are the identity used for reporting, so they must be real strings
    if not isinstance(name, str) or not name.strip():
        raise ValueError("buyer name must be a non-empty string")
    # Addresses are matched exactly, so an empty one would group unrelated buyers
    if not isinstance(address, str) or not address.strip():
        raise ValueError("home address must be a non-empty string")
    # Booleans are ints in Python; reject them explicitly to avoid silly counts
    if isinstance(tickets, bool) or not isinstance(tickets, int):
        raise ValueError("ticket count must be an integer")
    if tickets < 0:
        raise ValueError("ticket count cannot be negative")
    return name, address, tickets


def scalpers(purchases):
    flagged = set()
    totals = defaultdict(int)
    transaction_counts = defaultdict(int)
    # Maps an address to the distinct buyer names seen living there
    buyers_by_address = defaultdict(set)

    for event in purchases:
        name, address, tickets = parse_purchase(event)
        totals[name] += tickets
        transaction_counts[name] += 1
        buyers_by_address[address].add(name)
        # A single oversized purchase is immediately suspicious
        if tickets > SINGLE_PURCHASE_LIMIT:
            flagged.add(name)

    for name, total in totals.items():
        # Hoarding spread over several modest buys still counts
        if total > CUMULATIVE_LIMIT:
            flagged.add(name)
        # Frequent buying, however small each individual order is
        if transaction_counts[name] > TRANSACTION_LIMIT:
            flagged.add(name)

    for names in buyers_by_address.values():
        # One household fronting for several different identities
        if len(names) > 1:
            flagged.update(names)

    return sorted(flagged)


