    suspects = scalpers(purchases)
    lines = ["Screened {} purchase event(s).".format(len(purchases))]
    if not suspects:
        # Nothing to investigate; say so instead of printing an empty list
        lines.append("No suspicious buyers found.")
    else:
        lines.append("Flagged {} buyer(s):".format(len(suspects)))
        lines.extend("  - " + name for name in suspects)
    return "\n".join(lines)


