BASE_RATE = 0.10
AXLE_SURCHARGE = 0.05
COMMERCIAL_MULTIPLIER = 1.5
ELECTRIC_DISCOUNT = 0.20

EXEMPT_CLASSES = ("emergency",)


def normalize_class(vehicle_class):
    # Vehicle classes arrive from several scanners, so casing and padding vary
    if not isinstance(vehicle_class, str):
        raise TypeError("vehicle class must be a string")
    return vehicle_class.strip().lower()


def validate_record(record):
    # Unpacks a record into (axles, class, distance) or rejects it
    if len(record) != 3:
        raise ValueError("each vehicle record needs axles, class and distance")
    axles, vehicle_class, distance = record
    # An axle count below one is physically impossible and would give a negative surcharge
    if not isinstance(axles, int) or axles < 1:
        raise ValueError("axle count must be a positive integer")
    if distance < 0:
        raise ValueError("distance travelled cannot be negative")
    return axles, normalize_class(vehicle_class), float(distance)


def toll_for(axles, vehicle_class, distance):
    # Charge for a single validated vehicle, in dollars
    if vehicle_class in EXEMPT_CLASSES:
        return 0.0
    rate = BASE_RATE
    # Every axle past the second one adds its own per-mile surcharge
    if axles > 2:
        rate += AXLE_SURCHARGE * (axles - 2)
    charge = rate * distance
    if vehicle_class == "commercial":
        charge *= COMMERCIAL_MULTIPLIER
    if vehicle_class == "electric":
        # The green discount applies to the already computed total, not to the rate
        charge *= 1.0 - ELECTRIC_DISCOUNT
    return charge


def tolls(vehicles):
    # Toll charge per vehicle record, rounded to two decimals
    charges = []
    for record in vehicles:
        axles, vehicle_class, distance = validate_record(record)
        charges.append(round(toll_for(axles, vehicle_class, distance), 2))
    return charges


def format_report(vehicles, charges):
    # Per-vehicle report lines followed by a total line
    lines = []
    for record, charge in zip(vehicles, charges):
        axles, vehicle_class, distance = validate_record(record)
        label = "%s (%d axles, %.0f mi)" % (vehicle_class, axles, distance)
        lines.append("%-38s $%6.2f" % (label, charge))
    # The total is summed from the rounded charges so it matches the printed column
    lines.append("%-38s $%6.2f" % ("TOTAL", round(sum(charges), 2)))
    return "\n".join(lines)


def main():
    fleet = [
        (2, "personal", 100),
        (5, "Commercial", 240),
        (3, "emergency", 80),
        (2, "electric", 150),
        (4, "personal", 62.5),
    ]
    charges = tolls(fleet)
    print(charges)
    print(format_report(fleet, charges))


if __name__ == "__main__":
    main()

