def validate_container(record):
    # Each record must be a 3-field tuple: weight, destination port, hazard flag.
    if not isinstance(record, (tuple, list)) or len(record) != 3:
        raise ValueError("container record must have exactly 3 fields: %r" % (record,))
    weight, port, hazardous = record
    # Booleans are a subclass of int in Python, so reject them as weights explicitly.
    if isinstance(weight, bool) or not isinstance(weight, (int, float)):
        raise TypeError("weight must be numeric, got %r" % (weight,))
    if weight <= 0:
        raise ValueError("weight must be positive, got %r" % (weight,))
    if not isinstance(port, str) or not port.strip():
        raise ValueError("destination port must be a non-empty string")
    if not isinstance(hazardous, bool):
        raise TypeError("hazardous flag must be a boolean, got %r" % (hazardous,))
    # Normalise the port code so reports group "ny" and "NY" together.
    return float(weight), port.strip().upper(), hazardous


def classify(weight, hazardous):
    # Hazardous and heavy at the same time: the two stowage rules conflict.
    if hazardous and weight > 30:
        return "invalid"
    # Hazardous cargo always rides on the upper deck where it can be vented.
    if hazardous:
        return "upper"
    # Heavy non-hazardous cargo goes low to keep the centre of gravity down.
    if weight > 30:
        return "lower"
    return "middle"


def cargo(containers):
    totals = {"upper": 0.0, "middle": 0.0, "lower": 0.0, "invalid": 0.0}
    for record in containers:
        weight, _port, hazardous = validate_container(record)
        area = classify(weight, hazardous)
        totals[area] += weight
    # Rejected containers are never loaded, so their weight is dropped here.
    return (totals["upper"], totals["middle"], totals["lower"])


def manifest(containers):
    # Build a per-container stowage plan alongside the aggregate weights.
    plan = []
    for record in containers:
        weight, port, hazardous = validate_container(record)
        plan.append((weight, port, classify(weight, hazardous)))
    return plan


def format_report(containers):
    plan = manifest(containers)
    upper, middle, lower = cargo(containers)
    lines = []
    for weight, port, area in plan:
        # Invalid containers are reported so the loading crew can offload them.
        label = "REJECTED" if area == "invalid" else area.upper()
        lines.append("%8.1ft -> %-4s %s" % (weight, port, label))
    lines.append("-" * 32)
    lines.append("upper deck : %8.1f t" % upper)
    lines.append("middle deck: %8.1f t" % middle)
    lines.append("lower hold : %8.1f t" % lower)
    # The stowed total excludes rejected cargo by construction.
    lines.append("stowed     : %8.1f t" % (upper + middle + lower))
    return "\n".join(lines)


def main():
    shipment = [
        (20, "NY", False),
        (34.5, "Rotterdam", False),
        (12, " ny ", True),
        (41, "Shanghai", True),
        (30, "Hamburg", False),
    ]
    print(format_report(shipment))
    # The 41 t hazardous container is rejected, hence it is absent from the totals.
    print("totals:", cargo(shipment))


if __name__ == "__main__":
    main()

