BASE_WATTS_PER_UNIT = 100
WATTS_PER_CORE = 15
WATTS_PER_DRIVE = 10
COOLING_FAN_WATTS = 50
FAN_CORE_THRESHOLD = 32
PENALTY_UNIT_SIZE = 4
PENALTY_FACTOR = 1.10


def _validate(config, index):
    # Each configuration must unpack into exactly three fields
    try:
        units, cores, drives = config
    except (TypeError, ValueError):
        raise ValueError(f"server {index}: expected (units, cores, drives), got {config!r}")
    fields = {"unit size": units, "cpu core count": cores, "storage drive count": drives}
    for name, value in fields.items():
        # Booleans are ints in Python but make no sense as hardware counts
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"server {index}: {name} must be an int, got {value!r}")
    if units < 1:
        raise ValueError(f"server {index}: unit size must be at least 1, got {units}")
    if cores < 1:
        raise ValueError(f"server {index}: a server needs at least one cpu core, got {cores}")
    if drives < 0:
        raise ValueError(f"server {index}: storage drive count cannot be negative, got {drives}")
    return units, cores, drives


def server_power(units, cores, drives):
    # Chassis baseline scales with the rack units the server occupies
    watts = float(BASE_WATTS_PER_UNIT * units)
    watts += WATTS_PER_CORE * cores
    watts += WATTS_PER_DRIVE * drives
    if cores > FAN_CORE_THRESHOLD:
        # High core counts need an auxiliary cooling fan
        watts += COOLING_FAN_WATTS
    if units >= PENALTY_UNIT_SIZE:
        # Extended power bus lines waste ten percent of the draw
        watts *= PENALTY_FACTOR
    return watts


def racks(servers):
    powers = []
    for index, config in enumerate(servers):
        units, cores, drives = _validate(config, index)
        powers.append(server_power(units, cores, drives))
    return powers


def format_report(servers, powers):
    lines = ["units  cores  drives      watts"]
    for (units, cores, drives), watts in zip(servers, powers):
        # Two decimals keep the ten percent penalty readable
        lines.append(f"{units:>5}  {cores:>5}  {drives:>6}  {watts:>9.2f}")
    total = sum(powers)
    lines.append(f"{'total':>21}  {total:>9.2f}")
    # A 16 A / 230 V feed is the usual limit for a single rack circuit
    if total > 3680:
        lines.append("WARNING: total draw exceeds a single 16 A 230 V feed")
    return "\n".join(lines)


def main():
    rack = [(2, 16, 4), (1, 8, 2), (4, 64, 12), (3, 33, 24)]
    print(format_report(rack, racks(rack)))


if __name__ == "__main__":
    main()

