BULK_DISCOUNT_THRESHOLD = 100000
BULK_DISCOUNT_RATE = 0.10

# Format labels are normalised before matching so that "Print-Ready" and
# "print ready" are treated as the same requested output.
DIGITAL_LABELS = {"digital", "ebook", "epub", "standard digital"}
PRINT_LABELS = {"print", "print ready", "printready", "print-ready"}


def normalise_format(label):
    # Lowercase the label and turn underscores and hyphens into plain spaces.
    cleaned = str(label).strip().lower().replace("_", " ").replace("-", " ")
    # Multiple inner spaces would otherwise defeat the lookup tables above.
    return " ".join(cleaned.split())


def validate_record(record):
    # Unpack one manuscript record, rejecting anything with the wrong shape.
    try:
        words, images, formats = record
    except (TypeError, ValueError):
        raise ValueError("each manuscript needs word count, images and formats")
    # Negative counts would produce nonsensical negative fees.
    if words < 0 or images < 0:
        raise ValueError("word count and image count must be non-negative")
    if isinstance(formats, str):
        # A lone string is a common mistake; treat it as a single format.
        formats = [formats]
    return int(words), int(images), [normalise_format(f) for f in formats]


def manuscript_fee(record):
    words, images, formats = validate_record(record)
    total = words * BASE_RATE_PER_WORD
    total += images * IMAGE_PLACEMENT_FEE
    # The flat digital fee is charged once, however many digital labels appear.
    if any(fmt in DIGITAL_LABELS for fmt in formats):
        total += DIGITAL_FORMAT_FEE
    if any(fmt in PRINT_LABELS for fmt in formats):
        total += PRINT_READY_FEE
    if words > BULK_DISCOUNT_THRESHOLD:
        # The bulk discount applies to the whole total, not just the word cost.
        total *= 1 - BULK_DISCOUNT_RATE
    return round(total, 2)


def ebook(manuscripts):
    # Fees are returned in the same order as the manuscripts were supplied.
    return [manuscript_fee(record) for record in manuscripts]


def format_report(manuscripts, fees):
    lines = []
    for index, (record, fee) in enumerate(zip(manuscripts, fees), start=1):
        words, images, formats = validate_record(record)
        # Keep the original order of the requested formats in the report.
        joined = ", ".join(formats) if formats else "none"
        lines.append(
            "#%d: %d words, %d images, formats [%s] -> $%.2f"
            % (index, words, images, joined, fee)
        )
    lines.append("Total billed: $%.2f" % round(sum(fees), 2))
    return lines


def main():
    manuscripts = [
        (50000, 10, ["digital"]),
        (120000, 40, ["digital", "Print Ready"]),
        (8000, 0, []),
    ]
    fees = ebook(manuscripts)
    for line in format_report(manuscripts, fees):
        print(line)


if __name__ == "__main__":
    main()

