CONTRACT_MULTIPLIER = 100

VALID_OPTION_TYPES = ("call", "put")
VALID_POSITION_TYPES = ("long", "short")


def normalize_position(position):
    option_type, position_type, strike, premium, contracts = position
    # Option and position kinds are matched case-insensitively for convenience
    option_type = str(option_type).strip().lower()
    position_type = str(position_type).strip().lower()
    if option_type not in VALID_OPTION_TYPES:
        raise ValueError("unknown option type: %r" % (option_type,))
    if position_type not in VALID_POSITION_TYPES:
        raise ValueError("unknown position type: %r" % (position_type,))
    strike, premium, contracts = float(strike), float(premium), float(contracts)
    if strike < 0 or premium < 0:
        # Strikes and quoted premiums are always non-negative prices
        raise ValueError("strike and premium must be non-negative")
    return option_type, position_type, strike, premium, contracts


def intrinsic_payoff(option_type, position_type, strike, price):
    # Per-share value at expiration, signed by the side of the position
    if option_type == "call":
        # A long call collects what is above the strike; a short call owes it
        return max(0.0, price - strike) if position_type == "long" else min(0.0, strike - price)
    # Puts mirror calls around the strike
    return max(0.0, strike - price) if position_type == "long" else min(0.0, price - strike)


def position_profit(position, price):
    option_type, position_type, strike, premium, contracts = normalize_position(position)
    payoff = intrinsic_payoff(option_type, position_type, strike, price)
    # A long position paid the premium out; a short position collected it
    premium_flow = -premium if position_type == "long" else premium
    return (payoff + premium_flow) * contracts * CONTRACT_MULTIPLIER


def profit(positions, price):
    price = float(price)
    if price < 0:
        raise ValueError("underlying price must be non-negative")
    total = 0.0
    # The portfolio profit is just the sum over the individual legs
    for position in positions:
        total += position_profit(position, price)
    return float(total)


def describe_position(position):
    option_type, position_type, strike, premium, contracts = normalize_position(position)
    # Fractional contract counts are unusual, so keep them visible when present
    count = "%g" % contracts
    return "%s %s %s @ %.2f strike, premium %.2f" % (count, position_type, option_type, strike, premium)


def report(positions, prices):
    for position in positions:
        print("  -", describe_position(position))
    print("%10s %14s" % ("price", "profit"))
    for price in prices:
        # Each row is the whole portfolio valued at one expiration price
        print("%10.2f %14.2f" % (price, profit(positions, price)))


def main():
    # A long straddle: profits if the underlying moves far in either direction
    straddle = [
        ("call", "long", 100.0, 4.50, 2),
        ("put", "long", 100.0, 3.75, 2),
    ]
    report(straddle, [80.0, 95.0, 100.0, 105.0, 120.0])
    print()
    # A covered-call style overlay written above the current level
    written = [("call", "short", 105.0, 2.10, 5)]
    report(written, [100.0, 105.0, 110.0])


if __name__ == "__main__":
    main()

