import sys

# Each arm rests or points along one of eight 45-degree spokes; 0 degrees is
# straight up and the angle grows clockwise, so 90 is out to the signaller's right.
POSITION_ANGLES = {0: 180, 1: 225, 2: 270, 3: 315, 4: 0, 5: 45, 6: 90, 7: 135}

# Standard semaphore letters, each described by the two spokes the flags occupy.
LETTER_POSITIONS = {
    # First circle: one flag rests at the side, the other sweeps round.
    'A': (0, 1), 'B': (0, 2), 'C': (0, 3), 'D': (0, 4),
    'E': (0, 5), 'F': (0, 6), 'G': (0, 7),
    # Second circle: one flag stays low on the left.
    'H': (1, 2), 'I': (1, 3), 'K': (1, 4), 'L': (1, 5), 'M': (1, 6), 'N': (1, 7),
    'O': (2, 3), 'P': (2, 4), 'Q': (2, 5), 'R': (2, 6), 'S': (2, 7),
    'T': (3, 4), 'U': (3, 5), 'Y': (3, 6),
    # '#' is the numerical sign and 'J' doubles as the alphabetical sign.
    '#': (3, 7), 'J': (4, 5), 'V': (4, 6), 'W': (5, 6), 'X': (5, 7), 'Z': (6, 7),
}

# While the numerical shift is active the first ten letters stand for digits.
NUMERALS = {'A': '1', 'B': '2', 'C': '3', 'D': '4', 'E': '5',
            'F': '6', 'G': '7', 'H': '8', 'I': '9', 'K': '0'}


def _build_alphabet():
    table = {}
    for letter, (first, second) in LETTER_POSITIONS.items():
        # The flags are interchangeable, so store the angles in a canonical order.
        key = tuple(sorted((POSITION_ANGLES[first], POSITION_ANGLES[second])))
        table[key] = letter
    return table


SEMAPHORE = _build_alphabet()


def snap_angle(angle):
    # Round to the nearest spoke and wrap, so -1 and 359 both become 0.
    return int(round(angle / 45.0)) % 8 * 45


def snap_pair(pair):
    left, right = pair
    return tuple(sorted((snap_angle(left), snap_angle(right))))


def parse_angles(text):
    pairs = []
    for token in text.split():
        numbers = token.split(',')
        if len(numbers) != 2:
            raise ValueError('each signal must be two comma-separated angles: %r' % token)
        pairs.append((float(numbers[0]), float(numbers[1])))
    return pairs


def decode(angles):
    letters = []
    previous = None
    numeric = False
    for pair in angles:
        key = snap_pair(pair)
        if key == previous:
            # A repeated position is a pause between signals, not a new symbol.
            continue
        previous = key
        symbol = SEMAPHORE.get(key)
