            numeric = False
            continue
        if numeric:
            # Letters beyond 'K' have no numeric meaning, so keep them as letters.
            letters.append(NUMERALS.get(symbol, symbol))
        else:
            letters.append(symbol)
    return ''.join(letters)


def main(argv):
