DOT_CHARS = " .oO@"


def _block_average(pixels, width, height, x0, y0):
    total = 0
    count = 0
    for dy in range(2):
        y = y0 + dy
        # Rows beyond the bottom edge simply do not contribute to the average
        if y >= height:
            break
        for dx in range(2):
            x = x0 + dx
            # Same for columns: an odd width leaves half-blocks on the right margin
            if x >= width:
                break
            total += pixels[y * width + x]
            count += 1
    return total / count


def _dot_size(average):
    # Split the 0..255 range into five equal buckets, one per dot size
    size = int(average * 5 / 256)
    # Guard against averages slightly above 255 rounding past the last bucket
    return min(size, len(DOT_CHARS) - 1)


def halftone(pixels, width, height):
    if width <= 0 or height <= 0:
        raise ValueError("width and height must be positive")
    if len(pixels) != width * height:
        raise ValueError("pixels must contain exactly width * height values")

    lines = []
    for y0 in range(0, height, 2):
        line = ""
        for x0 in range(0, width, 2):
            average = _block_average(pixels, width, height, x0, y0)
            # Darker blocks (low grayscale) must produce the biggest dots
            line += DOT_CHARS[_dot_size(255 - average)]
        # One output line is complete once width // 2 columns have been emitted
        lines.append(line)
    return "\n".join(lines)


def make_radial_gradient(width, height):
    # Bright in the centre, dark towards the corners, so every dot size appears
    cx = (width - 1) / 2
    cy = (height - 1) / 2
    max_distance = (cx ** 2 + cy ** 2) ** 0.5
    pixels = []
    for y in range(height):
        for x in range(width):
            distance = ((x - cx) ** 2 + (y - cy) ** 2) ** 0.5
            # Normalise the distance so the farthest corner maps to black
            value = 255 * (1 - distance / max_distance)
            pixels.append(int(round(value)))
    return pixels


def main():
    width, height = 48, 24
    image = make_radial_gradient(width, height)
    art = halftone(image, width, height)
    print(art)
    # Report how much ink the pattern uses, counting only the solid blocks
    darkest = sum(row.count(DOT_CHARS[-1]) for row in art.splitlines())
    print("\nsolid blocks: {}".format(darkest))


if __name__ == "__main__":
    main()

