def _validate(current, total, siblings):
    """Reject inputs that cannot describe a real pagination control."""
    # Booleans are ints in Python, but they are never meaningful page numbers.
    for name, value in (("current", current), ("total", total), ("siblings", siblings)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("%s must be an int, got %r" % (name, value))
    if total < 1:
        raise ValueError("total must be at least 1")
    # The current page has to point at a page that actually exists.
    if not 1 <= current <= total:
        raise ValueError("current must be between 1 and %d" % total)
    if siblings < 0:
        raise ValueError("siblings cannot be negative")


def paginate(current, total, siblings):
    """Return page numbers plus ellipsis markers for a pagination bar."""
    _validate(current, total, siblings)
    # Clamp the sibling window so it never leaves the valid page range.
    left = max(current - siblings, 1)
    right = min(current + siblings, total)
    pages = [1]
    # A gap wider than one page is collapsed; a gap of exactly one page is filled.
    if left > 3:
        pages.append(ELLIPSIS)
    elif left == 3:
        pages.append(2)
    # The first and last pages are added separately, so skip them here.
    pages.extend(p for p in range(left, right + 1) if 1 < p < total)
    if right < total - 2:
        pages.append(ELLIPSIS)
    elif right == total - 2:
        # Only the second-to-last page is missing, so show it instead of dots.
        pages.append(total - 1)
    if total > 1:
        pages.append(total)
    return pages


def render(pages, current):
    """Format a pagination list as text, bracketing the active page."""
    parts = []
    for page in pages:
        # Ellipsis entries are plain strings and are never highlighted.
        if page == ELLIPSIS:
            parts.append(ELLIPSIS)
        elif page == current:
            parts.append("[%d]" % page)
        else:
            parts.append(str(page))
    return " ".join(parts)


def report(total, siblings):
    """Build one rendered pagination bar per page of a document."""
    lines = []
    for current in range(1, total + 1):
        lines.append(render(paginate(current, total, siblings), current))
    return lines


