GUARD_BAND_MHZ = 0.2
SPECTRUM_LOW_MHZ = 88.0
SPECTRUM_HIGH_MHZ = 108.0


def validate_requests(requests):
    # Normalizar las solicitudes entrantes y rechazar entradas malformadas.
    cleaned = []
    for entry in requests:
        # Cada solicitud debe ser un par: identificador de estación y ancho de banda.
        if len(entry) != 2:
            raise ValueError("each request needs exactly a station id and a bandwidth")
        station, bandwidth = entry
        width = float(bandwidth)
        # Una estación no puede ocupar espectro cero o negativo.
        if width <= 0:
            raise ValueError("bandwidth for %s must be positive" % station)
        # Nada encajará nunca si una sola solicitud excede toda la banda FM.
        if width > SPECTRUM_HIGH_MHZ - SPECTRUM_LOW_MHZ:
            raise ValueError("bandwidth for %s exceeds the available spectrum" % station)
        cleaned.append((station, width))
    return cleaned


def _first_fit(blocks, needed):
    # Devolver el índice del primer bloque lo suficientemente ancho, o None.
    for index, (low, high) in enumerate(blocks):
        # El redondeo evita que el ruido de punto flotante binario rechace ajustes exactos.
        if round(high - low, 6) >= round(needed, 6):
            return index
    return None


def allocate(requests):
    # Asignar rangos de frecuencia a las estaciones usando una estrategia de primer ajuste.
    pending = validate_requests(requests)
    # El grupo comienza como un bloque contiguo que cubre toda la banda FM.
    blocks = [(SPECTRUM_LOW_MHZ, SPECTRUM_HIGH_MHZ)]
    assignments = []
    for station, width in pending:
        needed = width + GUARD_BAND_MHZ
        slot = _first_fit(blocks, needed)
        # Las estaciones que no se pueden colocar en ningún lugar quedan sin asignar.
        if slot is None:
            continue
        low, high = blocks[slot]
        start = round(low, 6)
        end = round(low + width, 6)
        assignments.append((station, start, end))
        remainder_low = round(end + GUARD_BAND_MHZ, 6)
        # Eliminar el bloque por completo una vez que la banda de guarda consuma lo que queda.
        if remainder_low >= round(high, 6):
            del blocks[slot]
        else:
            blocks[slot] = (remainder_low, high)
    return assignments


def format_report(assignments):
    lines = []
    for station, start, end in assignments:
        # Dos decimales coinciden con la granularidad de la banda de guarda.
        lines.append("%-8s %6.2f - %6.2f MHz" % (station, start, end))
    return "\n".join(lines)


def main():
    requests = [("KXYZ", 0.4), ("WABC", 1.0), ("KJAZ", 0.2), ("WNEW", 15.0), ("KOLD", 5.0)]
    assignments = allocate(requests)
    print(format_report(assignments))
    granted = {station for station, _, _ in assignments}
    # Informar de cualquier cosa que el paso de primer ajuste no pudo colocar.
    for station, width in validate_requests(requests):
        if station not in granted:
            print("%-8s unassigned (%.2f MHz requested)" % (station, width))


if __name__ == "__main__":
    main()

