    "S": 1, "T": 1, "U": 1, "V": 4, "W": 4, "X": 8, "Y": 4, "Z": 10,
}
LETTER_PREMIUMS = {"DL": 2, "TL": 3}
WORD_PREMIUMS = {"DW": 2, "TW": 3}
VOWELS = "AEIOU"


def parse_play(play):
    # A play is either a bare word or a (word, premiums) pair; normalise both forms.
    if isinstance(play, str):
        word, premiums = play, []
    else:
        word, premiums = play[0], list(play[1])
    # Missing premium entries simply mean "plain square" for the trailing letters.
    if len(premiums) < len(word):
        premiums = premiums + [None] * (len(word) - len(premiums))
    elif len(premiums) > len(word):
        raise ValueError("more premium squares than letters in %r" % (word,))
    return word, premiums


def letter_value(letter):
    # Lowercase letters and underscores stand for blank tiles, which are worth nothing.
    if letter == "_" or letter.islower():
        return 0
    if letter not in TILE_VALUES:
        raise ValueError("not a playable tile: %r" % (letter,))
    return TILE_VALUES[letter]


def score_play(play):
    word, premiums = parse_play(play)
    total = 0
    word_multiplier = 1
    for letter, premium in zip(word, premiums):
        value = letter_value(letter)
        key = premium.upper() if premium else None
        # Letter premiums act immediately on the single tile they sit under.
        if key in LETTER_PREMIUMS:
            value *= LETTER_PREMIUMS[key]
