import math

GRAVITY = 9.80665
DISCHARGE_COEFFICIENT = 0.6
SURFACE_TRICKLE_RATE = 0.1
ATMOSPHERE_PER_10_M = 1.0


def valve_area(diameter):
    if diameter <= 0:
        raise ValueError("valve diameter must be positive")
    # A circle's area follows from its radius, which is half the diameter
    return math.pi * (diameter / 2.0) ** 2


def water_pressure(depth):
    if depth < 0:
        raise ValueError("dive depth cannot be negative")
    # One atmosphere of surface air plus one more per ten meters of water
    return 1.0 + depth / 10.0 * ATMOSPHERE_PER_10_M


def inflow_velocity(depth):
    # Torricelli's theorem relates efflux speed to the head of water above the opening
    return math.sqrt(2.0 * GRAVITY * depth)


def flow_rate(diameter, depth):
    area = valve_area(diameter)
    if depth == 0:
        # At the surface there is no pressure head, so only a trickle enters the tank
        return SURFACE_TRICKLE_RATE
    return inflow_velocity(depth) * area * DISCHARGE_COEFFICIENT


def flood(tanks):
    times = []
    for volume, diameter, depth in tanks:
        if volume <= 0:
            raise ValueError("tank volume must be positive")
        # The pressure check rejects negative depths before any square root is taken
        water_pressure(depth)
        rate = flow_rate(diameter, depth)
        # Filling a fixed volume at a constant rate is a simple division
        times.append(volume / rate)
    return times


def report(tanks):
    lines = []
    for (volume, diameter, depth), seconds in zip(tanks, flood(tanks)):
        pressure = water_pressure(depth)
        # Minutes read more naturally than raw seconds for long floodings
        minutes = seconds / 60.0
        lines.append(
            "volume {:.1f} m3, valve {:.3f} m, depth {:.0f} m: "
            "{:.2f} atm, {:.1f} s ({:.2f} min)".format(
                volume, diameter, depth, pressure, seconds, minutes
            )
        )
    return "\n".join(lines)


def main():
    tanks = [
        (30.0, 0.30, 0.0),
        (30.0, 0.30, 50.0),
        (45.5, 0.25, 120.0),
        (12.0, 0.15, 300.0),
    ]
    print(report(tanks))
    # The quickest tank bounds how fast the whole sequence can be completed
    print("fastest: {:.1f} s".format(min(flood(tanks))))


if __name__ == "__main__":
    main()

