import random
from math import floor

ATTRIBUTES = ("strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma")

# Classes that rely on Intelligence for their spell progression.
SPELLCASTERS = frozenset({"wizard", "mage", "artificer", "sorcerer", "warlock", "bard", "arcane trickster"})


def roll_attribute():
    dice = [random.randint(1, 6) for _ in range(4)]
    # Removing the single lowest die leaves a total in the range 3..18.
    dice.remove(min(dice))
    return sum(dice)


def modifier(score):
    # Flooring the halved difference keeps negative modifiers rounding downwards.
    return floor((score - 10) / 2)


def is_viable(scores):
    # A net penalty across the six modifiers makes the array unplayable.
    if sum(modifier(score) for score in scores) < 0:
        return False
    # At least one attribute has to be decent enough to build a character on.
    return max(scores) >= 13


def roll_array():
    # Keep generating six-attribute arrays until one passes the viability test.
    while True:
        scores = [roll_attribute() for _ in ATTRIBUTES]
        if is_viable(scores):
            return scores


def promote_intelligence(scores):
    # Swap the best score into the intelligence slot for spellcasting classes.
    int_index = ATTRIBUTES.index("intelligence")
    best_index = scores.index(max(scores))
    scores[int_index], scores[best_index] = scores[best_index], scores[int_index]
    return scores


def roll(characters):
    arrays = []
    for character in characters:
        # Class names arrive from user input, so normalise before the lookup.
        class_name = str(character).strip().lower()
        scores = roll_array()
        if class_name in SPELLCASTERS:
            scores = promote_intelligence(scores)
        arrays.append(tuple(scores))
    return arrays


def format_sheet(class_name, scores):
    parts = []
    for attribute, score in zip(ATTRIBUTES, scores):
        mod = modifier(score)
        # Show the modifier with an explicit sign, the way a character sheet does.
        parts.append("{} {:2d} ({:+d})".format(attribute[:3].upper(), score, mod))
    return "{:<10} {}".format(class_name, "  ".join(parts))


def main():
    party = ["Fighter", "Wizard", "Cleric", "Rogue", "Bard"]
    arrays = roll(party)
    for class_name, scores in zip(party, arrays):
        print(format_sheet(class_name, scores))
    # A party-wide summary helps spot an unusually lucky session.
    total = sum(modifier(score) for scores in arrays for score in scores)
    print("Party modifier total: {:+d}".format(total))


if __name__ == "__main__":
    main()

