INTERVAL_SECONDS = 30
MAILLARD_THRESHOLD = 150.0
CRACK_BASE_TEMP = 200.0
CRACK_RATE = 10.0


def _validate(temperatures):
    # A roast profile needs at least three readings: start, turning point and drop.
    if not isinstance(temperatures, (list, tuple)) or len(temperatures) < 3:
        raise ValueError("temperatures must be a sequence of at least 3 readings")
    for position, reading in enumerate(temperatures):
        # Booleans are ints in Python, but they are never valid probe readings.
        if isinstance(reading, bool) or not isinstance(reading, (int, float)):
            raise TypeError("reading at index %d is not numeric" % position)


def find_turning_point(temperatures):
    # The turning point is the coldest moment, and it can never be the charge reading itself.
    coldest = 1
    for index in range(2, len(temperatures)):
        if temperatures[index] < temperatures[coldest]:
            coldest = index
    return coldest


def find_maillard_start(temperatures, after):
    # Browning only counts once the beans have turned around and are climbing again.
    for index in range(after, len(temperatures)):
        if temperatures[index] > MAILLARD_THRESHOLD:
            return index
    return None


def find_first_crack(temperatures, after):
    for index in range(max(after, 1), len(temperatures)):
        previous = temperatures[index - 1]
        # The audible crack is a sudden jump measured against the previous half-minute.
        rate = temperatures[index] - previous
        if previous >= CRACK_BASE_TEMP and rate > CRACK_RATE:
            return index
    return None


def development_time_ratio(crack_index, total_readings):
    # Durations are counted in intervals between readings, hence the minus one.
    total_duration = (total_readings - 1) * INTERVAL_SECONDS
    development = (total_readings - 1 - crack_index) * INTERVAL_SECONDS
    return development / total_duration


def roast(temperatures):
    _validate(temperatures)
    turning_point = find_turning_point(temperatures)
    maillard_start = find_maillard_start(temperatures, turning_point + 1)
    # Without browning there is no crack to look for, so search from the turning point.
    search_from = maillard_start if maillard_start is not None else turning_point
    first_crack = find_first_crack(temperatures, search_from)
    ratio = None
    if first_crack is not None:
        ratio = development_time_ratio(first_crack, len(temperatures))
    return {
        "turning_point": turning_point,
        "maillard_start": maillard_start,
        "first_crack": first_crack,
        "development_time_ratio": ratio,
    }


def format_report(result):
    lines = []
    for key in ("turning_point", "maillard_start", "first_crack"):
        index = result[key]
        # An unreached phase is reported as such rather than as a fake timestamp.
        if index is None:
            lines.append("%-15s not reached" % key)
        else:
            lines.append("%-15s index %d (%d s)" % (key, index, index * INTERVAL_SECONDS))
    ratio = result["development_time_ratio"]
    lines.append("dtr             %s" % ("n/a" if ratio is None else "%.1f%%" % (ratio * 100)))
    return "\n".join(lines)


def main():
    profile = [200, 120, 95, 104, 128, 152, 175, 190, 198, 204, 216, 221, 225]
    print(format_report(roast(profile)))


