# Beam steering: cumulative correction kicks for a line of magnet stations.

MAX_KICK = 0.005          # safety threshold: five milliradians per station
COOLING_FACTOR = 0.8      # each station cools the beam, shrinking the offsets by 20%


def validate_station(station):
    # A station must unpack into exactly three numbers, otherwise the optics model is undefined.
    if len(station) != 3:
        raise ValueError("each magnet station needs 3 values: h_offset, v_offset, strength")
    h_offset, v_offset, strength = station
    for value in (h_offset, v_offset, strength):
        # Booleans are ints in Python, but they are never meaningful beam measurements.
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("magnet station values must be numeric")
    # A negative field strength would flip the kick sign; the hardware cannot do that.
    if strength < 0:
        raise ValueError("magnetic field strength cannot be negative")
    return float(h_offset), float(v_offset), float(strength)


def deflection(h_offset, v_offset, strength):
    # The kick of one station is proportional to the product of both offsets and the field.
    return h_offset * v_offset * strength


def steer(magnets):
    total_angle = 0.0
    dump = False
    # The cooling transformation is cumulative: station n sees offsets damped n times.
    cooling = 1.0

    for station in magnets:
        h_offset, v_offset, strength = validate_station(station)
        angle = deflection(h_offset * cooling, v_offset * cooling, strength)
        # Only the magnitude matters for the interlock: a huge negative kick is just as unsafe.
        if abs(angle) > MAX_KICK:
            # Clamp to the limit while preserving the direction of the kick, then dump the beam.
            angle = MAX_KICK if angle > 0 else -MAX_KICK
            dump = True
        total_angle += angle
        cooling *= COOLING_FACTOR

    return total_angle, dump


def format_report(magnets):
    total_angle, dump = steer(magnets)
    status = "EMERGENCY DUMP" if dump else "nominal"
    # Milliradians read better than radians on the control-room display.
    return "stations={0} total={1:.3f} mrad status={2}".format(
        len(magnets), total_angle * 1000.0, status)


def main():
    nominal_chain = [(0.002, 0.001, 0.8), (0.0015, 0.0012, 1.1), (0.001, 0.0009, 0.95)]
    # Ten milliradians of demanded kick: capped at five and the interlock fires at once.
    runaway_chain = [(0.1, 0.1, 1.0), (0.002, 0.001, 0.9)]

    for label, chain in (("nominal", nominal_chain), ("runaway", runaway_chain)):
        print(label, "->", format_report(chain))


if __name__ == "__main__":
    main()

