# Utilities for finding the largest integer in a list, plus a small report driver.


def find_max(numbers):
    # Track the running maximum instead of sorting, so a single pass suffices.
    largest = numbers[0]
    for value in numbers[1:]:
        # Strict comparison keeps the first occurrence of a repeated maximum.
        if value > largest:
            largest = value
    return largest


def parse_numbers(text):
    # Commas are turned into spaces so both separators work with one split call.
    cleaned = text.replace(",", " ")
    numbers = []
    for token in cleaned.split():
        try:
            numbers.append(int(token))
        except ValueError:
            # Re-raise with the offending token, which is far more useful to a caller.
            raise ValueError("not an integer: {!r}".format(token))
    return numbers


def validate(numbers):
