import re
import sys

# Words are letter or digit runs that may contain internal apostrophes or
# hyphens, so forms like "don't" and "well-known" survive tokenisation intact.
WORD_RE = re.compile(r"[a-z0-9]+(?:['\u2019-][a-z0-9]+)*")


def tokenize(text):
    """Split text into lowercase words, dropping punctuation."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Lowercasing first keeps the pattern itself simple and case-free.
    return WORD_RE.findall(text.lower())


def word_frequency(text):
    """Return a dict mapping each lowercase word to its number of occurrences."""
    counts = {}
    for word in tokenize(text):
        # dict.get avoids a separate membership test for first sightings.
        counts[word] = counts.get(word, 0) + 1
    return counts


def top_words(freqs, n=10):
    """Return the n most frequent (word, count) pairs, ties broken alphabetically."""
    if n < 0:
        raise ValueError("n must be non-negative")
    # Negating the count sorts descending by frequency while the word
    # stays ascending, which gives a predictable listing.
    ordered = sorted(freqs.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:n]


def format_report(text, n=10):
    """Build a human-readable frequency table for the given text."""
    freqs = word_frequency(text)
    pairs = top_words(freqs, n)
    if not pairs:
        return "no words found"
    total = sum(freqs.values())
    # Column width is driven by the longest word actually shown.
    width = max(len(word) for word, _ in pairs)
    lines = ["{} words counted, {} distinct".format(total, len(freqs))]
    for word, count in pairs:
        share = 100.0 * count / total
        lines.append("{:<{w}}  {:>5}  {:>5.1f}%".format(word, count, share, w=width))
    return "\n".join(lines)


def main(argv):
    # Any extra argument is read as a limit on how many rows to print.
    limit = 10
    if len(argv) > 1:
        try:
            limit = int(argv[1])
        except ValueError:
            print("usage: word_frequency.py [limit]", file=sys.stderr)
            return 2
    # Reading everything at once is fine here: shares and ranking need the
    # full text before any count can be reported.
    text = sys.stdin.read()
    print(format_report(text, limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

