# The alphabet is fixed by the task: lowercase, uppercase and digits only.
ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits


def generate_password(length):
    """Return a random password of exactly `length` characters."""
    # Booleans are integers in Python, but they are not sensible lengths.
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    # A negative or zero length would silently give an empty string.
    if length < 1:
        raise ValueError("length must be at least 1")
    # random.choice is called once per position, so repeats are possible.
    return "".join(random.choice(ALPHABET) for _ in range(length))


def character_classes(password):
    """Map each character class name to how often it occurs in `password`."""
    counts = {"lowercase": 0, "uppercase": 0, "digits": 0}
    for char in password:
        # Digits are tested first so the later branches only see letters.
        if char in string.digits:
            counts["digits"] += 1
        elif char in string.ascii_lowercase:
            counts["lowercase"] += 1
        else:
            counts["uppercase"] += 1
    return counts


def generate_strong_password(length):
    """Generate a password that contains at least one of every class."""
    # With fewer than three characters one of the classes is always absent.
    if length < 3:
        raise ValueError("a strong password needs at least 3 characters")
    while True:
        candidate = generate_password(length)
        counts = character_classes(candidate)
        # Retry until no class is missing; each draw is independent.
        if all(counts.values()):
            return candidate


def entropy_bits(length):
    """Approximate the entropy of a uniform password of the given length."""
    return round(length * math.log2(len(ALPHABET)), 1)


def describe(password):
    """Build a one-line human readable report about a password."""
    counts = character_classes(password)
    parts = []
    for name in ("lowercase", "uppercase", "digits"):
        # Skip classes that did not appear, to keep the report compact.
        if counts[name]:
            parts.append("{} {}".format(counts[name], name))
    return "{}  (len={}, {}, ~{} bits)".format(
        password, len(password), ", ".join(parts), entropy_bits(len(password))
    )


def main():
    print(describe(generate_password(8)))
    for size in (4, 12, 20):
        # Strong passwords are more useful in practice than purely random ones.
        print(describe(generate_strong_password(size)))


if __name__ == "__main__":
    main()

