def has_unique_chars(s):
    # Guard against non-string input so the loop below cannot fail silently
    if not isinstance(s, str):
        raise TypeError("has_unique_chars expects a string")
    seen = set()
    for ch in s:
        # A character already in the set means the string is not unique
        if ch in seen:
            return False
        seen.add(ch)
    return True


def first_duplicate(s):
    # Walk left to right so the first repeat encountered is the earliest one
    seen = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    # Reaching the end without a hit means no character repeated
    return None


def duplicate_counts(s):
    # Tally every character, then keep only the ones that appear more than once
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return {ch: n for ch, n in counts.items() if n > 1}


def describe(ch):
    # Invisible characters need a name, otherwise the report looks empty
    labels = {" ": "<space>", "\t": "<tab>", "\n": "<newline>"}
    return labels.get(ch, repr(ch))


def report(s):
    if has_unique_chars(s):
        return "%r: all %d characters are unique" % (s, len(s))
    culprit = first_duplicate(s)
    counts = duplicate_counts(s)
    # Sort by descending frequency, then alphabetically, for stable output
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    details = ", ".join("%s x%d" % (describe(ch), n) for ch, n in ordered)
    return "%r: not unique (first repeat %s; %s)" % (s, describe(culprit), details)


def main():
    samples = [
        "abc",
        "abca",
        "",
        "AaBb",
        "hello world",
        "the quick brown fox",
    ]
    for sample in samples:
        print(report(sample))

    unique_only = [s for s in samples if has_unique_chars(s)]
    # The summary line closes the report with the overall hit rate
    print("unique strings: %d of %d" % (len(unique_only), len(samples)))


if __name__ == "__main__":
    main()

