# Utilities for locating the second largest value in a list of integers.


def find_second_largest(numbers):
    # Ranking two positions requires at least two values to rank.
    if len(numbers) < 2:
        raise ValueError("need at least two numbers")
    largest = second = None
    for value in numbers:
        if largest is None or value > largest:
            # The old champion is pushed down into second place.
            second = largest
            largest = value
        elif second is None or value > second:
            # Duplicates of the maximum are kept, so [1, 1, 5, 5] yields 5.
            second = value
    return second


def parse_numbers(text):
    # Commas are treated as plain separators so "1, 2 3" works as expected.
    tokens = text.replace(",", " ").split()
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            # Report the offending token instead of the generic int() message.
            raise ValueError("not an integer: %r" % token)
    return numbers


def has_two_distinct(numbers):
    first = numbers[0]
    for value in numbers:
        # As soon as one element differs from the first, we are done.
        if value != first:
            return True
    return False


def describe(text):
    try:
        numbers = parse_numbers(text)
    except ValueError as exc:
        return "%-20s -> error: %s" % (text, exc)
    # Both preconditions are checked before the result can be trusted.
    if len(numbers) < 2 or not has_two_distinct(numbers):
        return "%-20s -> error: needs two distinct elements" % text
    return "%-20s -> %d" % (text, find_second_largest(numbers))


def main():
    samples = [
        "10 5 20 8",
        "1 1 5 5",
        "-3, -7, -3, -10",
        "42 42",
        "7",
        "4 x 9",
    ]
    for sample in samples:
        # Each sample is reported independently; bad input never aborts the run.
        print(describe(sample))


if __name__ == "__main__":
    main()

