        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value = 0  # Inicializa el valor entero total.
    prev_value = 0  # Inicializa el valor del numeral procesado anteriormente.

    # Itera a través de la cadena del número romano de derecha a izquierda.
    for char in reversed(roman_numeral):
