def validate_interval(start, end):
    # Times must be integers; booleans are rejected because they are not real clock values.
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError("event times must be integers, not booleans")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers")
    # A zero-length or reversed interval cannot describe a real event.
    if start >= end:
        raise ValueError("event start must be strictly before its end")
    return start, end


def validate_schedule(schedule):
    # The schedule is normalised into a list so generators can be passed in safely.
    intervals = []
    for entry in schedule:
        start, end = entry  # unpacking also rejects malformed entries
        intervals.append(validate_interval(start, end))
    return intervals


def overlaps(a_start, a_end, b_start, b_end):
    # Half-open intervals: touching endpoints (5 and 5) do not count as a clash.
    return a_start < b_end and b_start < a_end


def has_conflict(schedule, new_event_start, new_event_end):
    new_start, new_end = validate_interval(new_event_start, new_event_end)
    for start, end in validate_schedule(schedule):
        # Any single overlap is enough to decide, so we can stop immediately.
        if overlaps(new_start, new_end, start, end):
            return True
    return False


def find_conflicts(schedule, new_event_start, new_event_end):
    new_start, new_end = validate_interval(new_event_start, new_event_end)
    conflicts = []
    for start, end in validate_schedule(schedule):
        if overlaps(new_start, new_end, start, end):
            conflicts.append((start, end))
    # Keep the report deterministic regardless of the input ordering.
    conflicts.sort()
    return conflicts


def try_book(schedule, new_event_start, new_event_end):
    clashes = find_conflicts(schedule, new_event_start, new_event_end)
    if clashes:
        # Booking failed: the caller's schedule is left untouched.
        return False, clashes
    schedule.append((new_event_start, new_event_end))
    schedule.sort()
    return True, []


def format_result(new_event_start, new_event_end, booked, clashes):
    label = "%d-%d" % (new_event_start, new_event_end)
    if booked:
        return "booked %s" % label
    # Render each blocking event so the message explains the refusal.
    blockers = ", ".join("%d-%d" % pair for pair in clashes)
    return "rejected %s (conflicts with %s)" % (label, blockers)


def main():
    schedule = [(1, 5), (10, 15)]
    requests = [(3, 7), (6, 8), (5, 10), (15, 20), (12, 13)]
    for start, end in requests:
        booked, clashes = try_book(schedule, start, end)
        print(format_result(start, end, booked, clashes))
    # The final agenda contains only the requests that were accepted.
    print("final schedule:", schedule)


if __name__ == "__main__":
    main()

