def normalize_inventory(inventory):
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item -> quantity")
    clean = {}
    for item, quantity in inventory.items():
        # Item names become keys of the returned mapping, so they must be strings.
        if not isinstance(item, str):
            raise TypeError("inventory keys must be strings, got %r" % (item,))
        # Booleans are instances of int, but they are never meaningful quantities.
        if isinstance(quantity, bool) or not isinstance(quantity, int):
            raise TypeError("quantity for %r must be an int" % item)
        if quantity < 0:
            raise ValueError("quantity for %r cannot be negative" % item)
        # Trim surrounding blanks so that " apple" and "apple" refer to one product.
        clean[item.strip()] = quantity
    return clean


def check_stock(inventory, items_to_check):
    # Validate and canonicalise the inventory before any lookup happens.
    stock = normalize_inventory(inventory)
    if not isinstance(items_to_check, list):
        raise TypeError("items_to_check must be a list of strings")
    stock_levels = {}
    for item in items_to_check:
        if not isinstance(item, str):
            raise TypeError("items_to_check must contain strings, got %r" % (item,))
        key = item.strip()
        # Unknown products are reported as out of stock rather than skipped.
        stock_levels[key] = stock.get(key, 0)
    return stock_levels


def missing_items(stock_levels):
    # Request order is preserved because dictionaries keep insertion order.
    return [item for item, quantity in stock_levels.items() if quantity == 0]


def restock_plan(stock_levels, target_level):
    if target_level < 0:
        raise ValueError("target_level cannot be negative")
    plan = {}
    for item, quantity in stock_levels.items():
        shortfall = target_level - quantity
        # Only understocked items belong in the plan; surplus is left untouched.
        if shortfall > 0:
            plan[item] = shortfall
    return plan


def format_report(stock_levels, target_level):
    lines = []
    plan = restock_plan(stock_levels, target_level)
    # Align the item column using the longest name so the numbers line up.
    width = max((len(item) for item in stock_levels), default=0)
    for item, quantity in stock_levels.items():
        note = ""
        if item in plan:
            note = "  (order %d)" % plan[item]
        lines.append("%-*s %5d%s" % (width, item, quantity, note))
    empty = missing_items(stock_levels)
    if empty:
        lines.append("Out of stock: " + ", ".join(empty))
    return lines


def main():
    inventory = {"apple": 10, "banana": 5, " cherry ": 0, "date": 42}
    requested = ["apple", "orange", "cherry", "date"]
    stock_levels = check_stock(inventory, requested)
    # A target of twelve units per product drives the restock suggestions below.
    for line in format_report(stock_levels, 12):
        print(line)
    print("Raw result:", stock_levels)


