# Utilities for analysing character frequencies in a piece of text.

from collections import Counter


def char_counts(text):
    """Return a Counter mapping each character of *text* to its frequency."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Counter preserves first-insertion order for equal counts, which the
    # "first one encountered" tie-break rule relies on.
    return Counter(text)


def least_frequent_char(text):
    """Return the character occurring least often; ties go to the first seen."""
    counts = char_counts(text)
    if not counts:
        raise ValueError("cannot analyse an empty string")
    best_char = None
    best_count = None
    # Iterating the Counter walks characters in order of first appearance,
    # so a strict "<" comparison keeps the earliest of the tied minima.
    for char, count in counts.items():
        if best_count is None or count < best_count:
            best_char, best_count = char, count
    return best_char


def most_frequent_char(text):
    """Counterpart of least_frequent_char, used by the summary report."""
    counts = char_counts(text)
    if not counts:
        raise ValueError("cannot analyse an empty string")
    best_char, best_count = None, None
    for char, count in counts.items():
        # Again "<" / ">" without "=" protects the first-encountered winner.
        if best_count is None or count > best_count:
            best_char, best_count = char, count
    return best_char


def describe_char(char):
    """Make a character printable, spelling out whitespace explicitly."""
    names = {" ": "<space>", "\t": "<tab>", "\n": "<newline>"}
    # Invisible characters would otherwise ruin the alignment of the report.
    return names.get(char, repr(char))


def frequency_report(text):
    """Build a multi-line human-readable frequency summary for *text*."""
    counts = char_counts(text)
    lines = ["Text: {!r}".format(text), "Distinct characters: {}".format(len(counts))]
    # Sort by descending count, then by first-appearance order for stability.
    order = list(counts)
    for char in sorted(order, key=lambda c: (-counts[c], order.index(c))):
        lines.append("  {:<10} {}".format(describe_char(char), counts[char]))
    lines.append("Least frequent: {}".format(describe_char(least_frequent_char(text))))
    lines.append("Most frequent:  {}".format(describe_char(most_frequent_char(text))))
    return "\n".join(lines)


def main():
    samples = ["hello world", "aabbc", "mississippi river"]
    for sample in samples:
        print(frequency_report(sample))
        print()
    # Empty input has no answer at all, so show the error instead of crashing.
    try:
        least_frequent_char("")
    except ValueError as exc:
        print("Rejected empty input:", exc)


if __name__ == "__main__":
    main()

