def _validate_shape(matrix, name):
    # A matrix needs at least one row before a shape can be determined.
    if not isinstance(matrix, list) or not matrix:
        raise ValueError(name + " must be a non-empty list of rows")
    width = None
    for index, row in enumerate(matrix):
        # Every row has to be a list; a bare number is not a valid row.
        if not isinstance(row, list):
            raise ValueError("%s row %d is not a list" % (name, index))
        # The first row defines the expected width of all later rows.
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("%s is ragged at row %d" % (name, index))
        for column, value in enumerate(row):
            # bool is a subclass of int, so reject it explicitly.
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("%s[%d][%d] is not a number" % (name, index, column))
    return len(matrix), width


def matrix_subtract(matrix1, matrix2):
    rows1, cols1 = _validate_shape(matrix1, "matrix1")
    rows2, cols2 = _validate_shape(matrix2, "matrix2")
    # The subtraction is only defined for matrices of identical dimensions.
    if (rows1, cols1) != (rows2, cols2):
        raise ValueError("dimension mismatch: %dx%d vs %dx%d" % (rows1, cols1, rows2, cols2))
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        # zip pairs up the entries of the two rows position by position.
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def _format_cell(value):
    # Floats holding an exact integer print without a trailing ".0".
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix):
    cells = [[_format_cell(value) for value in row] for row in matrix]
    # One column width per column, taken as the widest rendered entry.
    widths = [max(len(row[c]) for row in cells) for c in range(len(cells[0]))]
    lines = []
    for row in cells:
        padded = [text.rjust(widths[c]) for c, text in enumerate(row)]
        lines.append("[ " + "  ".join(padded) + " ]")
    return "\n".join(lines)


def report(matrix1, matrix2):
    difference = matrix_subtract(matrix1, matrix2)
    print(format_matrix(matrix1))
    print("  minus")
    print(format_matrix(matrix2))
    print("  equals")
    print(format_matrix(difference))
    return difference


def main():
    pairs = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        ([[2.5, -3.0], [0.5, 8.0]], [[0.5, 1.5], [1.0, 2.25]]),
    ]
    for matrix1, matrix2 in pairs:
        report(matrix1, matrix2)
        # Blank line keeps consecutive reports visually separated.
        print()


if __name__ == "__main__":
    main()

