# Stock transaction profit/loss calculator: computes the absolute and
# relative result of a single buy-then-sell trade.


def _validate_trade(buy_price, sell_price, quantity):
    # Prices arrive from user input or CSV rows, so reject non-numeric types early
    for name, value in (("buy_price", buy_price), ("sell_price", sell_price)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a number, got {type(value).__name__}")
        if value < 0:
            raise ValueError(f"{name} cannot be negative")
    # A fractional share count makes no sense for a whole-lot transaction
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise TypeError("quantity must be an int")
    if quantity <= 0:
        raise ValueError("quantity must be positive")


def calculate_stock_profit(buy_price, sell_price, quantity):
    # Total profit is positive, a loss is negative
    _validate_trade(buy_price, sell_price, quantity)
    # Per-share difference scaled by the lot size gives the total result
    profit_loss = (sell_price - buy_price) * quantity
    # Money is only meaningful to the cent; this also removes float noise
    return round(float(profit_loss), 2)


def return_percentage(buy_price, sell_price):
    # Percentage change between buy and sell price, validated as a single share
    _validate_trade(buy_price, sell_price, 1)
    # A zero cost basis (e.g. gifted shares) has no defined percentage return
    if buy_price == 0:
        return float("inf") if sell_price > 0 else 0.0
    return round((sell_price - buy_price) / buy_price * 100.0, 2)


def format_trade_report(symbol, buy_price, sell_price, quantity):
    # One-line human readable summary of a closed position
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    pct = return_percentage(buy_price, sell_price)
    # Label the outcome instead of leaving the reader to decode the sign
    if profit_loss > 0:
        verdict = "PROFIT"
    elif profit_loss < 0:
        verdict = "LOSS"
    else:
        verdict = "BREAK-EVEN"
    return (
        f"{symbol:<6} {quantity:>5} @ {buy_price:>8.2f} -> {sell_price:>8.2f}  "
        f"{verdict:<11} {profit_loss:>10.2f} ({pct:+.2f}%)"
    )


def portfolio_total(trades):
    # Accumulate the already-rounded per-trade figures so the total matches the report
    total = 0.0
    for _symbol, buy_price, sell_price, quantity in trades:
        total += calculate_stock_profit(buy_price, sell_price, quantity)
    return round(total, 2)


def main():
    trades = [
