# Calculadora de ganancias/pérdidas de transacciones de acciones: calcula el resultado
# absoluto y relativo de una única operación de compra y posterior venta.


def _validate_trade(buy_price, sell_price, quantity):
    # Los precios provienen de la entrada del usuario o de filas CSV, así que rechaza pronto los tipos no numéricos
    for name, value in (("buy_price", buy_price), ("sell_price", sell_price)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a number, got {type(value).__name__}")
        if value < 0:
            raise ValueError(f"{name} cannot be negative")
    # Un número fraccionario de acciones no tiene sentido para una transacción de lote completo
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise TypeError("quantity must be an int")
    if quantity <= 0:
        raise ValueError("quantity must be positive")


def calculate_stock_profit(buy_price, sell_price, quantity):
    # La ganancia total es positiva, una pérdida es negativa
    _validate_trade(buy_price, sell_price, quantity)
    # La diferencia por acción escalada por el tamaño del lote da el resultado total
    profit_loss = (sell_price - buy_price) * quantity
    # El dinero solo tiene sentido hasta el céntimo; esto también elimina el ruido de los flotantes
    return round(float(profit_loss), 2)


def return_percentage(buy_price, sell_price):
    # Cambio porcentual entre el precio de compra y el de venta, validado como una sola acción
    _validate_trade(buy_price, sell_price, 1)
    # Una base de coste cero (p. ej. acciones regaladas) no tiene un retorno porcentual definido
    if buy_price == 0:
        return float("inf") if sell_price > 0 else 0.0
    return round((sell_price - buy_price) / buy_price * 100.0, 2)


def format_trade_report(symbol, buy_price, sell_price, quantity):
    # Resumen legible por humanos en una línea de una posición cerrada
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    pct = return_percentage(buy_price, sell_price)
    # Etiqueta el resultado en lugar de dejar que el lector descifre el signo
    if profit_loss > 0:
        verdict = "PROFIT"
    elif profit_loss < 0:
        verdict = "LOSS"
    else:
        verdict = "BREAK-EVEN"
    return (
        f"{symbol:<6} {quantity:>5} @ {buy_price:>8.2f} -> {sell_price:>8.2f}  "
        f"{verdict:<11} {profit_loss:>10.2f} ({pct:+.2f}%)"
    )


def portfolio_total(trades):
    # Acumula las cifras por operación ya redondeadas para que el total coincida con el informe
    total = 0.0
    for _symbol, buy_price, sell_price, quantity in trades:
        total += calculate_stock_profit(buy_price, sell_price, quantity)
    return round(total, 2)


def main():
    trades = [
        ("AAPL", 10.0, 12.0, 100),
        ("MSFT", 15.0, 13.0, 50),
        ("KO", 42.5, 42.5, 20),
    ]
    for trade in trades:
        print(format_trade_report(*trade))
    total = portfolio_total(trades)
    # Alinea a la derecha el pie bajo los importes por operación para facilitar la lectura
    print(f"{'TOTAL':<6} {'':>5}   {'':>8}    {'':>8}  {'':<11} {total:>10.2f}")


if __name__ == "__main__":
    main()

