def is_brackets_balanced(s: str) -> bool:
    stack = []  # Inicializa una pila vacía para llevar un registro de los corchetes de apertura.
    mapping = {")": "(", "]": "[", "}": "{"}  # Define un mapeo de corchetes de cierre a apertura.

    # Itera a través de cada carácter en la cadena de entrada.
    for char in s:
        # Comprueba si el carácter actual es un corchete de apertura.
        if char in mapping.values():
            stack.append(char)  # Si es un corchete de apertura, lo empuja a la pila.
        # Comprueba si el carácter actual es un corchete de cierre.
        elif char in mapping:
            # Si la pila está vacía o la parte superior de la pila no coincide con el corchete de apertura correspondiente, está desequilibrado.
            if not stack or stack.pop() != mapping[char]:
                return False  # Se encontró una falta de coincidencia o la pila está vacía, por lo que se devuelve False.

    # Después de iterar a través de todos los caracteres, si la pila está vacía, todos los corchetes estaban equilibrados.
    return not stack  # Devuelve True si la pila está vacía, indicando que todos los corchetes coinciden.

