def _validate(meeting, name):
    # A meeting must be a pair; anything else is a programming error at the call site.
    if not isinstance(meeting, (tuple, list)) or len(meeting) != 2:
        raise ValueError(f"{name} must be a (start, end) pair, got {meeting!r}")
    start, end = meeting
    # Booleans are ints in Python, but they are never sensible clock values.
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError(f"{name} must contain integers, not booleans")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(f"{name} must contain integers, got {meeting!r}")
    # Zero-length meetings are tolerated, reversed ones are not.
    if start > end:
        raise ValueError(f"{name} ends before it starts: {meeting!r}")
    return start, end


def has_overlap(meeting1, meeting2):
    a_start, a_end = _validate(meeting1, "meeting1")
    b_start, b_end = _validate(meeting2, "meeting2")
    # Two intervals intersect only if each one starts before the other ends.
    # End times are exclusive, so touching intervals such as (1, 3) and (3, 5) do not clash.
    return a_start < b_end and b_start < a_end


def overlap_minutes(meeting1, meeting2):
    a_start, a_end = _validate(meeting1, "meeting1")
    b_start, b_end = _validate(meeting2, "meeting2")
    # The shared span runs from the later start to the earlier end.
    shared = min(a_end, b_end) - max(a_start, b_start)
    return max(shared, 0)


def find_conflicts(meetings):
    conflicts = []
    # Compare every unordered pair once; the schedules handled here are small.
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):
            if has_overlap(meetings[i], meetings[j]):
                conflicts.append((i, j))
    return conflicts


def format_interval(meeting):
    start, end = _validate(meeting, "meeting")
    # Show the half-open nature of the interval explicitly in the report.
    return f"[{start}, {end})"


def report(meetings):
    lines = [f"{i}: {format_interval(m)}" for i, m in enumerate(meetings)]
    conflicts = find_conflicts(meetings)
    if not conflicts:
        lines.append("no conflicts")
        return "\n".join(lines)
    for i, j in conflicts:
        shared = overlap_minutes(meetings[i], meetings[j])
        # Report the amount of clashing time so a scheduler can decide what to move.
        lines.append(f"conflict: {i} vs {j} ({shared} min)")
    return "\n".join(lines)


def main():
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))
    schedule = [(540, 600), (570, 630), (630, 690), (700, 720)]
    print(report(schedule))


if __name__ == "__main__":
    main()

