import random
import re
from collections import Counter

# Dice notation looks like "3d6" or "d20"; the count defaults to 1 when omitted.
DICE_PATTERN = re.compile(r"^\s*(\d*)\s*[dD]\s*(\d+)\s*$")


def roll_die(num_sides):
    # bool is a subclass of int, but True as a side count is a caller mistake.
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an int")
    # A die needs at least one face, so reject anything smaller than 1.
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    # randint is inclusive on both ends, which matches the required range.
    return random.randint(1, num_sides)


def roll_dice(count, num_sides):
    # Rolling zero or fewer dice has no meaningful result.
    if count < 1:
        raise ValueError("count must be at least 1")
    return [roll_die(num_sides) for _ in range(count)]


def parse_dice_notation(text):
    match = DICE_PATTERN.match(text)
    if match is None:
        raise ValueError("unrecognised dice notation: %r" % (text,))
    count_text, sides_text = match.groups()
    # An empty count group means the notation was written as plain "d20".
    count = int(count_text) if count_text else 1
    return count, int(sides_text)


def roll_notation(text):
    # The face count is returned alongside the rolls so reports can list every face.
    count, sides = parse_dice_notation(text)
    return roll_dice(count, sides), sides


def histogram(results, num_sides):
    tally = Counter(results)
    # Faces that never came up should still be reported, with a count of zero.
    return {face: tally.get(face, 0) for face in range(1, num_sides + 1)}


def format_report(notation, results, num_sides):
    lines = ["%s -> total %d" % (notation, sum(results))]
    counts = histogram(results, num_sides)
    # The busiest face sets the bar scale; guard against a divisor of zero.
    width = max(counts.values()) or 1
    for face, hits in counts.items():
        # Scale each bar to at most 30 characters so wide dice stay readable.
        bar = "#" * round(30 * hits / width)
        lines.append("  %3d | %-30s %d" % (face, bar, hits))
    return "\n".join(lines)


def main():
    # A fixed seed keeps the printed report reproducible between runs.
    random.seed(20260918)
    print("one d6 :", roll_die(6))
    print("one d20:", roll_die(20))
    for notation in ("3d6", "d20", "100d4"):
        results, sides = roll_notation(notation)
        print(format_report(notation, results, sides))


if __name__ == "__main__":
    main()

