# Utilities for detecting scheduling conflicts between hour-based tasks.

from itertools import combinations

# Tasks are expressed in whole hours on a 24-hour clock, so 0 and 24 are the bounds.
DAY_START = 0
DAY_END = 24


def validate_interval(start, end, label="task"):
    # Booleans are a subclass of int, but they never make sense as clock hours.
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError(f"{label} times must be integers, not booleans")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(f"{label} times must be integers")
    if not (DAY_START <= start <= DAY_END and DAY_START <= end <= DAY_END):
        raise ValueError(f"{label} times must lie between {DAY_START} and {DAY_END}")
    # A task that ends before (or exactly when) it starts occupies no time at all.
    if start >= end:
        raise ValueError(f"{label} must start strictly before it ends")


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    validate_interval(task1_start, task1_end, "task1")
    validate_interval(task2_start, task2_end, "task2")
    # Two half-open intervals intersect only if each one begins before the other ends.
    return task1_start < task2_end and task2_start < task1_end


def overlap_hours(task1_start, task1_end, task2_start, task2_end):
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return 0
    # The shared span runs from the later start to the earlier end.
    return min(task1_end, task2_end) - max(task1_start, task2_start)


def format_hour(hour):
    # Hour 24 is the end of the day and is conventionally written as 24:00.
    return f"{hour:02d}:00"


def find_conflicts(schedule):
    conflicts = []
    # Comparing each unordered pair once avoids reporting the same clash twice.
    for (name_a, start_a, end_a), (name_b, start_b, end_b) in combinations(schedule, 2):
        shared = overlap_hours(start_a, end_a, start_b, end_b)
        if shared:
            conflicts.append((name_a, name_b, shared))
    # Sorting by the largest overlap first puts the worst clashes at the top.
    conflicts.sort(key=lambda item: -item[2])
    return conflicts


def report(schedule):
    lines = [f"{name}: {format_hour(s)}-{format_hour(e)}" for name, s, e in schedule]
    conflicts = find_conflicts(schedule)
    if not conflicts:
        lines.append("No conflicts found.")
        return "\n".join(lines)
    for name_a, name_b, shared in conflicts:
        # Pluralise the unit so the message reads naturally for a single hour.
        unit = "hour" if shared == 1 else "hours"
        lines.append(f"Conflict: {name_a} and {name_b} overlap by {shared} {unit}")
    return "\n".join(lines)


def main():
    schedule = [
        ("standup", 9, 10),
        ("review", 9, 12),
        ("lunch", 12, 13),
        ("deep work", 11, 14),
    ]
    print(report(schedule))
    # Touching intervals such as 9-10 and 10-12 are reported as conflict-free.
    print("9-10 vs 10-12:", has_overlap(9, 10, 10, 12))


if __name__ == "__main__":
    main()

