def _validate_inputs(principal, rate, time):
    # Reject non-numeric input early so the arithmetic below cannot fail cryptically
    for name, value in (("principal", principal), ("rate", rate), ("time", time)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a number, got {type(value).__name__}")
    # A negative principal or rate has no meaning for a savings or loan calculation
    if principal < 0:
        raise ValueError("principal must not be negative")
    if rate < 0:
        raise ValueError("rate must not be negative")
    # The time period is counted in whole years, so fractions are not accepted
    if int(time) != time:
        raise ValueError("time must be a whole number of years")
    if time < 0:
        raise ValueError("time must not be negative")


def calculate_simple_interest(principal, rate, time):
    _validate_inputs(principal, rate, time)
    # Standard formula: I = P * R * T / 100, since the rate arrives as a percentage
    return float(principal) * float(rate) * int(time) / 100.0


def total_amount(principal, rate, time):
    # The closing balance is the capital plus everything it earned
    return float(principal) + calculate_simple_interest(principal, rate, time)


def yearly_schedule(principal, rate, time):
    _validate_inputs(principal, rate, time)
    # With simple interest the yearly charge is constant, so compute it once
    per_year = calculate_simple_interest(principal, rate, 1)
    schedule = []
    for year in range(1, int(time) + 1):
        # Derive the balance from the original principal to avoid accumulating rounding error
        balance = float(principal) + per_year * year
        schedule.append((year, per_year, balance))
    return schedule


def format_schedule(principal, rate, time, currency="$"):
    rows = yearly_schedule(principal, rate, time)
    lines = [f"Principal {currency}{principal:,.2f} at {rate}% for {int(time)} year(s)"]
    lines.append(f"{'Year':>4} {'Interest':>12} {'Balance':>14}")
    for year, interest, balance in rows:
        lines.append(f"{year:>4} {currency + format(interest, ',.2f'):>12} "
                     f"{currency + format(balance, ',.2f'):>14}")
    interest_total = calculate_simple_interest(principal, rate, time)
    # A zero-year period produces no rows, so state the totals explicitly
    lines.append(f"Total interest: {currency}{interest_total:,.2f}")
    lines.append(f"Final amount:   {currency}{total_amount(principal, rate, time):,.2f}")
    return "\n".join(lines)


def main():
    cases = [(1000, 5, 2), (500, 2.5, 10), (2500, 7.25, 3)]
    for principal, rate, time in cases:
        print(format_schedule(principal, rate, time))
        print()


if __name__ == "__main__":
