class Queue:
    """A simple FIFO queue backed by a Python list."""

    def __init__(self, items=None):
        # The left end of the list is the front of the queue
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        # Appending is O(1) amortised, so the tail is the cheap end to grow
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            # An empty queue has nothing to hand back
            return None
        # pop(0) shifts the remaining elements, which is acceptable for a basic list-based queue
        return self._items.pop(0)

    def peek(self):
        # Look at the front without consuming it
        return self._items[0] if self._items else None

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "Queue(front -> {})".format(self._items)


def drain(queue):
    """Dequeue everything and return the items in the order they left the queue."""
    order = []
    while len(queue):
        # dequeue() only returns None once the queue is empty, and the loop guard prevents that
        order.append(queue.dequeue())
    return order


def parse_commands(text):
    """Turn a whitespace-separated command string into (operation, argument) pairs."""
    tokens = text.split()
    commands = []
    index = 0
    while index < len(tokens):
        word = tokens[index]
        if word == "enqueue":
            # The value to push follows the keyword, so it must be present
            if index + 1 >= len(tokens):
                raise ValueError("enqueue is missing its argument")
            commands.append(("enqueue", tokens[index + 1]))
            index += 2
        elif word == "dequeue":
            commands.append(("dequeue", None))
            index += 1
        else:
            raise ValueError("unknown command: {}".format(word))
    return commands


def run_commands(text):
    """Execute a command script and report the result of every dequeue."""
    queue = Queue()
    results = []
    for operation, argument in parse_commands(text):
        if operation == "enqueue":
            queue.enqueue(argument)
        else:
            # None here genuinely means "the queue was empty"
            results.append(queue.dequeue())
    return queue, results


def main():
    script = "enqueue a enqueue b dequeue enqueue c dequeue dequeue dequeue"
    queue, results = run_commands(script)
    for step, value in enumerate(results, start=1):
        # Distinguish a real item from the empty-queue signal in the report
        label = "empty" if value is None else repr(value)
        print("dequeue #{}: {}".format(step, label))
    print("remaining:", queue)

    numbers = Queue([1, 2, 3])
    numbers.enqueue(4)
    # Draining shows that insertion order is preserved
    print("drained:", drain(numbers))


if __name__ == "__main__":
    main()

