        if is_plausible(address):
            results.append(address)
    return results


def unique_emails(text):
    seen = set()
    result = []
    for address in extract_emails(text):
        # Domains are case-insensitive and mailboxes are in practice too.
        key = address.lower()
        if key not in seen:
            seen.add(key)
            result.append(address)
    return result


