def _validate_2x2(matrix, name):
    # A matrix must be a sequence of rows, not a scalar or a string
    if not isinstance(matrix, (list, tuple)):
        raise TypeError(name + " must be a list of lists")
    # Exactly two rows are required for a 2x2 matrix
    if len(matrix) != 2:
        raise ValueError(name + " must have exactly 2 rows")
    for index, row in enumerate(matrix):
        # Each row itself has to be a sequence of two numbers
        if not isinstance(row, (list, tuple)):
            raise TypeError("%s row %d must be a list" % (name, index))
        if len(row) != 2:
            raise ValueError("%s row %d must have exactly 2 columns" % (name, index))
        for value in row:
            # Booleans are instances of int, but they are not meaningful entries here
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("%s contains a non-numeric entry: %r" % (name, value))


def multiply_2x2_matrices(matrix_a, matrix_b):
    # Reject malformed input before touching any element
    _validate_2x2(matrix_a, "matrix_a")
    _validate_2x2(matrix_b, "matrix_b")

    a00, a01 = matrix_a[0][0], matrix_a[0][1]
    a10, a11 = matrix_a[1][0], matrix_a[1][1]
    b00, b01 = matrix_b[0][0], matrix_b[0][1]
    b10, b11 = matrix_b[1][0], matrix_b[1][1]

    # Each result entry is the dot product of a row of A with a column of B
    return [
        [a00 * b00 + a01 * b10, a00 * b01 + a01 * b11],
        [a10 * b00 + a11 * b10, a10 * b01 + a11 * b11],
    ]


def format_matrix(matrix):
    # Render every entry first so that the column width can be shared
    cells = [[format(value, "g") for value in row] for row in matrix]
    width = max(len(text) for row in cells for text in row)
    lines = []
    for row in cells:
        # Right-align the numbers so the two rows line up visually
        lines.append("[ " + "  ".join(text.rjust(width) for text in row) + " ]")
    return "\n".join(lines)


def describe_product(matrix_a, matrix_b):
    product = multiply_2x2_matrices(matrix_a, matrix_b)
    left = format_matrix(matrix_a).splitlines()
    right = format_matrix(matrix_b).splitlines()
    result = format_matrix(product).splitlines()
    report = []
    for line_index in range(2):
        # The multiplication sign and equals sign belong on the first row only
        separator = " x " if line_index == 0 else "   "
        equals = " = " if line_index == 0 else "   "
        report.append(left[line_index] + separator + right[line_index] + equals + result[line_index])
    return "\n".join(report)


def main():
    pairs = [
        ([[1, 2], [3, 4]], [[5, 6], [7, 8]]),
        ([[1, 0], [0, 1]], [[10, 20], [30, 40]]),
    ]
    for matrix_a, matrix_b in pairs:
        print(describe_product(matrix_a, matrix_b))
        # Keep an empty line between consecutive reports
        print()


if __name__ == "__main__":
    main()

