import os
import sys


def count_words_in_file(filepath):
    total = 0
    # Stream the file line by line so that huge files never have to fit in memory
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            # split() with no argument collapses runs of spaces, tabs and newlines
            total += len(line.split())
    return total


def count_lines_in_file(filepath):
    with open(filepath, "r", encoding="utf-8") as handle:
        # Iterating a text handle yields one item per newline-terminated line
        return sum(1 for _ in handle)


def longest_word_in_file(filepath):
    longest = ""
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            for word in line.split():
                # Strict comparison keeps the first of several equally long words
                if len(word) > len(longest):
                    longest = word
    return longest


def format_report(filepath):
    words = count_words_in_file(filepath)
    lines = count_lines_in_file(filepath)
    longest = longest_word_in_file(filepath)
    parts = [
        "file: %s" % filepath,
        "lines: %d" % lines,
        "words: %d" % words,
    ]
    # An empty file has no longest word, so that field is simply omitted
    if longest:
        parts.append("longest word: %s (%d chars)" % (longest, len(longest)))
    return "\n".join(parts)


def main(argv):
    # Without command line arguments fall back to the sample file from the task
