def reverse_string(input_string):
    # The public contract is string-in / string-out, so reject other types early.
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str, got %s" % type(input_string).__name__)
    # Slicing with a negative step copies the characters from the end backwards.
    return input_string[::-1]


def reverse_words(sentence):
    # Splitting on arbitrary whitespace drops empty fragments automatically.
    words = sentence.split()
    # Each individual word is reversed, but the word order itself is preserved.
    return " ".join(reverse_string(word) for word in words)


def normalize_for_palindrome(text):
    # Palindrome checks should ignore punctuation, spacing and letter case.
    return "".join(ch.lower() for ch in text if ch.isalnum())


def is_palindrome(text):
    normalized = normalize_for_palindrome(text)
    return normalized == reverse_string(normalized)


def longest_palindromic_suffix(text):
    # Start with the whole string and shrink from the left until a suffix matches
    # its own reversal, which makes the first hit the longest such suffix.
    for start in range(len(text)):
        candidate = text[start:]
        if candidate == reverse_string(candidate):
            return candidate
    # An empty string is trivially a palindrome, which covers the empty input.
    return ""


def describe(text):
    # Build a one-line human readable report for a single input string.
    parts = ["%r -> %r" % (text, reverse_string(text))]
    # Only mention word-wise reversal when it actually differs from the plain one.
    flipped_words = reverse_words(text)
    if flipped_words != reverse_string(text):
        parts.append("words: %r" % flipped_words)
    if is_palindrome(text):
        parts.append("palindrome")
    else:
        # Reporting the palindromic tail is only interesting for non-palindromes.
        suffix = longest_palindromic_suffix(text)
        if len(suffix) > 1:
            parts.append("palindromic suffix: %r" % suffix)
    return " | ".join(parts)


def main():
    samples = [
        "hello",
        "Python",
        "never odd or even",
        "A man, a plan, a canal: Panama",
        "reverse these words",
        "abcdefg",
    ]
    for sample in samples:
        print(describe(sample))


