# Utilities for detecting overlaps in a schedule of events.


def _validate_event(event):
    # Accept any two-element sequence but normalise it to a plain tuple
    if not isinstance(event, (tuple, list)) or len(event) != 2:
        raise ValueError("an event must be a (start_time, end_time) pair")
    start, end = event
    # bool is a subclass of int, so reject it before the integer check
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError("event times must be integers")
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers")
    if start > end:
        raise ValueError("event start time must not be after its end time")
    return start, end


def check_event_overlap(event1, event2):
    # True when the two events share at least one minute of time
    start1, end1 = _validate_event(event1)
    start2, end2 = _validate_event(event2)
    # Touching intervals such as (10, 15) and (15, 20) count as separate: the
    # end time is exclusive, so strict inequalities are used on both sides.
    return start1 < end2 and start2 < end1


def find_all_overlaps(events):
    # Collect the index pairs of every clashing event in a schedule
    times = [_validate_event(event) for event in events]
    # Sorting by start time lets the scan stop as soon as an event begins
    # after the currently inspected one has already finished.
    order = sorted(range(len(times)), key=lambda i: times[i])
    clashes = []
    for pos, i in enumerate(order):
        end_i = times[i][1]
        for j in order[pos + 1:]:
            if times[j][0] >= end_i:
                break
            clashes.append((min(i, j), max(i, j)))
    # Report pairs in input order so the output is predictable
    return sorted(clashes)


def format_time(minutes):
    # Render minutes-from-midnight as HH:MM, wrapping past a full day
    hours, mins = divmod(minutes % (24 * 60), 60)
    return "{:02d}:{:02d}".format(hours, mins)


def describe_schedule(events):
    # Build a human readable report of the clashes found in a schedule
    lines = []
    for i, j in find_all_overlaps(events):
        first, second = events[i], events[j]
        # The clashing window is the intersection of the two intervals
        overlap_start = max(first[0], second[0])
        overlap_end = min(first[1], second[1])
        lines.append(
            "Event {} ({}-{}) clashes with event {} ({}-{}) during {}-{}".format(
                i, format_time(first[0]), format_time(first[1]),
                j, format_time(second[0]), format_time(second[1]),
                format_time(overlap_start), format_time(overlap_end),
            )
        )
    if not lines:
        lines.append("No clashes found.")
    return "\n".join(lines)


def main():
    # A small day plan expressed in minutes from midnight
    day = [(540, 600), (570, 630), (660, 720), (700, 780), (1200, 1230)]
    print(describe_schedule(day))
    lunch = (720, 780)
    # Highlight which planned events the fixed lunch break would run into
    for index, event in enumerate(day):
        if check_event_overlap(event, lunch):
            print("Event {} runs into the lunch break".format(index))


if __name__ == "__main__":
    main()

