    order = sorted(range(len(times)), key=lambda i: times[i])
    clashes = []
    for pos, i in enumerate(order):
        end_i = times[i][1]
        for j in order[pos + 1:]:
            if times[j][0] >= end_i:
                break
            clashes.append((min(i, j), max(i, j)))
    # Informa los pares en el orden de entrada para que la salida sea predecible
    return sorted(clashes)


def format_time(minutes):
    # Representa los minutos desde medianoche como HH:MM, dando la vuelta al pasar un día completo
    hours, mins = divmod(minutes % (24 * 60), 60)
    return "{:02d}:{:02d}".format(hours, mins)


def describe_schedule(events):
    # Construye un informe legible por humanos de los conflictos encontrados en una agenda
    lines = []
    for i, j in find_all_overlaps(events):
        first, second = events[i], events[j]
        # La ventana en conflicto es la intersección de los dos intervalos
        overlap_start = max(first[0], second[0])
        overlap_end = min(first[1], second[1])
        lines.append(
            "Event {} ({}-{}) clashes with event {} ({}-{}) during {}-{}".format(
                i, format_time(first[0]), format_time(first[1]),
                j, format_time(second[0]), format_time(second[1]),
                format_time(overlap_start), format_time(overlap_end),
            )
        )
    if not lines:
        lines.append("No clashes found.")
    return "\n".join(lines)


def main():
    # Un pequeño plan del día expresado en minutos desde medianoche
    day = [(540, 600), (570, 630), (660, 720), (700, 780), (1200, 1230)]
    print(describe_schedule(day))
    lunch = (720, 780)
    # Destaca con qué eventos planificados chocaría la pausa fija para el almuerzo
    for index, event in enumerate(day):
        if check_event_overlap(event, lunch):
            print("Event {} runs into the lunch break".format(index))


if __name__ == "__main__":
    main()

