import math


# A triangle needs three strictly positive sides
def is_valid_triangle(a, b, c):
    sides = (a, b, c)
    if any(side <= 0 for side in sides):
        return False
    # Strict inequality: equality means the triangle collapses onto a line
    longest = max(sides)
    return sum(sides) - longest > longest


def triangle_area(a, b, c):
    if not is_valid_triangle(a, b, c):
        return 0.0
    s = (a + b + c) / 2.0
    radicand = s * (s - a) * (s - b) * (s - c)
    # Floating point noise can push an almost-degenerate product below zero
    if radicand <= 0.0:
        return 0.0
    return math.sqrt(radicand)


def classify(a, b, c):
    if not is_valid_triangle(a, b, c):
        return "not a triangle"
    sides = sorted((a, b, c))
    # Compare with a tolerance so 0.1 + 0.2 style sums still count as equal
    equal_pairs = sum(
        1 for x, y in ((sides[0], sides[1]), (sides[1], sides[2]))
        if math.isclose(x, y, rel_tol=1e-9, abs_tol=1e-12)
    )
    # Two equal adjacent pairs mean all three sides agree
    if equal_pairs == 2:
        return "equilateral"
    if equal_pairs == 1:
        return "isosceles"
    return "scalene"


# Accept both comma-separated and space-separated side lengths
def parse_sides(text):
    parts = text.replace(",", " ").split()
    # The caller must supply exactly three numbers, no more and no fewer
    if len(parts) != 3:
        raise ValueError("expected exactly three side lengths, got %d" % len(parts))
    return tuple(float(part) for part in parts)


# Build a one-line report for a single input line
def describe(text):
    a, b, c = parse_sides(text)
    area = triangle_area(a, b, c)
    kind = classify(a, b, c)
    return "sides %g, %g, %g -> %s, area %.4f" % (a, b, c, kind, area)


def main():
    samples = [
        "3 4 5",
        "1 1 10",
        "2, 2, 2",
        "5 5 8",
        "0 4 5",
        "1 2 3",
        "7 8 9.5",
        "4 5",
    ]
    for sample in samples:
        try:
            print(describe(sample))
        # Malformed input should not abort the whole report
        except ValueError as exc:
            print("skipping %r: %s" % (sample, exc))


if __name__ == "__main__":
    main()

