MAX_ELEMENTS = 8


def generate_permutations(lst):
    """Return a list containing every ordering of the elements in ``lst``."""
    # Only sequences that can be copied and sliced are acceptable inputs.
    if not isinstance(lst, (list, tuple)):
        raise TypeError(f"expected a list or tuple, got {type(lst).__name__}")
    # The empty input has exactly one ordering: the empty arrangement itself.
    if not (items := list(lst)):
        return [[]]
    if (count := len(items)) > MAX_ELEMENTS:
        raise ValueError(f"{count} elements would produce too many permutations")
    result = []
    for index, element in enumerate(items):
        remaining = items[:index] + items[index + 1:]
        # Each ordering of the remaining elements extends the chosen first item.
        for tail in generate_permutations(remaining):
            result.append([element] + tail)
    return result


def unique_permutations(lst):
    """Like ``generate_permutations`` but drop duplicates caused by equal items."""
    seen = set()
    unique = []
    for perm in generate_permutations(lst):
        # Tuples are hashable, so they serve as a signature for the ordering.
        if (key := tuple(perm)) not in seen:
            seen.add(key)
            unique.append(perm)
    return unique


def permutation_count(lst):
    """Number of orderings of ``lst``, computed as a plain factorial."""
    total = 1
    for factor in range(2, len(lst) + 1):
        total *= factor
    return total


def format_permutations(perms, per_line=4):
    """Render permutations as text, wrapping after ``per_line`` entries."""
    if per_line < 1:
        raise ValueError(f"per_line must be at least 1, got {per_line}")
    rendered = [f"({', '.join(repr(x) for x in perm)})" for perm in perms]
    lines = []
    start = 0
    # Slicing past the end yields an empty chunk, which terminates the loop.
    while (chunk := rendered[start:start + per_line]):
        lines.append("  ".join(chunk))
        start += per_line
    return "\n".join(lines)


def report(lst):
    """Print a short summary of the permutations of a single input list."""
    perms = generate_permutations(lst)
    print(f"input: {lst}")
    print(f"count: {len(perms)} (expected {permutation_count(lst)})")
    print(format_permutations(perms))
    distinct = unique_permutations(lst)
    # Only repeated elements collapse orderings, so report the amount removed.
    if (extra := len(perms) - len(distinct)):
        print(f"{extra} duplicate orderings removed:")
        print(format_permutations(distinct))
    print()


def main():
    for sample in [[1, 2], ['a'], [], [1, 2, 3], ['x', 'x', 'y']]:
        report(sample)


if __name__ == "__main__":
    main()

