def calculate_average(numbers):
    # An empty sample has no mean, so the task defines the result as 0.0
    if not numbers:
        return 0.0
    # float() guarantees a float result even when every element is an int
    return float(sum(numbers)) / len(numbers)


def parse_numbers(text):
    # Commas are treated as plain separators so both "1,2" and "1 2" work
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        try:
            values.append(float(token))
        except ValueError:
            # Re-raise with the offending token so the caller can report it
            raise ValueError("not a number: %r" % token)
    return values


def deviations(numbers):
    # Each value's signed distance from the mean of the whole sample
    mean = calculate_average(numbers)
    return [value - mean for value in numbers]


def largest_deviation(numbers):
    # max() needs a non-empty sequence, hence the guard for the empty sample
    if not numbers:
        return 0.0
    return max(deviations(numbers), key=abs)


def format_report(label, numbers):
    # Header first, then the summary figures, then one line per value
    lines = ["%s (%d value(s))" % (label, len(numbers))]
    lines.append("  average : %.4f" % calculate_average(numbers))
    # The widest gap from the mean is a cheap hint about spread
    lines.append("  spread  : %.4f" % largest_deviation(numbers))
    for value, delta in zip(numbers, deviations(numbers)):
        # A leading sign makes the direction of each deviation obvious
        lines.append("    %10.4f  (%+.4f)" % (value, delta))
    return "\n".join(lines)


def main():
    samples = [
        ("first example", "1, 2, 3, 4, 5"),
        ("second example", "10 20"),
        ("empty sample", ""),
        ("broken input", "4 5 six"),
    ]
    for label, raw in samples:
        try:
            numbers = parse_numbers(raw)
        except ValueError as exc:
            # Bad input should not stop the remaining data sets
            print("%s: skipped (%s)" % (label, exc))
            continue
        print(format_report(label, numbers))
        # Blank line keeps consecutive reports readable
        print()


if __name__ == "__main__":
    main()

