# Path joining utilities: build clean POSIX-style paths from loose components.


def _split_component(component):
    # A single component may itself carry separators, e.g. 'local/bin'.
    return [piece for piece in component.strip().split('/') if piece]


def _is_absolute(components):
    # Only the very first component can make the whole result absolute.
    heads = [component.strip() for component in components[:1]]
    return bool(heads) and heads[0].startswith('/')


def join_path_components(components):
    """Join path components with exactly one '/' between them."""
    if not isinstance(components, (list, tuple)):
        raise TypeError('components must be a list or tuple of strings')
    # Report every offending type at once instead of failing on the first.
    wrong = [type(component).__name__ for component in components
             if not isinstance(component, str)]
    if wrong:
        raise TypeError('path components must be strings, got: ' + ', '.join(wrong))

    parts = [piece for component in components for piece in _split_component(component)]
    joined = '/'.join(parts)
    if _is_absolute(components):
        # Keep the single leading separator that marks the filesystem root.
        return '/' + joined
    return joined


def normalize_path(path):
    """Resolve '.' and '..' inside an already joined path string."""
    absolute = path.startswith('/')
    resolved = []
    for piece in [part for part in path.split('/') if part and part != '.']:
        if piece != '..':
            resolved.append(piece)
        elif resolved and resolved[-1] != '..':
            resolved.pop()
        elif not absolute:
            # A relative path can still point outside its starting directory.
            resolved.append('..')

    normalized = '/'.join(resolved)
    if absolute:
        # Climbing above the root collapses back to the root itself.
        return '/' + normalized
    # An empty relative result refers to the current directory.
    return normalized or '.'


def describe(components):
    """Format one report line showing the raw input and both results."""
    joined = join_path_components(components)
    normalized = normalize_path(joined)
    return '{!r:<45} -> {!r:<28} (normalized: {!r})'.format(components, joined, normalized)


def main():
    samples = [
        ['usr', 'local', 'bin'],
        ['/', 'home', 'user', 'documents'],
        ['/var/', '/log/', 'nginx'],
        ['docs', '', 'chapter1', '/'],
        ['/etc', 'apache2', '..', 'ssl', '.', 'certs'],
    ]
    report = [describe(sample) for sample in samples]
    for line in report:
        print(line)


if __name__ == '__main__':
    main()

