def validate_inventory(inventory, threshold):
    # A mapping is required because stock levels are looked up by item name.
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item_name -> stock_level")
    # Booleans are a subclass of int, so they are rejected explicitly.
    if not isinstance(threshold, int) or isinstance(threshold, bool):
        raise TypeError("threshold must be an int")
    # A negative threshold can never be met by a non-negative stock level.
    if threshold < 0:
        raise ValueError("threshold must be zero or positive")
    for name, level in inventory.items():
        if not isinstance(name, str):
            raise TypeError("item names must be strings, got %r" % (name,))
        # Stock levels are counts, so floats and strings are not accepted.
        if not isinstance(level, int) or isinstance(level, bool):
            raise TypeError("stock level for %s must be an int" % name)
        if level < 0:
            raise ValueError("stock level for %s must not be negative" % name)


def get_restock_reminders(inventory, threshold):
    validate_inventory(inventory, threshold)
    # Strictly below the threshold: an item exactly at the threshold is fine.
    low_items = [name for name, level in inventory.items() if level < threshold]
    return sorted(low_items)


def restock_quantities(inventory, threshold):
    # Reuse the sorted reminder order so the report and the quantities agree.
    names = get_restock_reminders(inventory, threshold)
    return {name: threshold - inventory[name] for name in names}


def format_report(inventory, threshold):
    needed = restock_quantities(inventory, threshold)
    header = "Restock report (threshold = %d)" % threshold
    lines = [header, "-" * len(header)]
    # An empty result is worth stating explicitly rather than printing nothing.
    if not needed:
        lines.append("All %d item(s) are sufficiently stocked." % len(inventory))
        return "\n".join(lines)
    # Pad the names so the quantity columns line up.
    width = max(len(name) for name in needed)
    for name, amount in needed.items():
        lines.append("%-*s  have %2d, order %2d" % (width, name, inventory[name], amount))
    lines.append("Total units to order: %d" % sum(needed.values()))
    return "\n".join(lines)


def main():
    fruit_stand = {'apple': 5, 'banana': 12, 'orange': 3}
    groceries = {'milk': 1, 'bread': 0, 'eggs': 2}
    print(get_restock_reminders(fruit_stand, 5))
    print(get_restock_reminders(groceries, 3))
    print()
    print(format_report(fruit_stand, 5))
    print()
    print(format_report(groceries, 3))


if __name__ == "__main__":
    main()

