    # Sin ninguna ventana completa, toda la serie tiene promedios indefinidos.
    if not averages:
        return [(value, None) for value in data]
    # Los primeros window_size - 1 puntos preceden a la primera ventana completa.
    aligned = [(value, None) for value in data[:window_size - 1]]
    for value, average in zip(data[window_size - 1:], averages):
