from collections import Counter


def count_occurrences(items):
    # Hashable elements let us use the fast dictionary-based counter.
    try:
        return list(Counter(items).items())
    except TypeError:
        # Unhashable elements (lists, dicts, ...) need an equality-based scan.
        pairs = []
        for item in items:
            for index, (seen, count) in enumerate(pairs):
                if seen == item:
                    pairs[index] = (seen, count + 1)
                    break
            else:
                # First time this value is seen, so start its tally at one.
                pairs.append((item, 1))
        return pairs


def find_most_frequent_element(values):
    # An empty list has no most frequent element at all.
    if not values:
        return None
    best_element, best_count = None, 0
    for element, count in count_occurrences(values):
        # Strict comparison keeps the first winner, which resolves ties arbitrarily.
        if count > best_count:
            best_element, best_count = element, count
    return best_element


def frequency_ranking(values):
    pairs = count_occurrences(values)
    # Negating the count sorts descending while keeping insertion order for ties.
    return sorted(pairs, key=lambda pair: -pair[1])


def format_report(values):
    winner = find_most_frequent_element(values)
    if winner is None:
        return "empty list: no most frequent element"
    lines = ["input: {!r}".format(values)]
    total = len(values)
    for element, count in frequency_ranking(values):
        # Shares are expressed as a percentage of the whole input.
        share = 100.0 * count / total
        lines.append("  {!r}: {} ({:.1f}%)".format(element, count, share))
    lines.append("most frequent: {!r}".format(winner))
    return "\n".join(lines)


def main():
    samples = [
        [1, 3, 2, 1, 3, 1],
        ['a', 'b', 'b', 'c', 'a'],
        [],
        [[1, 2], [3], [1, 2]],
    ]
    for sample in samples:
        print(format_report(sample))
        # A blank line separates consecutive reports in the output.
        print()


if __name__ == "__main__":
    main()

