# Character frequency utilities: counting, ranking and reporting.


def character_frequency(text):
    # Reject non-string input early so callers get a clear error instead of a
    # confusing failure deep inside the counting loop.
    if not isinstance(text, str):
        raise TypeError("character_frequency() expects a string")

    counts = {}
    for char in text:
        # Whitespace separates words in inputs like 'Hello World', so it is
        # skipped rather than counted as data.
        if char.isspace():
            continue
        # Folding the case makes 'H' and 'h' accumulate into the same bucket.
        key = char.lower()
        counts[key] = counts.get(key, 0) + 1
    return counts


def most_common(counts, limit=3):
    # Sort by descending count, breaking ties alphabetically so that the
    # ranking is deterministic across runs.
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def total_characters(counts):
    return sum(counts.values())


def format_report(text, limit=3):
    counts = character_frequency(text)
    lines = ["Text: %r" % text]

    # A whitespace-only text produces no buckets, so there is nothing to rank.
    if not counts:
        lines.append("  no countable characters")
        return "\n".join(lines)

    total = total_characters(counts)
    lines.append("  distinct characters: %d" % len(counts))
    lines.append("  counted characters : %d" % total)

    for char, count in most_common(counts, limit):
        share = 100.0 * count / total
        # Percentages are rounded to one decimal to keep the columns narrow.
        lines.append("  %r -> %d (%.1f%%)" % (char, count, share))

    repeated = [char for char, count in sorted(counts.items()) if count > 1]
    if repeated:
        lines.append("  repeated: " + ", ".join(repeated))
    return "\n".join(lines)


def main():
    samples = ["Hello World", "Python", "Mississippi River", "   "]

    for sample in samples:
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

