def fibonacci_sequence(n):
    """Return a list with the first `n` numbers of the Fibonacci sequence."""
    # Reject inputs that cannot describe a count of terms at all.
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    sequence = []
    current, following = 0, 1
    for _ in range(n):
        sequence.append(current)
        # Shift the sliding window one step forward along the sequence.
        current, following = following, current + following
    return sequence


def is_fibonacci(value):
    """Tell whether a non-negative integer appears in the Fibonacci sequence."""
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise ValueError("value must be a non-negative integer")

    current, following = 0, 1
    # Generate terms until we reach or pass the candidate value.
    while current < value:
        current, following = following, current + following
    return current == value


def golden_ratio_estimates(sequence):
    """Return the ratios between consecutive terms, skipping divisions by zero."""
    ratios = []
    for previous, nxt in zip(sequence, sequence[1:]):
        # The very first pair starts with 0, which has no usable ratio.
        if previous == 0:
            continue
        ratios.append(nxt / previous)
    return ratios


def format_report(n):
    """Build a short human-readable report about the first `n` Fibonacci numbers."""
    sequence = fibonacci_sequence(n)
    lines = ["First {} Fibonacci number(s): {}".format(n, sequence)]

    # An empty request has no sum, no maximum and no ratios to report.
    if not sequence:
        lines.append("Nothing to summarise.")
        return "\n".join(lines)

    lines.append("Sum of terms: {}".format(sum(sequence)))
    lines.append("Largest term: {}".format(sequence[-1]))

    ratios = golden_ratio_estimates(sequence)
    if ratios:
        # The last ratio is the closest available approximation of phi.
        lines.append("Golden ratio estimate: {:.8f}".format(ratios[-1]))
    else:
        lines.append("Golden ratio estimate: not enough terms.")
    return "\n".join(lines)


def main():
    for count in (1, 5, 12):
        print(format_report(count))
        print("-" * 40)

    # Membership queries exercise the sequence from the opposite direction.
    for candidate in (0, 4, 21, 100):
        verdict = "is" if is_fibonacci(candidate) else "is not"
        print("{} {} a Fibonacci number".format(candidate, verdict))


if __name__ == "__main__":
    main()

