# Count trailing zeros in n! without computing the factorial itself.
# The number of trailing zeros equals the exponent of 5 in the prime
# factorisation of n!, because factors of 2 are always more plentiful.


def trailing_zeros_factorial(n):
    """Return the number of trailing zeros in n! for a non-negative int n."""
    if isinstance(n, bool) or not isinstance(n, int):
        # bool is a subclass of int, so it must be rejected explicitly
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    zeros = 0
    power = 5
    # Legendre's formula: sum of floor(n / 5^k) for k = 1, 2, 3, ...
    while power <= n:
        zeros += n // power
        power *= 5
    return zeros


def trailing_zeros_digits(n):
    """Reference implementation that inspects the digits of the real n!."""
    factorial = 1
    for k in range(2, n + 1):
        factorial *= k
    text = str(factorial)
    stripped = text.rstrip("0")
    # The difference in length is exactly the count of trailing zeros
    return len(text) - len(stripped)


def smallest_n_with_zeros(target):
    """Smallest n such that n! ends in exactly `target` zeros, or None."""
    if target < 0:
        raise ValueError("target must be non-negative")
    # Each multiple of 5 adds at least one zero, so 5 * target is an upper bound
    for n in range(0, 5 * target + 1):
        count = trailing_zeros_factorial(n)
        if count == target:
            return n
        if count > target:
            # Counts are non-decreasing, so the target was skipped entirely
            return None
    return None


def format_report(values):
    """Build aligned "n -> zeros" lines for the given iterable of n values."""
    values = list(values)
    width = max((len(str(v)) for v in values), default=1)
    lines = []
    for n in values:
        zeros = trailing_zeros_factorial(n)
        lines.append("%*d! ends in %d zero(s)" % (width, n, zeros))
    return "\n".join(lines)


def main():
    samples = [0, 1, 5, 10, 25, 100, 1000]
    print(format_report(samples))
