# Cuenta los ceros finales de n! sin calcular el factorial en sí.
# El número de ceros finales es igual al exponente de 5 en la
# factorización en primos de n!, porque los factores de 2 son siempre más abundantes.


def trailing_zeros_factorial(n):
    """Return the number of trailing zeros in n! for a non-negative int n."""
    if isinstance(n, bool) or not isinstance(n, int):
        # bool es una subclase de int, así que debe rechazarse explícitamente
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    zeros = 0
    power = 5
    # Fórmula de Legendre: suma de floor(n / 5^k) para k = 1, 2, 3, ...
    while power <= n:
        zeros += n // power
        power *= 5
    return zeros


def trailing_zeros_digits(n):
    """Reference implementation that inspects the digits of the real n!."""
    factorial = 1
    for k in range(2, n + 1):
        factorial *= k
    text = str(factorial)
    stripped = text.rstrip("0")
    # La diferencia de longitud es exactamente la cantidad de ceros finales
    return len(text) - len(stripped)


def smallest_n_with_zeros(target):
    """Smallest n such that n! ends in exactly `target` zeros, or None."""
    if target < 0:
        raise ValueError("target must be non-negative")
    # Cada múltiplo de 5 añade al menos un cero, así que 5 * target es una cota superior
    for n in range(0, 5 * target + 1):
        count = trailing_zeros_factorial(n)
        if count == target:
            return n
        if count > target:
            # Los recuentos son no decrecientes, así que el objetivo se omitió por completo
            return None
    return None


def format_report(values):
    """Build aligned "n -> zeros" lines for the given iterable of n values."""
    values = list(values)
    width = max((len(str(v)) for v in values), default=1)
    lines = []
    for n in values:
        zeros = trailing_zeros_factorial(n)
        lines.append("%*d! ends in %d zero(s)" % (width, n, zeros))
    return "\n".join(lines)


def main():
    samples = [0, 1, 5, 10, 25, 100, 1000]
    print(format_report(samples))
    # Comprueba la fórmula rápida contra la fuerza bruta en los casos pequeños
    for n in range(0, 30):
        assert trailing_zeros_factorial(n) == trailing_zeros_digits(n)
    print("formula verified for n < 30")
    for target in (1, 2, 5, 6):
        n = smallest_n_with_zeros(target)
        # Un resultado None significa que ningún factorial termina en exactamente esa cantidad de ceros
        if n is None:
            print("no factorial ends in exactly %d zeros" % target)
        else:
            print("smallest n with %d trailing zeros: %d" % (target, n))


if __name__ == "__main__":
    main()

