from math import isqrt


def proper_divisors(num):
    # Proper divisors are only defined here for positive integers
    if num < 1:
        raise ValueError("proper_divisors expects a positive integer")
    # 1 has no proper divisors at all, so the general loop below would be wrong for it
    if num == 1:
        return []
    divisors = {1}
    # Divisors come in pairs (d, num // d), so scanning up to sqrt(num) is enough
    for d in range(2, isqrt(num) + 1):
        if num % d == 0:
            divisors.add(d)
            divisors.add(num // d)
    return sorted(divisors)


def is_perfect_number(num):
    # Perfection is only defined for integers; booleans are rejected as well
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("is_perfect_number expects an int")
    # Zero and negatives have no proper divisor sum to compare against
    if num < 1:
        return False
    return sum(proper_divisors(num)) == num


def classify_number(num):
    aliquot = sum(proper_divisors(num))
    if aliquot == num:
        return "perfect"
    # An abundant number's divisors overshoot the number itself
    if aliquot > num:
        return "abundant"
    return "deficient"


def format_report(num):
    divisors = proper_divisors(num)
    aliquot = sum(divisors)
    # Keep the empty-divisor case readable instead of printing an empty sum
    shown = " + ".join(str(d) for d in divisors) if divisors else "(none)"
    label = classify_number(num)
    return f"{num:>5}: {shown} = {aliquot} -> {label}"


def perfect_numbers_up_to(limit):
    # A limit below 1 leaves nothing to scan
    if limit < 1:
        return []
    return [n for n in range(1, limit + 1) if is_perfect_number(n)]


def main():
