_EXHAUSTED = object()  # distinguishes "iterator finished" from a legitimate None value


def flatten_list(nested_list):
    """Return a flat list containing every non-list element of nested_list."""
    # Strings are iterable but would flatten into characters, so they are refused
    if not isinstance(nested_list, (list, tuple)):
        raise TypeError("flatten_list expects a list or tuple")
    flat = []
    # An explicit stack avoids recursion limits on deeply nested input
    stack = [iter(nested_list)]
    while stack:
        item = next(stack[-1], _EXHAUSTED)
        if item is _EXHAUSTED:
            # This level is fully consumed, so step back to the parent level
            stack.pop()
        elif isinstance(item, (list, tuple)):
            stack.append(iter(item))
        else:
            flat.append(item)
    return flat


def max_depth(nested_list):
    """Return the nesting depth, where a flat list has depth 1."""
    if not isinstance(nested_list, (list, tuple)):
        raise TypeError("max_depth expects a list or tuple")
    deepest = 1
    for item in nested_list:
        if isinstance(item, (list, tuple)):
            # A sublist contributes one extra level on top of its own depth
            deepest = max(deepest, 1 + max_depth(item))
    return deepest


def count_elements(nested_list):
    """Return how many leaf elements the nested list holds."""
    return len(flatten_list(nested_list))


def describe(nested_list):
    """Build a one-line report about a nested list and its flattened form."""
    flat = flatten_list(nested_list)
    depth = max_depth(nested_list)
    # Singular/plural wording keeps the report readable for depth 1
    level_word = "level" if depth == 1 else "levels"
    return "{0} -> {1} ({2} {3}, {4} elements)".format(
        nested_list, flat, depth, level_word, len(flat)
    )


def main():
    samples = [
        [1, [2, 3], 4, [5, [6]]],
        [1, 2, 3],
        [],
        [[[["deep"]]], "shallow"],
        [1, [None, [2, (3, 4)]]],
    ]
    for sample in samples:
        print(describe(sample))
    total = sum(count_elements(sample) for sample in samples)
    print("total leaf elements:", total)


if __name__ == "__main__":
    main()

