# Roman numeral utilities: conversion in both directions plus a small report.

# Value/symbol pairs ordered from largest to smallest, including the
# six subtractive forms (CM, CD, XC, XL, IX, IV) that Roman numerals use.
ROMAN_PAIRS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

# Single-letter values, used when reading a numeral back into an integer.
LETTER_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    """Convert an integer in [1, 3999] to its Roman numeral string."""
    # Reject booleans explicitly: bool is a subclass of int and would slip through.
    if isinstance(num, bool) or not isinstance(num, int):
        raise TypeError("int_to_roman expects an int, got %r" % type(num).__name__)
    # Classical Roman numerals have no zero and no standard form above MMMCMXCIX.
    if not 1 <= num <= 3999:
        raise ValueError("number out of range (1..3999): %d" % num)

    pieces = []
    remainder = num
    for value, symbol in ROMAN_PAIRS:
        # Integer division tells us how many times this symbol repeats.
        count, remainder = divmod(remainder, value)
        if count:
            pieces.append(symbol * count)
    return "".join(pieces)


def roman_to_int(roman):
    """Convert a Roman numeral string back to an integer."""
    text = roman.strip().upper()
    if not text:
        raise ValueError("empty numeral")

    total = 0
    previous = 0
    # Scanning right to left makes subtractive pairs easy: a smaller
    # letter standing left of a bigger one is subtracted instead of added.
    for letter in reversed(text):
        if letter not in LETTER_VALUES:
            raise ValueError("invalid Roman digit: %r" % letter)
        current = LETTER_VALUES[letter]
        if current < previous:
            total -= current
        else:
            total += current
            previous = current
    return total


def format_table(numbers):
    """Build aligned 'number = numeral' lines for the given numbers."""
    rendered = [(n, int_to_roman(n)) for n in numbers]
    # Pad the decimal column so the equals signs line up in the output.
    width = max(len(str(n)) for n, _ in rendered)
    lines = []
    for number, numeral in rendered:
        lines.append("%*d = %s" % (width, number, numeral))
    return lines


def main():
    samples = [4, 9, 58, 400, 1994, 2024, 3999]
    for line in format_table(samples):
        print(line)

    # Round-tripping every sample is a cheap sanity check on both directions.
    for number in samples:
        back = roman_to_int(int_to_roman(number))
        if back != number:
            raise AssertionError("round trip failed for %d (got %d)" % (number, back))
    print("round trip OK for %d values" % len(samples))


if __name__ == "__main__":
    main()

