class SimpleQueue:
    # A first-in, first-out queue backed by a plain Python list.

    def __init__(self, items=None):
        # The list is stored front-first, so index 0 is always the next item out.
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        # New arrivals go to the back of the line.
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            # An empty queue has no front item, so signal the misuse instead of returning None.
            raise IndexError("dequeue from an empty queue")
        # Removing index 0 keeps the FIFO ordering intact.
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            raise IndexError("peek into an empty queue")
        return self._items[0]

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "SimpleQueue({!r})".format(self._items)


def drain(queue):
    # Dequeue everything and return the items in the order they left the queue.
    order = []
    # Relying on is_empty() means we never trigger the IndexError from dequeue().
    while not queue.is_empty():
        order.append(queue.dequeue())
    return order


def serve_tickets(names, window_count):
    # Distribute waiting customers round-robin over a number of service windows.
    if window_count < 1:
        # Zero windows would make the distribution loop spin forever with nobody served.
        raise ValueError("window_count must be at least 1")
    waiting = SimpleQueue(names)
    windows = [[] for _ in range(window_count)]
    index = 0
    while not waiting.is_empty():
        # Each pass hands the current front customer to the next window in rotation.
        windows[index % window_count].append(waiting.dequeue())
        index += 1
    return windows


def format_assignments(windows):
    lines = []
    for number, served in enumerate(windows, start=1):
        # A window that received nobody still deserves a line in the report.
        body = ", ".join(served) if served else "(idle)"
        lines.append("Window {}: {}".format(number, body))
    return "\n".join(lines)


def main():
    q = SimpleQueue()
    q.enqueue(1)
    q.enqueue(2)
    print(q.dequeue())
    print(q.dequeue())
    try:
        q.dequeue()
    except IndexError as exc:
        # Third dequeue must fail because both numbers have already been served.
        print("error:", exc)

    customers = ["Ada", "Brendan", "Casey", "Dijkstra", "Erin"]
    print(format_assignments(serve_tickets(customers, 2)))
    # drain() shows the untouched arrival order for the same customer list.
    print("arrival order:", drain(SimpleQueue(customers)))


if __name__ == "__main__":
    main()

