    def __init__(self, items=None):
        # La lista se almacena con el frente primero, así que el índice 0 siempre es el próximo elemento en salir.
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        # Los nuevos que llegan van al final de la fila.
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            # Una cola vacía no tiene elemento al frente, así que señala el mal uso en vez de devolver None.
            raise IndexError("dequeue from an empty queue")
        # Eliminar el índice 0 mantiene intacto el orden FIFO.
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            raise IndexError("peek into an empty queue")
        return self._items[0]

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "SimpleQueue({!r})".format(self._items)


def drain(queue):
    # Saca todo de la cola y devuelve los elementos en el orden en que salieron de la cola.
    order = []
    # Confiar en is_empty() significa que nunca provocamos el IndexError de dequeue().
    while not queue.is_empty():
        order.append(queue.dequeue())
    return order


def serve_tickets(names, window_count):
